//! Scheduled and manually-triggered admin tasks.
//!
//! Each task implements `tasks::Task` and is registered by [`register_tasks`], which
//! `backend/main.rs` hands to `blob` as a `blob::startup::Extensions` hook. The dependency edge is
//! one-directional — `admintasks` -> `blob` — so nothing in `blob` may import this crate. Task
//! bodies are reached at runtime by string id through `TaskManager`; startup and admin-route
//! entry points are reached through the `Extensions` hooks assembled in `main.rs`.

// The default 128 is exhausted proving `Send` for the deeply nested `impl
// Future` chains `#[redis_cached]`-instrumented tasks (e.g. `push_results`)
// generate through their reqwest/hyper/h2 dependency futures — deep async
// call chains routinely need this bump, per rustc's own suggestion on the
// overflow error.
#![recursion_limit = "256"]

use std::sync::Arc;

use anyhow::Result;
use backfill_connected_fencer_results::BackfillConnectedFencerResults;
use delete_connected_backfill_bouts::DeleteConnectedBackfillBouts;
use migrate_bouts::MigrateBouts;
use push_results::PushResultsToDatabase;
use rebuild_standings_index::RebuildStandingsIndex;
use reconcile_inprogress_registrations::ReconcileInProgressRegistrations;
use refresh_british_rankings::RefreshBritishRankings;
use snapshot_standings_history::SnapshotStandingsHistory;
use tasks::{TaskManager, TaskSpecBuilder};
use unified_catalog_refresh::UnifiedCatalogRefresh;
use unified_identity_sweep::UnifiedIdentitySweep;

pub mod backfill_connected_fencer_results;
pub mod delete_connected_backfill_bouts;
pub mod migrate_bouts;
pub mod push_results;
pub mod rebuild_standings_index;
pub mod reconcile_inprogress_registrations;
pub mod refresh_british_rankings;
pub mod snapshot_standings_history;
pub mod unified_catalog_refresh;
pub mod unified_identity_sweep;

pub async fn register_tasks() -> Result<()> {
  let task_manager = TaskManager::get().await;
  rebuild_standings_index::register_fetcher()?;

  task_manager
    .add_task(
      TaskSpecBuilder::default()
        .description("Push results to database for registered tournaments")
        .short_name("push_results")
        .task(PushResultsToDatabase)
        .build()?,
    )
    .await?;

  task_manager
    .add_task(
      TaskSpecBuilder::default()
        .description("Refresh USA Fencing Unified rankings catalog")
        .short_name(unified_catalog_refresh::TASK_ID)
        .schedule(unified_catalog_refresh::SCHEDULE)
        .schedule_jitter_max_seconds(unified_catalog_refresh::MAX_SCHEDULE_JITTER_SECONDS)
        .heartbeat_id("U35jXzB4DKUERhpEVvTzmXvr")
        .on_outcome(Arc::new(unified_catalog_refresh::record_refresh_outcome))
        .task(UnifiedCatalogRefresh::normal())
        .build()?,
    )
    .await?;

  task_manager
    .add_task(
      TaskSpecBuilder::default()
        .description("Refresh British Fencing live ranking tables")
        .short_name(refresh_british_rankings::TASK_ID)
        .schedule(refresh_british_rankings::SCHEDULE)
        .schedule_jitter_max_seconds(refresh_british_rankings::MAX_SCHEDULE_JITTER_SECONDS)
        .task(RefreshBritishRankings)
        .build()?,
    )
    .await?;

  task_manager
    .add_task(
      TaskSpecBuilder::default()
        .description("Override Unified rankings catalog refresh cooldown")
        .short_name(unified_catalog_refresh::OVERRIDE_TASK_ID)
        .task(UnifiedCatalogRefresh::with_cooldown_override())
        .build()?,
    )
    .await?;

  // The identity half of the Unified catalog, deliberately on its own
  // schedule and its own budget — see `unified_identity_sweep` for why it
  // cannot live inside the refresh above. The explicit execution timeout is
  // the outer bound on a run whose own wall-clock budget
  // (`unified.identity_sweep_max_run_seconds`) should always bind first; it is
  // set well below the process-wide 30-minute ceiling so a wedged sweep frees
  // its slot before the next cadence rather than squatting on it.
  task_manager
    .add_task(
      TaskSpecBuilder::default()
        .description("Resolve Unified rankings identities against FencingTracker")
        .short_name(unified_identity_sweep::TASK_ID)
        .schedule(unified_identity_sweep::schedule())
        .execution_timeout(std::time::Duration::from_secs(
          flunge_config::CONF.unified.identity_sweep_max_run_seconds + 120,
        ))
        .task(UnifiedIdentitySweep)
        .build()?,
    )
    .await?;

  task_manager
    .add_task(
      TaskSpecBuilder::default()
        .description("Backfill historical bouts for newly connected fencers")
        .short_name("backfill_connected_fencer_results")
        .schedule("0 */5 * * * *")
        .task(BackfillConnectedFencerResults)
        .build()?,
    )
    .await?;

  task_manager
    .add_task(
      TaskSpecBuilder::default()
        .description("Delete bouts created by connected-fencer results backfill")
        .short_name("delete_connected_backfill_bouts")
        .task(DeleteConnectedBackfillBouts)
        .build()?,
    )
    .await?;

  task_manager
    .add_task(
      TaskSpecBuilder::default()
        .description("Rebuild standings lookup index")
        .short_name("rebuild_standings_index")
        .schedule("0 */15 * * * *")
        .task(RebuildStandingsIndex)
        .build()?,
    )
    .await?;

  task_manager
    .add_task(
      TaskSpecBuilder::default()
        .description("Migrate historical tournament matches into bouts")
        .short_name("migrate_bouts")
        .task(MigrateBouts)
        .build()?,
    )
    .await?;

  task_manager
    .add_task(
      TaskSpecBuilder::default()
        .description("Reconcile in-progress saber event registrations from USA Fencing")
        .short_name("reconcile_inprogress_registrations")
        .schedule("0 0 4 * * *")
        .task(ReconcileInProgressRegistrations)
        .build()?,
    )
    .await?;

  task_manager
    .add_task(
      TaskSpecBuilder::default()
        .description("Snapshot tracked-fencer standings history")
        .short_name(snapshot_standings_history::TASK_ID)
        .schedule(snapshot_standings_history::SCHEDULE)
        .schedule_jitter_max_seconds(snapshot_standings_history::MAX_SCHEDULE_JITTER_SECONDS)
        .execution_timeout(snapshot_standings_history::execution_timeout())
        .on_outcome(Arc::new(snapshot_standings_history::record_outcome))
        .task(SnapshotStandingsHistory)
        .build()?,
    )
    .await?;

  Ok(())
}

