//! One-shot lift of per-user British Fencing licences onto the shared
//! fencer-licence collection. Idempotent: a fencer that already has a
//! shared record is not overwritten.

use anyhow::Result;
use async_trait::async_trait;
use tasks::Task;
use tracing::info;

pub const TASK_ID: &str = "migrate_british_fencing_licences";

pub struct MigrateBritishFencingLicences;

#[async_trait]
impl Task for MigrateBritishFencingLicences {
  async fn execute(&self) -> Result<()> {
    info!(
      task = TASK_ID,
      "Starting per-user British Fencing licence migration"
    );
    let counts = blob::fencer_licence::migrate_per_user_licences().await?;
    info!(
      task = TASK_ID,
      adopted = counts.adopted,
      conflicted = counts.conflicted,
      skipped_already_shared = counts.skipped_already_shared,
      users_stripped = counts.users_stripped,
      "Per-user British Fencing licence migration completed"
    );
    Ok(())
  }
}

