#[serde(rename_all = "camelCase")]
struct TaskExecQuery {
  #[serde(default)]
  force_list_refresh: bool,
  /// Deliberate operator action for the Unified catalog cadence gate. This
  /// does not alter source-client egress limits or request budgets.
  #[serde(default)]
  override_cooldown: bool,
  /// Optional slot date (`YYYY-MM-DD`) for `snapshot_standings_history`.
  /// Defaults to the most recent scheduled Monday/Thursday slot. A value
  /// later than that slot is a 400.
  #[serde(default)]
  run_id: Option<String>,
}

async fn v2_admin_task_exec(
  Path(id): Path<String>,
  Query(query): Query<TaskExecQuery>,
  Extension(force_refresh_hooks): Extension<ForceRefreshHooks>,
) -> util::Result<StatusCode> {
  if query.run_id.is_some() && id != crate::standings_history::TASK_ID {
    return Err(util::MyError::BadRequest(
      "runId is only available for snapshot_standings_history".to_owned(),
    ));
  }
  if id == crate::standings_history::TASK_ID
    && let Some(ref run_id) = query.run_id
  {
    crate::standings_history::validate_run_id(run_id).map_err(util::MyError::BadRequest)?;
  }

  if query.override_cooldown {
    if id != "refresh_unified_catalog" {
      return Err(
        anyhow!("cooldown override is only available for the Unified catalog refresh").into(),
      );
    }
    if !TaskManager::get()
      .await
      .run_now_after_reserving("refresh_unified_catalog_override", || {})
      .await?
    {
      return Err(util::MyError::BadRequest(
        "Task 'refresh_unified_catalog_override' is already running".to_owned(),
      ));
    }
    return Ok(StatusCode::ACCEPTED);
  }

  let usa_fencing = if query.force_list_refresh && id == "usaf_sync" {
    Some(UsaFencingClient::get().await)
  } else {
    None
  };

  if !TaskManager::get()
    .await
    .run_now_after_reserving(&id, || {
      if let Some(usa_fencing) = usa_fencing {
        usa_fencing.force_list_refresh();
      }
      if query.force_list_refresh {
        force_refresh_hooks.run(&id);
      }
      if id == crate::standings_history::TASK_ID {
        crate::standings_history::set_exec_request(query.run_id.clone());
      }
    })
    .await?
  {
    return Err(util::MyError::BadRequest(format!(
      "Task '{id}' is already running"
    )));
  }

  Ok(StatusCode::ACCEPTED)
}

