#[derive(Embed)]
#[folder = "assets/"]
pub struct Asset;

impl Asset {
  /// Load and deserialize an embedded JSON asset, returning `T::default()` if the
  /// asset is missing or fails to deserialize.
  pub fn load_json_or_default<T: serde::de::DeserializeOwned + Default>(name: &str) -> T {
    match Asset::get(name) {
      Some(file) => serde_json::from_slice(file.data.as_ref()).unwrap_or_default(),
      None => T::default(),
    }
  }

  /// Load and deserialize an embedded JSON asset. Returns `Ok(None)` when the asset
  /// is missing and propagates any deserialization error.
  pub fn load_json<T: serde::de::DeserializeOwned>(name: &str) -> Result<Option<T>> {
    match Asset::get(name) {
      Some(file) => Ok(Some(serde_json::from_slice(file.data.as_ref())?)),
      None => Ok(None),
    }
  }
}

pub async fn run(extensions: Extensions) -> Result<()> {
  crate::tracing_init::init_tracing();
  let app_span = tracing::info_span!("app", env = %CONF.logs.server_variant);
  let _app_span_guard = app_span.enter();
  info!(event = "startup", "Backend is starting up");

  // Must run after `init_tracing()` above: a failure here is fatal to startup, and this is the
  // earliest point at which such a failure is actually observable to an operator (via the
  // tracing::error! below, captured by the file-based log pipeline) rather than silently lost to
  // stderr, which the log pipeline doesn't tail.
  if let Err(err) = DB.ensure_containers_exist().await {
    tracing::error!(error = ?err, "Failed to provision required Cosmos containers");
    return Err(err.context("Provisioning required Cosmos containers"));
  }

  // The one-shot per-user -> shared British Fencing licence migration is not run
  // automatically here: it does a full, uncached scan of the users container on
  // every invocation, which every replica would otherwise pay on every process
  // start, forever, blocking the bind below. It is triggered explicitly via the
  // `migrate_british_fencing_licences` admin task instead
  // (backend/admintasks/src/migrate_british_fencing_licences.rs).
  init_metrics();

  tracing::info!(
    bind_address = %CONF.server.bind_address,
    port = CONF.server.port,
    "Backend started; statusz ready"
  );

  let cors = build_cors_layer(&CONF.server.cors_allow_origin)?;

  // Initialize singleton services
  let _ = FtlClient::get();
  let _ = FencingTrackerClient::get().await;
  let _ = UsaFencingClient::get().await;

  // Register background tasks
  if !CONF.background_tasks.enabled {
    tracing::info!(
      background_tasks_enabled = CONF.background_tasks.enabled,
      "Background tasks disabled; registering tasks without automatic scheduling"
    );
  }
  UsaFencingClient::get().await.register_tasks().await?;
  FencingTrackerClient::get().await.register_tasks().await?;
  crate::v2::fencer::register_tasks().await?;
  notification::register_tasks().await?;
  gcal::register_tasks().await?;
  extensions.register_all_tasks().await?;
  crate::invitations::tasks::register_tasks().await?;

  TaskManager::get().await.start().await?;

  // Spawned (not awaited inline) so a multi-minute sweep never delays the rest of startup — the
  // check itself is a couple of fast Redis round trips plus a non-blocking spawn. Must run after
  // `start()` above, which is what assigns task UUIDs that immediate execution requires.
  extensions.spawn_post_start_jobs();

  let force_refresh_hooks = extensions.into_force_refresh_hooks();

  let admin_routes = RoutezRouter::new()
    .route_post("/admin/flushcache", v2_admin_flush_cache)
    .route_get("/admin/cache", v2_admin_cache_summary)
    .route_get("/admin/cache/{key}", v2_admin_cache_key)
    .route_get("/admin/caches", crate::admin_cache_api::v2_admin_caches_get)
    .route_get(
      "/admin/caches/{name}/entries/{key}",
      crate::admin_cache_api::v2_admin_cache_entry_get,
    )
    .route_post(
      "/admin/caches/{name}/invalidate",
      crate::admin_cache_api::v2_admin_cache_invalidate,
    )
    .route_get("/admin/tasks", v2_admin_tasks_get)
    .route_get("/admin/fencingtracker", v2_admin_fencingtracker_get)
    .route_get("/admin/unified-rankings", v2_admin_unified_rankings_get)
    .route_get(
      "/admin/standings-history",
      crate::standings_history::admin_status_handler,
    )
    .route_post("/admin/tasks/{id}/exec", v2_admin_task_exec)
    .route_get("/admin/users", v2_admin_users_get)
    .route_post(
      "/admin/users/{id}/capabilities",
      v2_admin_user_capabilities_put,
    )
    .route_post("/admin/users/{id}/groups", v2_admin_user_groups_put)
    .route_get("/admin/groups", v2_admin_groups_get)
    .route_get("/admin/flags", crate::admin_flags_api::v2_admin_flags_get)
    .route_post(
      "/admin/flags/{flag_key}",
      crate::admin_flags_api::v2_admin_flag_set,
    )
    .route_get(
      "/admin/capabilities/config",
      crate::admin_flags_api::v2_admin_capability_config_get,
    )
    .route_post(
      "/admin/capabilities/config/{capability}",
      crate::admin_flags_api::v2_admin_capability_config_set,
    );

  let (admin_router_inner, admin_route_info) = admin_routes.finish();
  let admin_router_inner = admin_router_inner
    .layer(Extension(force_refresh_hooks))
    .layer(middleware::from_fn(admin_middleware))
    .layer(middleware::from_fn(jwt_middleware));
  let admin_routes = RoutezRouter::from_parts(admin_router_inner, admin_route_info);

  let protected_routes = RoutezRouter::new()
    .route_get("/tournament", v2_tournament)
    .route_get("/tournament/{id}", v2_tournament_get)
    .route_get(
      "/tournament/{tournamentId}/event/{eventId}/registrations",
      v2_event_get_registrations,
    )
    .route_get("/tournament/{tournamentId}/event/{eventId}", v2_event_get)
    .route_patch("/tournament/{tournamentId}/event/{eventId}", v2_event_patch)
    .route_get("/fencer/{id}", v2_fencer_get)
    .route_post("/auth/google", v2_auth_google_post)
    .route_get("/user/{id}", v2_user)
    .route_patch("/user/{id}", v2_user_patch)
    .route_get("/user/{id}/authtokens", v2_user_auth_tokens)
    .route_post("/user/me/trackedfencers", v2_user_add_tracked_fencer)
    .route_delete(
      "/user/me/trackedfencers/{fencer_id}",
      v2_user_remove_tracked_fencer,
    )
    .route_get("/oauth/state", v2_oauth_state);

  let (protected_router_inner, protected_route_info) = protected_routes.finish();
  let protected_router_inner = protected_router_inner.layer(middleware::from_fn(jwt_middleware));
  let protected_routes = RoutezRouter::from_parts(protected_router_inner, protected_route_info);

  let public_routes = RoutezRouter::new()
    .route_get("/statusz", statusz)
    .route_get("/versionz", versionz)
    .route_get("/configz", configz)
    .route_get("/flagz", flagz)
    .route_get("/api/v2/oauth/redirect", v2_oauth_redirect);

  // Public v3 routes (no authentication required)
  let api_v3_public_routes = RoutezRouter::new()
    .nest("/auth", crate::v3::auth::rest::router())
    .nest("/view", crate::view::router())
    // Anonymous share-view read path: distinct paths under `/share` from the
    // authenticated owner router below, so both can nest the same prefix.
    // See docs/design-docs/private-results-share-links.md.
    .nest("/share", crate::share::view::router());

  // Protected v3 routes (authentication required)
  let api_v3_protected_routes = RoutezRouter::new()
    .nest("/view", crate::view::protected_router())
    .nest("/family", crate::family::api::router())
    .nest("/invitations", crate::invitations::api::router())
    .nest("/event-notes", crate::event_notes::api::router())
    .nest("/share", crate::share::api::router())
    .nest(
      "/manual-tournaments",
      crate::manual_tournaments::api::router(),
    )
    .nest("/user", crate::v3::user::rest::router());

  let (api_v3_protected_inner, api_v3_protected_info) = api_v3_protected_routes.finish();
  let api_v3_protected_inner = api_v3_protected_inner.layer(middleware::from_fn(jwt_middleware));
  let api_v3_protected_routes =
    RoutezRouter::from_parts(api_v3_protected_inner, api_v3_protected_info);

  let api_v3_routes = RoutezRouter::new()
    .merge(api_v3_public_routes)
    .merge(api_v3_protected_routes);

  let app_routes = RoutezRouter::new()
    .nest("/api/v2", protected_routes)
    .nest("/api/v2", admin_routes)
    .nest("/api/v3", api_v3_routes)
    .nest("/api/v2/usaf", crate::usafencing::api::rest::router())
    .nest(
      "/api/v2/fencingtracker",
      crate::fencingtracker::api::rest::router(),
    )
    .nest(
      "/api/v2/fencingtimelive",
      crate::fencingtimelive::api::rest::router(),
    )
    .merge(public_routes)
    .route_get("/routez", route_listing)
    .route_get("/requestz", requestz);

  let (app_router, mut all_routes) = app_routes.finish();
  all_routes.sort_by(|a, b| {
    a.path
      .cmp(&b.path)
      .then_with(|| a.method.as_str().cmp(b.method.as_str()))
  });

  let route_listing_data = Arc::new(all_routes);
  let request_log = RequestLog::new(REQUEST_LOG_CAPACITY);

  let app = app_router
    .layer(Extension(route_listing_data))
    .layer(Extension(request_log.clone()))
    .layer(cors)
    .layer(middleware::from_fn_with_state(
      request_log,
      request_log_middleware,
    ))
    .layer(
      TraceLayer::new_for_http()
        .make_span_with(|request: &Request<Body>| {
          let uri = redact_uri(&request.uri().to_string());
          tracing::span!(
            Level::INFO,
            "request",
            method = %request.method(),
            uri = %uri,
            version = ?request.version(),
            env = %CONF.logs.server_variant
          )
        })
        .on_response(DefaultOnResponse::new().level(Level::INFO)),
    );

  counter!(util::STARTUP).increment(1);

  let addr = SocketAddr::new(CONF.server.bind_address.parse().unwrap(), CONF.server.port);
  let listener = tokio::net::TcpListener::bind(addr).await?;

  axum::serve(listener, app).await?;

  Ok(())
}

