struct RedactedConf<'a>(&'a Conf);

impl Serialize for RedactedConf<'_> {
  fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
  where
    S: serde::Serializer,
  {
    let mut value = serde_json::to_value(self.0).map_err(serde::ser::Error::custom)?;
    json_redact::redact_secret_values(&mut value);
    value.serialize(serializer)
  }
}

fn decode_cache_entry(field: Option<String>, bytes: Vec<u8>) -> RedisEntry {
  match util::compression::brotli_decompress_json::<JsonValue>(&bytes) {
    Ok(json_value) => {
      let preview =
        serde_json::to_string_pretty(&json_value).unwrap_or_else(|_| json_value.to_string());
      RedisEntry {
        field,
        preview,
        json: Some(json_value),
      }
    }
    Err(_) => match String::from_utf8(bytes.clone()) {
      Ok(text) => match serde_json::from_str::<JsonValue>(&text) {
        Ok(json_value) => {
          let preview =
            serde_json::to_string_pretty(&json_value).unwrap_or_else(|_| json_value.to_string());
          RedisEntry {
            field,
            preview,
            json: Some(json_value),
          }
        }
        Err(_) => RedisEntry {
          field,
          preview: text,
          json: None,
        },
      },
      Err(_) => RedisEntry {
        field,
        preview: format!("base64:{}", BASE64_STANDARD.encode(bytes)),
        json: None,
      },
    },
  }
}

