async fn v2_admin_cache_summary() -> util::Result<Json<RedisCacheSummary>> {
  let connection = RedisCache::get()
    .await
    .get_connection()
    .ok_or_else(|| anyhow!("Redis connection not available"))?;
  let mut conn = connection;

  let all_keys = RedisCache::get().await.scan_keys(None).await?;
  let mut summaries = Vec::new();

  for key_name in all_keys {
    if let Some(summary) = load_key_summary(&mut conn, &key_name).await? {
      summaries.push(summary);
    }
  }

  Ok(Json(RedisCacheSummary { keys: summaries }))
}

