async fn load_key_summary(
  conn: &mut MultiplexedConnection,
  key_name: &str,
) -> util::Result<Option<RedisKeySummary>> {
  let key_type: String = redis::cmd("TYPE").arg(key_name).query_async(conn).await?;

  if key_type == "none" {
    return Ok(None);
  }

  let length = match key_type.as_str() {
    "hash" => Some(redis::cmd("HLEN").arg(key_name).query_async(conn).await?),
    "set" => Some(redis::cmd("SCARD").arg(key_name).query_async(conn).await?),
    "zset" => Some(redis::cmd("ZCARD").arg(key_name).query_async(conn).await?),
    "list" => Some(redis::cmd("LLEN").arg(key_name).query_async(conn).await?),
    "string" => Some(redis::cmd("STRLEN").arg(key_name).query_async(conn).await?),
    _ => None,
  };

  Ok(Some(RedisKeySummary {
    name: key_name.to_string(),
    kind: key_type,
    length,
  }))
}

async fn load_key_detail(
  conn: &mut MultiplexedConnection,
  key_name: &str,
) -> util::Result<Option<RedisKeyDetail>> {
  let summary = match load_key_summary(conn, key_name).await? {
    Some(summary) => summary,
    None => return Ok(None),
  };

  let RedisKeySummary { name, kind, length } = summary;

  let entries = match kind.as_str() {
    "hash" => {
      let raw_entries: Vec<(String, Vec<u8>)> =
        redis::cmd("HGETALL").arg(&name).query_async(conn).await?;
      raw_entries
        .into_iter()
        .map(|(field, value)| decode_cache_entry(Some(field), value))
        .collect::<Vec<_>>()
    }
    "set" => {
      let members: Vec<String> = redis::cmd("SMEMBERS").arg(&name).query_async(conn).await?;
      members
        .into_iter()
        .map(|member| RedisEntry {
          field: None,
          preview: member,
          json: None,
        })
        .collect::<Vec<_>>()
    }
    "zset" => {
      let raw: Vec<(String, f64)> = redis::cmd("ZRANGE")
        .arg(&name)
        .arg(0)
        .arg(-1)
        .arg("WITHSCORES")
        .query_async(conn)
        .await?;
      raw
        .into_iter()
        .map(|(member, score)| RedisEntry {
          field: Some(member.clone()),
          preview: member.clone(),
          json: Some(json!({ "member": member, "score": score })),
        })
        .collect::<Vec<_>>()
    }
    "list" => {
      let raw: Vec<Vec<u8>> = redis::cmd("LRANGE")
        .arg(&name)
        .arg(0)
        .arg(-1)
        .query_async(conn)
        .await?;
      raw
        .into_iter()
        .enumerate()
        .map(|(idx, value)| decode_cache_entry(Some(idx.to_string()), value))
        .collect::<Vec<_>>()
    }
    "string" => {
      let value: Vec<u8> = redis::cmd("GET").arg(&name).query_async(conn).await?;
      vec![decode_cache_entry(None, value)]
    }
    _ => Vec::new(),
  };

  Ok(Some(RedisKeyDetail {
    name,
    kind,
    length,
    entries,
  }))
}

