async fn v2_user_remove_tracked_fencer(
  Path(fencer_id): Path<String>,
  Extension(user): Extension<AuthenticatedUser>,
) -> util::Result<StatusCode> {
  // Revoke live share links *before* dropping the tracked-fencer edge. The
  // edge is the authorization to share; if revoke fails after removal, a
  // retry cannot recover because `remove_tracked_fencer` then returns
  // "Fencer not being tracked". A removal failure after a successful revoke
  // leaves already-revoked links, which is harmless. Plan links are pruned
  // (narrowed, or revoked outright if the prune empties their fencer set)
  // rather than always revoked, since a plan link's remaining fencers were
  // independently authorized at mint.
  match fencer_id.parse::<ViewTypedId<FencerId>>() {
    Ok(parsed_fencer_id) => {
      let owner_user_id = ViewTypedId::<UserId>::database(&user.user.id);
      crate::share::revoke_for_disconnected_fencer(&owner_user_id, &parsed_fencer_id)
        .await
        .map_err(anyhow::Error::from)?;
      crate::share::plan::prune_disconnected_fencer(&owner_user_id, &parsed_fencer_id)
        .await
        .map_err(anyhow::Error::from)?;
      // Strip the fencer from every registeredFencerIds on the owner's manual
      // tournaments *before* the edge is deleted too - same "revoke before
      // disconnect" ordering as the share-link revoke above.
      crate::manual_tournaments::strip_disconnected_fencer(&owner_user_id, &parsed_fencer_id)
        .await
        .map_err(anyhow::Error::from)?;
    }
    Err(_) => {
      warn!(
        fencer_id,
        "Skipping share-link revoke, plan-link prune, and manual-tournament strip on tracked-fencer removal: fencer id is unparseable"
      );
    }
  }

  v2::user::remove_tracked_fencer(&user.user.id, &fencer_id).await?;

  Ok(StatusCode::NO_CONTENT)
}

