fn oauth_success_redirect_url(return_to: Option<&str>) -> String {
  let allowed_origins = parse_allowed_origins(&CONF.server.cors_allow_origin);
  if let Some(origin) = return_to
    && is_allowed_frontend_origin(origin, &allowed_origins)
  {
    return format!("{}/settings/account", origin.trim_end_matches('/'));
  }
  CONF.auth.oauth_success_redirect_uri.clone()
}

/// Public endpoint that Google redirects to after OAuth consent.
/// The state parameter contains a signed JWT with the user ID.
async fn v2_oauth_redirect(
  Query(oauth_query): Query<OAuthQuery>,
) -> util::Result<impl IntoResponse> {
  // Validate the signed state token and extract callback details.
  let claims = validate_oauth_state_claims(&oauth_query.state)
    .map_err(|e| anyhow!("Invalid OAuth state: {}", e))?;
  let user_id = claims.sub;

  oauth_and_store(&user_id, &oauth_query.code).await?;

  let success_redirect = oauth_success_redirect_url(claims.return_to.as_deref());
  Ok(Redirect::temporary(&success_redirect))
}

#[derive(Serialize)]
struct OAuthStateResponse {
  state: String,
}

/// Protected endpoint to generate a signed state token for OAuth flow.
/// The frontend calls this before redirecting to Google.
async fn v2_oauth_state(
  Query(query): Query<OAuthStateQuery>,
  Extension(user): Extension<AuthenticatedUser>,
) -> util::Result<Json<OAuthStateResponse>> {
  let allowed_origins = parse_allowed_origins(&CONF.server.cors_allow_origin);
  let requested_return_to = query.return_to.as_deref().and_then(|origin| {
    if is_allowed_frontend_origin(origin, &allowed_origins) {
      Some(origin)
    } else {
      None
    }
  });

  let state = generate_oauth_state_with_return_to(&user.user.id, requested_return_to)?;
  Ok(Json(OAuthStateResponse { state }))
}

// Middleware function to verify the JWT and inject `AuthenticatedUser`
async fn jwt_middleware(
  mut req: Request<Body>,
  next: Next,
) -> core::result::Result<impl IntoResponse, StatusCode> {
  // Check for Clerk bearer token
  if let Some(clerk_user) = crate::v3::auth::rest::authenticated_clerk_user(req.headers()).await {
    let authed = AuthenticatedUser { user: clerk_user };
    req.extensions_mut().insert(authed);
    return Ok(next.run(req).await);
  }

  // No valid authentication found
  Err(StatusCode::UNAUTHORIZED)
}

// Middleware function to verify the user has Administrator capability
async fn admin_middleware(
  req: Request<Body>,
  next: Next,
) -> core::result::Result<impl IntoResponse, StatusCode> {
  // Get the authenticated user from the request extensions (added by jwt_middleware)
  if let Some(authed) = req.extensions().get::<AuthenticatedUser>() {
    // Check if user has Administrator capability
    if authed
      .user
      .fields
      .capabilities
      .contains(&v2::model::UserCapability::Administrator)
    {
      return Ok(next.run(req).await);
    }
  }

  // User doesn't have admin capability
