use anyhow::{Result, anyhow};
use chrono::{Duration, Utc};
use jsonwebtoken::{DecodingKey, EncodingKey, Header, Validation, decode, encode};
use reqwest::{Client, StatusCode};
use serde::{Deserialize, Serialize};
use tracing::info;

use crate::db::DB;
use crate::v2::model::{Account, AccountFields, GoogleAuthInfo, ServiceConnection, User};
use flunge_config::CONF;
use util::eq;

fn create_auth_http_client() -> Client {
  http_helper::create_http_client_builder()
    .build()
    .expect("auth HTTP client configuration is valid")
}

/// Claims for the OAuth state token
#[derive(Debug, Serialize, Deserialize)]
pub struct OAuthStateClaims {
  /// User ID
  pub sub: String,
  /// Expiration time (Unix timestamp)
  pub exp: i64,
  /// Optional frontend origin to return to after OAuth callback.
  #[serde(default)]
  pub return_to: Option<String>,
}

/// Generate a signed state token for OAuth flow containing the user ID and an
/// optional frontend origin to return to after the callback.
pub fn generate_oauth_state_with_return_to(
  user_id: &str,
  return_to: Option<&str>,
) -> Result<String> {
  generate_oauth_state_with_secret(user_id, return_to, &CONF.auth.secret_clerk_key)
}

fn generate_oauth_state_with_secret(
  user_id: &str,
  return_to: Option<&str>,
  secret: &str,
) -> Result<String> {
  let expiration = Utc::now() + Duration::minutes(10);
  let claims = OAuthStateClaims {
    sub: user_id.to_string(),
    exp: expiration.timestamp(),
    return_to: return_to.map(str::to_string),
  };

  let token = encode(
    &Header::default(),
    &claims,
    &EncodingKey::from_secret(secret.as_bytes()),
  )?;

  Ok(token)
}

/// Validate and decode the OAuth state token, returning its claims
pub fn validate_oauth_state_claims(state: &str) -> Result<OAuthStateClaims> {
  validate_oauth_state_claims_with_secret(state, &CONF.auth.secret_clerk_key)
}

fn validate_oauth_state_claims_with_secret(state: &str, secret: &str) -> Result<OAuthStateClaims> {
  let token_data = decode::<OAuthStateClaims>(
    state,
    &DecodingKey::from_secret(secret.as_bytes()),
    &Validation::default(),
  )?;

  Ok(token_data.claims)
}

const CLIENT_ID: &str = "109396758206-f0akr87bh5cvv7ai827ghcjb9qbdpvpu.apps.googleusercontent.com";

#[derive(Deserialize)]
pub struct AuthCodeRequest {
  pub code: String,
}

#[derive(Deserialize, Serialize, Clone, Debug, Hash, PartialEq, Eq)]
pub struct TokenResponse {
  pub access_token: String,
  refresh_token: Option<String>,
  expires_in: u64,
  scope: String,
  token_type: String,
  id_token: Option<String>,
}

#[derive(Deserialize)]
struct GoogleOAuthErrorResponse {
  error: String,
}

enum RefreshAuthError {
  InvalidGrant,
  Other(anyhow::Error),
}

pub async fn google_auth(req: AuthCodeRequest) -> Result<TokenResponse> {
  info!("Requesting google auth tokens...");

  let client = create_auth_http_client();
  let params = [
    ("client_id", CLIENT_ID),
    (
      "client_secret",
      CONF.google_api.secret_googleapi_key.as_str(),
    ),
    ("code", req.code.as_str()),
    ("grant_type", "authorization_code"),
    ("redirect_uri", &CONF.auth.oauth_redirect_uri),
  ];

  let token_response = client
    .post("https://oauth2.googleapis.com/token")
    .form(&params)
    .send()
    .await?;

  if !token_response.status().is_success() {
    let status = token_response.status();
    let text = token_response.text().await.unwrap_or_default();
    return Err(anyhow!("Failed to get token: Status {}: {}", status, text));
  }

  let text = token_response.text().await?;
  Ok(serde_json::from_str(&text)?)
}

async fn google_refresh_auth(
  old_response: &TokenResponse,
) -> std::result::Result<TokenResponse, RefreshAuthError> {
  if let Some(refresh_token) = &old_response.refresh_token {
    let client = create_auth_http_client();
    let params = [
      ("client_id", CLIENT_ID),
      (
        "client_secret",
        CONF.google_api.secret_googleapi_key.as_str(),
      ),
      ("refresh_token", refresh_token.as_str()),
      ("grant_type", "refresh_token"),
    ];

    let token_response = client
      .post("https://oauth2.googleapis.com/token")
      .form(&params)
      .send()
      .await
      .map_err(|error| RefreshAuthError::Other(error.into()))?;

    if !token_response.status().is_success() {
      let status = token_response.status();
      let text = token_response.text().await.unwrap_or_default();
      if is_invalid_grant_response(status, &text) {
        return Err(RefreshAuthError::InvalidGrant);
      }
      return Err(RefreshAuthError::Other(anyhow::anyhow!(
        "Failed to refresh token: Status {}: {}",
        status,
        text
      )));
    }

    let text = token_response
      .text()
      .await
      .map_err(|error| RefreshAuthError::Other(error.into()))?;
    return serde_json::from_str(&text).map_err(|error| RefreshAuthError::Other(error.into()));
  }
  Err(RefreshAuthError::Other(anyhow!(
    "No refresh token, need to re-auth"
  )))
}

fn is_invalid_grant_response(status: StatusCode, body: &str) -> bool {
  status == StatusCode::BAD_REQUEST
    && serde_json::from_str::<GoogleOAuthErrorResponse>(body)
      .is_ok_and(|error| error.error == "invalid_grant")
}

async fn set_google_needs_reauth(user_id: &str, needs_reauth: bool) -> Result<()> {
  let Some(user) = DB.users.get_document(user_id).await? else {
    return Ok(());
  };

  if user.fields.google_needs_reauth == needs_reauth {
    return Ok(());
  }

  let mut updated_user = user.clone();
  updated_user.fields.google_needs_reauth = needs_reauth;
  DB.users.patch_document(&user, &updated_user).await?;
  crate::v2::user::invalidate_all_user_caches(&updated_user).await;
  Ok(())
}

#[derive(Debug, Clone)]
pub struct AuthenticatedUser {
  pub user: User,
}

/// Best-effort auth: inserts [`AuthenticatedUser`] into request extensions
/// when a valid Clerk bearer token is present, but -- unlike the required
/// `crate::app::jwt_middleware` -- never rejects the request when one isn't.
/// Lets a route stay reachable by signed-out callers while still giving a
/// signed-in caller their own household context on top of the same public
/// response.
///
/// Shared by the routes that layer it:
/// `/registrations/{...}/field-strength` and
/// `/view/standings/fencer/{fencer_id}`. Each serves the same public response
/// to everyone and enriches it with owner-scoped data for a signed-in caller.
/// See the British Fencing rankings design doc, "The consequence: British
/// items need an owner-scoped viewing context".
pub async fn optional_auth_middleware(
  mut req: axum::extract::Request<axum::body::Body>,
  next: axum::middleware::Next,
) -> impl axum::response::IntoResponse {
  if let Some(clerk_user) = crate::v3::auth::rest::authenticated_clerk_user(req.headers()).await {
    req
      .extensions_mut()
      .insert(AuthenticatedUser { user: clerk_user });
  }
  next.run(req).await
}

/// Do oauth, and store the resulting tokens in the specially separated
/// accounts table in the database.
pub async fn oauth_and_store(user_id: &str, oauth_code: &str) -> Result<()> {
  let auth_response = google_auth(AuthCodeRequest {
    code: oauth_code.to_owned(),
  })
  .await?;

  let connections = get_connections(&auth_response);

  let obtained = Utc::now();
  let expires = obtained + Duration::seconds(auth_response.expires_in as i64);
  let account = DB
    .accounts
    .list_documents_where(&eq!("c.userId", user_id))
    .await?
    .pop();
  let google_auth = Some(GoogleAuthInfo {
    obtained,
    expires,
    tokens: auth_response,
  });

  match account {
    None => {
      DB.accounts
        .create_document(AccountFields {
          user_id: user_id.to_owned(),
          google_auth,
        })
        .await?;
    }
    Some(account) => {
      let mut new_account = account.clone();
      new_account.fields.google_auth = google_auth;
      DB.accounts.patch_document(&account, &new_account).await?;
    }
  }

  // Write to the user table the services we've successfully connected to. It's ok if this somehow fails is
  // nonatomic - we'll just make the user do auth again at some point.
  let user = DB.users.get_document(user_id).await?;
  if let Some(user) = user {
    let mut new_user = user.clone();
    new_user.fields.connections = Some(connections);
    new_user.fields.google_needs_reauth = false;
    DB.users.patch_document(&user, &new_user).await?;
    crate::v2::user::invalidate_all_user_caches(&new_user).await;
  }

  Ok(())
}

pub async fn get_or_refresh_oauth_token(account: &Account) -> Result<Option<String>> {
  if let Some(auth) = &account.fields.google_auth {
    let now = Utc::now();
    if auth.expires <= now + Duration::minutes(30) {
      info!(
        "Refreshing expired oauth token for user {}",
        account.fields.user_id
      );
      let mut response = match google_refresh_auth(&auth.tokens).await {
        Ok(response) => response,
        Err(RefreshAuthError::InvalidGrant) => {
          set_google_needs_reauth(&account.fields.user_id, true).await?;
          return Err(anyhow!(
            "Google rejected the refresh token; re-authentication is required"
          ));
        }
        Err(RefreshAuthError::Other(error)) => return Err(error),
      };

      if response.refresh_token.is_none() {
        response.refresh_token = auth.tokens.refresh_token.clone();
      }

      // Update the database.
      let obtained = Utc::now();
      let expires = obtained + Duration::seconds(response.expires_in as i64);
      let token = response.access_token.clone();
      let google_auth = Some(GoogleAuthInfo {
        obtained,
        expires,
        tokens: response,
      });

      let mut new_account = account.clone();
      new_account.fields.google_auth = google_auth;
      DB.accounts.patch_document(account, &new_account).await?;
      set_google_needs_reauth(&account.fields.user_id, false).await?;

      return Ok(Some(token));
    } else {
      return Ok(Some(auth.tokens.access_token.clone()));
    }
  }

  Ok(None)
}

fn get_connections(auth_response: &TokenResponse) -> Vec<ServiceConnection> {
  let mut result = vec![];
  for scope in auth_response.scope.split(' ') {
    result.push(scope.into());
  }

  result
}

#[cfg(test)]
mod tests {
  use super::*;
  use jsonwebtoken::{EncodingKey, Header, encode};

  #[test]
  fn oauth_state_round_trip_returns_original_user_id() {
    let state = generate_oauth_state_with_secret("user-123", None, "test-secret").unwrap();
    let user_id = validate_oauth_state_claims_with_secret(&state, "test-secret")
      .unwrap()
      .sub;
    assert_eq!(user_id, "user-123");
  }

  #[test]
  fn oauth_state_round_trip_preserves_optional_return_to_origin() {
    let state = generate_oauth_state_with_secret(
      "user-123",
      Some("https://prod-cf.flunge.org"),
      "test-secret",
    )
    .unwrap();
    let claims = validate_oauth_state_claims_with_secret(&state, "test-secret").unwrap();
    assert_eq!(claims.sub, "user-123");
    assert_eq!(
      claims.return_to.as_deref(),
      Some("https://prod-cf.flunge.org")
    );
  }

  #[test]
  fn oauth_state_validation_rejects_invalid_token() {
    let result = validate_oauth_state_claims_with_secret("not-a-jwt", "test-secret");
    assert!(result.is_err());
  }

  #[test]
  fn oauth_state_validation_rejects_expired_token() {
    let claims = OAuthStateClaims {
      sub: "user-123".to_string(),
      exp: (Utc::now() - Duration::minutes(5)).timestamp(),
      return_to: None,
    };

    let token = encode(
      &Header::default(),
      &claims,
      &EncodingKey::from_secret("test-secret".as_bytes()),
    )
    .unwrap();

    let result = validate_oauth_state_claims_with_secret(&token, "test-secret");
    assert!(result.is_err());
  }

  #[test]
  fn get_connections_maps_scopes_to_service_connections_in_order() {
    let token_response = TokenResponse {
      access_token: "access-token".to_string(),
      refresh_token: Some("refresh-token".to_string()),
      expires_in: 3600,
      scope: "https://www.googleapis.com/auth/calendar.events.owned https://www.googleapis.com/auth/youtube.upload unknown.scope".to_string(),
      token_type: "Bearer".to_string(),
      id_token: None,
    };

    let connections = get_connections(&token_response);
    assert_eq!(
      connections,
      vec![
        ServiceConnection::GoogleCalendar,
        ServiceConnection::YouTubeUpload,
        ServiceConnection::Unknown,
      ]
    );
  }

  #[test]
  fn invalid_grant_is_the_only_refresh_error_that_requires_reauth() {
    assert!(is_invalid_grant_response(
      StatusCode::BAD_REQUEST,
      r#"{"error":"invalid_grant","error_description":"Token has been expired or revoked."}"#,
    ));
    assert!(!is_invalid_grant_response(
      StatusCode::INTERNAL_SERVER_ERROR,
      r#"{"error":"invalid_grant"}"#,
    ));
    assert!(!is_invalid_grant_response(
      StatusCode::BAD_REQUEST,
      r#"{"error":"invalid_client"}"#,
    ));
    assert!(!is_invalid_grant_response(
      StatusCode::BAD_REQUEST,
      "not JSON"
    ));
  }
}

