  pub family_groups: Collection<FamilyGroupFields>,
  pub invitations: Collection<InvitationFields>,
  pub bouts: Collection<BoutFields>,
  pub field_strength_snapshots: Collection<FieldStrengthSnapshotFields>,
  pub share_links: Collection<ResultsShareLinkFields>,
  pub plan_share_links: Collection<PlanShareLinkFields>,
  pub manual_tournaments: Collection<ManualTournamentFields>,
  pub event_notes: Collection<EventNoteFields>,
  pub standings_history_snapshots: Collection<StandingSnapshotFields>,
  pub standings_history_receipts: Collection<SnapshotRunReceiptFields>,
}

impl DbClient {
  fn collection_name(base: &str) -> String {
    match CONF.db.cosmos_collection_prefix {
      Some(ref prefix) => format!("{}-{}", prefix, base),
      None => base.to_string(),
    }
  }

  pub fn new(dry: bool) -> Result<Self> {
    let cosmos_client = CosmosClient::connect(
      &CONF.db.cosmos_account,
      &CONF.db.secret_cosmos_key,
      &CONF.db.cosmos_db,
      dry,
    )?;
    let tournaments = cosmos_client.collection(&Self::collection_name("tournaments"));
    let fencers = cosmos_client.collection(&Self::collection_name("fencers"));
    let users = cosmos_client.collection(&Self::collection_name("users"));
    let notifications = cosmos_client.collection(&Self::collection_name("notifications"));
    let accounts = cosmos_client.collection(&Self::collection_name("accounts"));
    let standings = cosmos_client.collection(&Self::collection_name("standings"));
    let config = cosmos_client.collection(&Self::collection_name("config"));
    let family_groups = cosmos_client.collection(&Self::collection_name("family_groups"));
    let invitations = cosmos_client.collection(&Self::collection_name("invitations"));
    let bouts = cosmos_client.collection(&Self::collection_name("bouts"));
    let field_strength_snapshots =
      cosmos_client.collection(&Self::collection_name("field_strength_snapshots"));
    let share_links = cosmos_client.collection(&Self::collection_name("results_share_links"));
    let plan_share_links = cosmos_client.collection(&Self::collection_name("plan_share_links"));
    let manual_tournaments = cosmos_client.collection(&Self::collection_name("manual_tournaments"));
    let event_notes = cosmos_client.collection(&Self::collection_name("event_notes"));
    // TTL-enabled (`defaultTtl = -1`): every document carries its own `ttl` field rather than a
    // container-wide default expiry - see `standings_history::model` and the design doc's
    // §Retention. `CollectionOptions::default_ttl` is a known no-op against the pinned
    // azure_data_cosmos SDK at container-creation time (see the warning
    // `CosmosClient::ensure_collections_exist` logs); passed anyway so the intent is recorded and
    // forward-compatible with an SDK that supports it.
    let standings_history_snapshots = cosmos_client.collection_with_options(
      &Self::collection_name("standings_history_snapshots"),
      CollectionOptions {
        default_ttl: Some(-1),
      },
    );
    let standings_history_receipts = cosmos_client.collection_with_options(
      &Self::collection_name("standings_history_receipts"),
      CollectionOptions {
        default_ttl: Some(-1),
      },
    );

    Ok(DbClient {
      cosmos_client,
      tournaments,
      fencers,
      users,
      notifications,
      accounts,
      standings,
      config,
      family_groups,
      invitations,
      bouts,
      field_strength_snapshots,
      share_links,
      plan_share_links,
      manual_tournaments,
      event_notes,
      standings_history_snapshots,
      standings_history_receipts,
    })
  }

  /// Creates any of this account's required containers that don't already exist yet, using the
  /// account's standard conventions. Existing containers are left completely untouched. Fails
  /// loudly if a required container is missing and can't be created - callers must treat this as
  /// fatal to startup rather than logging and continuing.
  pub async fn ensure_containers_exist(&self) -> Result<()> {
    self.cosmos_client.ensure_collections_exist().await
  }
}

