+    for op in patch.0.iter() {
+      let path = match op {
+        json_patch::PatchOperation::Add(op) => op.path.as_str(),
+        json_patch::PatchOperation::Remove(op) => op.path.as_str(),
+        json_patch::PatchOperation::Replace(op) => op.path.as_str(),
+        json_patch::PatchOperation::Move(op) => op.path.as_str(),
+        json_patch::PatchOperation::Copy(op) => op.path.as_str(),
+        json_patch::PatchOperation::Test(op) => op.path.as_str(),
+      };
+      let lower = path.to_ascii_lowercase();
+      assert!(
+        !lower.contains("licence")
+          && !lower.contains("license")
+          && !path.contains("britishFencing"),
+        "fencer refresh must not patch a licence path, got {path}"
+      );
+    }
+
+    let after = serde_json::to_value(&refreshed.fields).unwrap();
+    assert!(after.get("britishFencingLicence").is_none());
+    assert_ne!(
+      crate::fencer_licence::document_id(&ids::TypedId::<ids::FencerId>::usaf("100344622")),
+      original.id,
+      "licence sidecar id must not collide with the fencer document id"
+    );
+  }
 }

