pub(crate) mod lookup;
pub mod resolve;
pub mod warmer;

// The egress control + HTTP/scrape API client now live in the standalone
// `fencingtracker` crate so changes to the FencingTracker fetch layer don't
// rebuild all of `blob`. Re-export them under the original module paths so
// existing consumers (`crate::fencingtracker::{api, egress}`) keep compiling
// unchanged.
pub use ::fencingtracker::{api, egress};

// The HTML parsing layer (models + scrapers) likewise lives in its own crate.
// Re-export it under the original module paths so existing consumers keep
// compiling unchanged.
pub use fencingtracker_parse::{model, normalize_name_key, scrape};

use std::collections::HashSet;

use crate::fencingtracker::model::{EventBoutConversionInput, EventResults};
use crate::v2::fencer::FencerSearch;
use crate::v2::model::{Fencer, FencerFields, Rating, Ratings};
use cache::{Cache, CacheCollection, RedisCache};
use tasks::{Task, TaskManager, TaskSpecBuilder};
use tokio::sync::OnceCell;

use anyhow::Result;
use async_trait::async_trait;
use chrono::{Datelike, NaiveDate};
use ids::{ExternalId, IdDetailBuilder, Identified};
use itertools::Itertools;
use tokio::sync::RwLock;
use tracing::{error, info, warn};
use util::{eq, to_ftl_style_name, to_usaf_style_name};

static FENCING_TRACKER_CLIENT: OnceCell<FencingTrackerClient> = OnceCell::const_new();

pub struct FencingTrackerClient {
  cache: RwLock<CacheCollection<FencerFields>>,
}

pub const KEY_NAME: &str = "name";
pub const KEY_CLUB: &str = "club";
pub const KEY_USAF_ID: &str = "usaf_id";

impl FencingTrackerClient {
  fn new(cache: &impl Cache) -> Self {
    let mut cache = cache.collection("ft_fencers");
    cache.add_indexer(KEY_NAME, |f: &Fencer| {
      vec![
        f.fields.name.clone(),
        f.fields.name.to_lowercase().clone(),
        to_usaf_style_name(&f.fields.name).to_lowercase().clone(),
        to_ftl_style_name(&f.fields.name).to_lowercase().clone(),
      ]
    });
    cache.add_indexer(KEY_CLUB, |f: &Fencer| {
      f.fields.current_club_name.clone().into_iter().collect_vec()
    });
    cache.add_indexer(KEY_USAF_ID, |f: &Fencer| {
      f.fields.id_detail.usaf_id.clone().into_iter().collect_vec()
    });

    Self {
      cache: RwLock::new(cache),
    }
  }

  /// Returns the global FencingTrackerClient singleton.
  pub async fn get() -> &'static FencingTrackerClient {
    FENCING_TRACKER_CLIENT
      .get_or_init(|| async { FencingTrackerClient::new(RedisCache::get().await) })
      .await
  }

  pub async fn register_tasks(&self) -> Result<()> {
    let manager = TaskManager::get().await;
    manager
      .add_task(
        TaskSpecBuilder::default()
          .schedule("0 30 5 * * Wed")
          .description("Sync fencer info from FencingTracker")
          .short_name("sync_fencers")
          .task(sync::SyncFencerInfo)
          .build()?,
      )
      .await?;
    // Background strength warmer (recommendation-cache population, Task 2). Runs
    // every `flunge_config::WARMER_CADENCE_SECONDS` deriving a prioritized fencer
    // working set; its draining step is config-gated (off by default). See
    // `warmer` for the full shape.
    let warmer_cadence_minutes = flunge_config::WARMER_CADENCE_SECONDS / 60;
    manager
      .add_task(
        TaskSpecBuilder::default()
          .schedule(format!("0 */{warmer_cadence_minutes} * * * *"))
          .description("Warm FencingTracker fencer strength for the upcoming schedule")
          .short_name("warm_fencer_strength")
          .task(warmer::StrengthWarmer)
          .build()?,
      )
      .await?;
    Ok(())
  }

  /// Try to find the best possible match for the given fencer search in the cache.
  async fn find_fencer_in_cache(&self, search: &FencerSearch) -> Result<Option<Fencer>> {
    if let Some(usaf_id) = &search.usaf_id {
      let result = self
        .cache
        .read()
        .await
        .evaluate(eq!(KEY_USAF_ID, usaf_id))
        .await?;
      if let Some(fencer) = result.into_iter().next() {
        return Ok(Some(fencer));
      }

      // If a USAF ID is provided, do not fall back to name-only matching in cache.
      // Name collisions are common enough that returning an arbitrary cached match can
      // mis-associate bouts to the wrong person.
      info!(
        %usaf_id,
        "USAF ID not found in ft_fencers cache; skipping name-based cache fallback"
      );
      return Ok(None);
    }
    // Try to find by name.
    if let Some(name) = &search.name {
      let result = self
        .cache
        .read()
        .await
        .evaluate(eq!(KEY_NAME, name.to_lowercase()))
        .await?;
      for r in result.iter() {
        if let Some(club) = &search.club
          && let Some(actual_club) = &r.fields.current_club_name
          && names::club_matches(club, actual_club)
        {
          return Ok(Some(r.clone()));
        }
      }

      if let Some(club) = &search.club
        && !result.is_empty()
      {
        warn!(
          %name,
          search_club = %club,
          candidate_count = result.len(),
          "Found cache results but none matched club; not returning a potentially wrong fencer"
        );
        return Ok(None);
      }

      if search.club.is_none() {
        if result.len() == 1 {
          info!("No club provided for search, but only got one result. Returning it.");
          return Ok(result.first().cloned());
        } else if !result.is_empty() {
          warn!(
            "No club provided for search, and got multiple results. Refusing to return an arbitrary potentially wrong fencer"
          );
          return Ok(None);
        }
      }
    }

    info!(?search, "Fencer not found in cache");
    Ok(None)
  }

  async fn find_and_cache_fencer(&self, search: &FencerSearch) -> Result<Option<Fencer>> {
    let mut fencer = None;

    let search = search.clone();

    // If we have a usaf_id, then look up the fencer directly in the api. This is a
    // profile lookup only (name/club/ratings/history) — no registrations needed —
    // so it goes through the long-TTL profile cache, not the composed `get_fencer`.
    if let Some(usaf_id) = &search.usaf_id {
      let usaf_id = usaf_id.parse::<u32>().unwrap();
      if let Ok(api_fencer) = api::get_fencer_profile(usaf_id, None).await {
        fencer = Some(convert_fencer(&api_fencer));
      }
    }

    // If that didn't work, then we have to use a more kludgey methods - search for the name and see if we can
    // find a fencer with a matching club.
    if fencer.is_none()
      && let Some(name) = &search.name
      && let Some(member_id) = self
        .find_fencer_by_name(name, search.club.as_deref())
        .await?
      && let Ok(api_fencer) = api::get_fencer_profile(member_id, None).await
    {
      fencer = Some(convert_fencer(&api_fencer));
    }

    if let Some(mut fencer) = fencer {
      if fencer.fields.gender.is_none() {
        fencer.fields.gender = search.gender.clone();
      }

      // if let Some(usaf_id) = &fencer.fields.id_detail.usaf_id {
      //   // // Try to find USA fencing standings for this fencer in the cache, and inject them into the object.
      //   // let standings = services.usaf.get_standing_from_cache(usaf_id).await?;
      //   // fencer.fields.standing = standings;
      // }
      self.cache.write().await.put(fencer.clone()).await?;

      return Ok(Some(fencer));
    }

    Ok(None)
  }

  // Tries to find the best possible match for the given fencer information.
  pub async fn find_fencer(
    &self,
    search: &FencerSearch,
    do_search: bool,
  ) -> Result<Option<Fencer>> {
    // First, try to find the fencer in the cache.
    if let Some(fencer) = self.find_fencer_in_cache(search).await? {
      // if let Some(usaf_id) = &fencer.fields.id_detail.usaf_id {
      //   // // Try to find USA fencing standings for this fencer in the cache, and inject them into the object.
      //   // let standings = services.usaf.get_standing_from_cache(usaf_id).await?;
      //   // fencer.fields.standing = standings;
      // }
      Ok(Some(fencer))
    } else if do_search {
      Ok(self.find_and_cache_fencer(search).await?)
    } else {
      Ok(None)
    }
  }

  /// Finds a fencer's FencingTracker membership from a name and optionally a
  /// club, via [`resolve`] — the single shared resolver.
  ///
  /// This used to be `find_fencer_impl`, a third independent matcher. It
  /// accepted a lone search hit without verifying the name at all, and broke a
  /// genuine tie by picking the only "Unattached" row. The shared resolver
  /// verifies the name on every candidate and refuses ties, so this path is now
  /// stricter — see the module docs on `resolve` for what that trades away.
  ///
  /// `FencerSearch` carries no birth year, so this caller cannot supply the
  /// resolver's strongest discriminator and leans on club alone. That is the
  /// same information it always had; the difference is that an unverifiable
  /// match is now declined rather than returned.
  async fn find_fencer_by_name(&self, name: &str, club: Option<&str>) -> Result<Option<u32>> {
    let query = resolve::FencerQuery::by_name(name).with_club(club.map(str::to_owned));
    Ok(resolve::resolve_member_id(&query).await?.member_id())
  }

  async fn get_profile_by_name(
    &self,
    name: &str,
    club: Option<&str>,
  ) -> Result<Option<model::Fencer>> {
    match self.find_fencer_by_name(name, club).await? {
      Some(member_id) => Ok(api::get_fencer_profile(member_id, None).await.ok()),
      None => Ok(None),
    }
  }
}

fn get_first_competition_year(fencer: &model::Fencer) -> Option<u16> {
  let mut first_year = 9999;
  for result in &fencer.results {
    let year = result.event.date.year();
    if year < first_year {
      first_year = year;
    }
  }
  if first_year == 9999 {
    None
  } else {
    Some(first_year as u16)
  }
}

fn merge_into(api_fencer: &model::Fencer, fencer: &mut FencerFields) {
  fencer.id_detail.usaf_id = Some(api_fencer.id.to_string());
  fencer.birth_year = api_fencer.birth_year;
  fencer.first_competition_year = get_first_competition_year(api_fencer);
  fencer.current_club_name = api_fencer.club.clone();
  fencer.country = Some(api_fencer.country.clone());
  fencer.current_ratings = convert_ratings(&api_fencer.rating_history);
}

fn convert_fencer(fencer: &model::Fencer) -> Fencer {
  let converted = FencerFields {
    id_detail: IdDetailBuilder::default()
      .usaf_id(fencer.id.to_string())
      .build()
      .unwrap(),
    name: to_usaf_style_name(&fencer.name), // Always normalize fencer names to their USAF style.
    birth_year: fencer.birth_year,
    first_competition_year: get_first_competition_year(fencer),
    country: Some(fencer.country.clone()),
    current_club_name: fencer.club.clone(),
    gender: None,
    current_ratings: convert_ratings(&fencer.rating_history),
    standing: None,
    match_stats: None,
    confirmed_usaf_registrations: vec![],
  };

  Identified::external(ExternalId::UsaFencing(fencer.id.to_string()), converted)
}

fn convert_ratings(rating_history: &[model::RatingHistory]) -> Option<Ratings> {
  if rating_history.is_empty() {
    return None;
  }

  let mut ratings = Ratings {
    foil: None,
    epee: None,
    sabre: None,
  };

  for rating in rating_history.iter().rev() {
    match rating.rating.weapon.unwrap() {
      Weapon::Foil => ratings.foil = Some(convert_rating(&rating.rating, rating.date)),
      Weapon::Epee => ratings.epee = Some(convert_rating(&rating.rating, rating.date)),
      Weapon::Sabre => ratings.sabre = Some(convert_rating(&rating.rating, rating.date)),
      _ => {}
    }
  }

  Some(ratings)
}

use model_common::{self, Weapon};

fn convert_rating(rating: &model_common::FencerRating, obtained: NaiveDate) -> Rating {
  Rating {
    classification: rating.category.to_string(),
    year_obtained: rating.year,
    date_obtained: obtained,
  }
}

/// Converts parsed FT event results into deduplicated bout conversion inputs.
/// FT result pages list every bout from both fencers' perspectives; this removes
/// mirrored duplicates while preserving score parity.
pub fn build_event_bout_conversion_inputs(
  event_results: &EventResults,
) -> Vec<EventBoutConversionInput> {
  let mut dedupe = HashSet::new();
  let mut inputs = Vec::new();

  for entrant in &event_results.entrants {
    for bout in &entrant.bouts {
      let key = canonical_bout_key(
        bout.stage,
        entrant.usaf_id,
        bout.opponent_usaf_id,
        &entrant.name,
        &bout.opponent_name,
        bout.score_for,
        bout.score_against,
      );

      if dedupe.insert(key) {
        inputs.push(EventBoutConversionInput {
          stage: bout.stage,
          left_usaf_id: entrant.usaf_id,
          left_name: entrant.name.clone(),
          right_usaf_id: bout.opponent_usaf_id,
          right_name: bout.opponent_name.clone(),
          left_score: bout.score_for,
          right_score: bout.score_against,
        });
      }
    }
  }

  inputs
}

fn canonical_bout_key(
  stage: crate::fencingtracker::model::EventBoutStage,
  left_id: u32,
  right_id: Option<u32>,
  left_name: &str,
  right_name: &str,
  left_score: u8,
  right_score: u8,
) -> String {
  if let Some(right_id) = right_id {
    if left_id <= right_id {
      return format!(
        "{:?}|{}|{}|{}:{}",
        stage, left_id, right_id, left_score, right_score
      );
    }
    return format!(
      "{:?}|{}|{}|{}:{}",
      stage, right_id, left_id, right_score, left_score
    );
  }

  let left_key = normalize_name_key(left_name);
  let right_key = normalize_name_key(right_name);
  if left_key <= right_key {
    format!(
      "{:?}|{}|{}|{}:{}",
      stage, left_key, right_key, left_score, right_score
    )
  } else {
    format!(
      "{:?}|{}|{}|{}:{}",
      stage, right_key, left_key, right_score, left_score
    )
  }
}

mod sync {
  use super::*;
  use crate::db::DB;
  use crate::notification::{fencer_club_changed, fencer_rating_changed, post};

  pub struct SyncFencerInfo;
  #[async_trait]
  impl Task for SyncFencerInfo {
    async fn execute(&self) -> Result<()> {
      // This scheduled sync is background egress: any FencingTracker fetch it
      // makes is attributed to the background source and subject to the
      // background request budget, keeping it separable from serving traffic.
      egress::as_background(self.sync()).await
    }
  }

  impl SyncFencerInfo {
    async fn sync(&self) -> Result<()> {
      let mut fencers = DB.fencers.list_documents().await?;

      for f in fencers.iter_mut() {
        let profile = if let Some(usaf_id) = &f.fields.id_detail.usaf_id {
          Some(api::get_fencer_profile(usaf_id.parse().unwrap(), None).await?)
        } else if f.fields.country != Some("GB".to_string()) {
          warn!(
            fencer_name = %f.fields.name,
            "Profile does not have a USAF ID"
          );
          FencingTrackerClient::get()
            .await
            .get_profile_by_name(&f.fields.name, f.fields.current_club_name.as_deref())
            .await?
        } else {
          None
        };

        if let Some(profile) = profile {
          let mut notifications = Vec::new();
          let original = f.clone();
          merge_into(&profile, &mut f.fields);

          if f.fields.current_club_name != original.fields.current_club_name {
            notifications.push(fencer_club_changed(f)?);
          }

          if f.fields.current_ratings != original.fields.current_ratings {
            notifications.append(&mut fencer_rating_changed(
              f,
              &original.fields.current_ratings,
            )?);
          }

          if !notifications.is_empty() {
            info!(
              fencer_name = %f.fields.name,
              ?notifications,
              "Sending notifications"
            );

            if let Err(e) = post(notifications).await {
              error!(error = ?e, "Failed to send notifications");
            }
          }

          DB.fencers.patch_document(&original, f).await?;
        } else {
          warn!(
            fencer_name = %f.fields.name,
            "Unable to find FencingTracker profile"
          )
        }
      }

      Ok(())
    }
  }

  // SyncRegistrations and RepairRecentRegistrationsDryRun tasks have been removed.
  // Registration syncing is now handled on-demand via the /v3/view/fencer/{id}/registrations API,
  // and result syncing uses connected fencers from user.trackedFencers.
}

#[cfg(test)]
mod tests {
  use crate::fencingtracker::model::{
    EventBoutResult, EventBoutStage, EventResults, EventResultsEntrant,
  };
  use crate::v2::fencer::FencerSearchBuilder;
  use crate::v2::model::FencerFieldsBuilder;
  use cache::InMemoryCache;

  use super::*;
  use assert_matches::assert_matches;

  #[test]
  fn build_event_bout_conversion_inputs_deduplicates_mirrored_rows() {
    let parsed = EventResults {
      event_id: 123,
      entrants: vec![
        EventResultsEntrant {
          usaf_id: 111,
          name: "DOE JANE".to_string(),
          bouts: vec![
            EventBoutResult {
              stage: EventBoutStage::Pool,
              elimination_round_of: None,
              opponent_name: "SMITH JOHN".to_string(),
              opponent_usaf_id: Some(222),
              score_for: 5,
              score_against: 3,
            },
            EventBoutResult {
              stage: EventBoutStage::DirectElimination,
              elimination_round_of: Some(16),
              opponent_name: "SMITH JOHN".to_string(),
              opponent_usaf_id: Some(222),
              score_for: 15,
              score_against: 14,
            },
          ],
        },
        EventResultsEntrant {
          usaf_id: 222,
          name: "SMITH JOHN".to_string(),
          bouts: vec![
            EventBoutResult {
              stage: EventBoutStage::Pool,
              elimination_round_of: None,
              opponent_name: "DOE JANE".to_string(),
              opponent_usaf_id: Some(111),
              score_for: 3,
              score_against: 5,
            },
            EventBoutResult {
              stage: EventBoutStage::DirectElimination,
              elimination_round_of: Some(16),
              opponent_name: "DOE JANE".to_string(),
              opponent_usaf_id: Some(111),
              score_for: 14,
              score_against: 15,
            },
          ],
        },
      ],
      parse_failures: 0,
    };

    let converted = build_event_bout_conversion_inputs(&parsed);
    assert_eq!(converted.len(), 2);
    assert!(
      converted
        .iter()
        .any(|bout| bout.stage == EventBoutStage::Pool
          && bout.left_usaf_id == 111
          && bout.right_usaf_id == Some(222)
          && bout.left_score == 5
          && bout.right_score == 3)
    );
    assert!(
      converted
        .iter()
        .any(|bout| bout.stage == EventBoutStage::DirectElimination
          && bout.left_usaf_id == 111
          && bout.right_usaf_id == Some(222)
          && bout.left_score == 15
          && bout.right_score == 14)
    );
  }

  #[tokio::test]
  #[ignore = "Hits live FencingTracker and requires full runtime config"]
  async fn find_fencers() -> Result<()> {
    let cache = InMemoryCache;
    let client = FencingTrackerClient::new(&cache);

    // An unambiguous name resolves with or without a club.
    assert_matches!(
      client
        .find_fencer_by_name("DUFF Caitlin", Some("Halberstadt Fencers' Club"))
        .await?,
      Some(100344622)
    );
    assert_matches!(
      client.find_fencer_by_name("DUFF Caitlin", None).await?,
      Some(100344622)
    );

    // A name with several holders resolves only when a club separates them...
    assert_matches!(
      client
        .find_fencer_by_name("WANG David", Some("Bay Area Fencing Club"))
        .await?,
      Some(100335535)
    );

    // ...and is refused outright when nothing does. This assertion used to read
    // `Some(100332472)` with the comment "essentially arbitrary": the old
    // matcher broke the tie by picking a candidate. Returning an arbitrary
    // member id for a name shared by several fencers is how one fencer's
    // ratings and results end up attached to another, so the shared resolver
    // declines instead.
    assert_matches!(client.find_fencer_by_name("WANG David", None).await?, None);

    // A club nobody in the result set belongs to is not a licence to guess
    // either. The club is a tie-break, so this falls back to the same refusal.
    assert_matches!(
      client
        .find_fencer_by_name("WANG David", Some("Academy of Totally Imaginary Fencers"))
        .await?,
      None
    );

    Ok(())
  }

  async fn seed_cached_fencer(
    client: &FencingTrackerClient,
    usaf_id: &str,
    name: &str,
    club: Option<&str>,
  ) -> Result<()> {
    let mut builder = FencerFieldsBuilder::default();
    builder.name(name.to_string()).id_detail(
      IdDetailBuilder::default()
        .usaf_id(usaf_id.to_string())
        .build()?,
    );
    if let Some(club) = club {
      builder.current_club_name(club.to_string());
    }
    let fencer = Identified::usaf_id(usaf_id, builder.build()?);
    client.cache.write().await.put(fencer).await?;
    Ok(())
  }

  #[tokio::test]
  async fn find_fencer_with_usaf_id_prefers_id_match_over_name_collisions() -> Result<()> {
    let cache = InMemoryCache;
    let client = FencingTrackerClient::new(&cache);

    seed_cached_fencer(
      &client,
      "100286745",
      "Li, Sonia",
      Some("Bergen Fencing Club"),
    )
    .await?;
    seed_cached_fencer(
      &client,
      "100314522",
      "Li, Sonia",
      Some("Advance Fencing And Fitness Academy"),
    )
    .await?;

    let search = FencerSearchBuilder::default()
      .usaf_id("100314522".to_string())
      .name("LI Sonia".to_string())
      .club(Some("Advance Fencing And Fitness Academy".to_string()))
      .build()?;

    let result = client.find_fencer(&search, false).await?;
    assert_eq!(
      result.and_then(|f| f.fields.current_club_name),
      Some("Advance Fencing And Fitness Academy".to_string())
    );
    Ok(())
  }

  #[tokio::test]
  async fn find_fencer_does_not_fallback_to_name_when_usaf_id_misses_cache() -> Result<()> {
