before.content:
//! Anonymous, read-only share-view API: `GET /api/v3/share/results/view`,
//! `GET /api/v3/share/results/view/events/{tournament_id}/{event_id}`, and
//! `GET /api/v3/share/results/view/standings`. See
//! `docs/design-docs/private-results-share-links.md` and, for the standings
//! route specifically,
//! `docs/design-docs/british-fencing-rankings-as-a-standings-source.md`.
//!
//! Every failure mode — missing header, unknown token, revoked, expired, or
//! the owner document gone — collapses to the same generic 404
//! ([`unavailable`]). That is a deliberate anti-enumeration property (see
//! the design doc's Revocation section), not an oversight: do not add a
//! response that distinguishes any of those causes.
//!
//! These handlers never read `Authorization` or any other identity header.
//! Video visibility comes **only** from the share link's owner id, resolved
//! via [`share::resolve_live_link`] and threaded into
//! [`results::get_event`] as `viewer_user_id` — never from whoever is making
//! the anonymous request, signed in or not. That is what makes "a logged-in
//! recipient does not get their own private videos mixed in" true by
//! construction rather than by a check that could be forgotten.

use axum::Json;
use axum::extract::{Path, Request};
use axum::http::{HeaderMap, HeaderValue, StatusCode, header};
use axum::middleware::{self, Next};
use axum::response::{IntoResponse, Response};
use routez::RoutezRouter;
use serde::Serialize;
use tracing::{error, warn};

use ids::{Identified, ResultsShareLinkId, TypedId};

use crate::share::{self, ResultsShareLinkFields};
use crate::view::fencer::fetch_db_fencer_fields;
use crate::view::ids::parse_typed_id;
use crate::view::results::{self, Event, Tournament};
use crate::view::standings::fencer as standings_fencer;

use super::rate_limit;

/// Header carrying the share-link bearer token. Never placed in a URI or
/// query string — see the design doc's Hardening / Logging section. Also
/// referenced by `crate::cors` so it stays in CORS's `allow_headers` (a
/// browser strips any header not listed there from a cross-origin request).
pub(crate) const SHARE_TOKEN_HEADER: &str = "x-flunge-share-token";

/// Router for the anonymous share-view routes, mounted at `/share` alongside
/// (but not gated by) the authenticated owner router in [`super::api`].
/// Every response — success or failure — carries `Cache-Control: private,
/// no-store`: these are authenticated-equivalent payloads served anonymously
/// and must never be stored by a shared cache.
pub fn router() -> RoutezRouter {
  let router = RoutezRouter::new()
    .route_get("/results/view", get_share_results_view)
    .route_get(
      "/results/view/events/{tournament_id}/{event_id}",
      get_share_event_view,
    )
    .route_get("/results/view/standings", get_share_standings_view)
    .route_get(
      "/results/view/standings/{standing_key}/composition",
      get_share_standing_composition_view,
    )
    .merge(super::plan_view::router());

  let (inner, routes) = router.finish();
  RoutezRouter::from_parts(
    inner.layer(middleware::from_fn(no_store_middleware)),
    routes,
  )
}

pub(super) async fn no_store_middleware(request: Request, next: Next) -> Response {
  let mut response = next.run(request).await;
  response.headers_mut().insert(
    header::CACHE_CONTROL,
    HeaderValue::from_static("private, no-store"),
  );
  response
}

/// The generic "this link isn't available" response — same body and status
/// for missing header / unknown / revoked / expired / owner-gone alike.
pub(super) fn unavailable() -> Response {
  (StatusCode::NOT_FOUND, "Share link not found").into_response()
}

pub(super) fn too_many_requests() -> Response {
  (StatusCode::TOO_MANY_REQUESTS, "Too many requests").into_response()
}

pub(super) fn internal_error() -> Response {
  (
    StatusCode::INTERNAL_SERVER_ERROR,
    "An internal error occurred",
  )
    .into_response()
}

/// Extracts the bearer token from [`SHARE_TOKEN_HEADER`]. `None` on a
/// missing, non-UTF-8, or empty header — all treated identically by the
/// caller (see the module doc).
pub(super) fn share_token(headers: &HeaderMap) -> Option<&str> {
  headers
    .get(SHARE_TOKEN_HEADER)?
    .to_str()
    .ok()
    .filter(|token| !token.is_empty())
}

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
struct ShareResultsViewResponse {
  fencer_id: String,
  fencer_name: String,
  created_at: String,
  expires_at: String,
  tournaments: Vec<Tournament>,
}

async fn get_share_results_view(headers: HeaderMap) -> Response {
  if !rate_limit::allow(&headers) {
    return too_many_requests();
  }

  let Some(token) = share_token(&headers) else {
    return unavailable();
  };

  let link = match share::resolve_live_link(token).await {
    Ok(Some(link)) => link,
    Ok(None) => return unavailable(),
    Err(err) => {
      error!(error = ?err, "failed to resolve share link for results view");
      return internal_error();
    }
  };

  render_results_view(link).await
}

async fn render_results_view(link: Identified<ResultsShareLinkFields>) -> Response {
  let rsl_id = TypedId::<ResultsShareLinkId>::database(&link.id);
  let fencer_id = link.fields.fencer_id.clone();

  let fencer_name = match fetch_db_fencer_fields(&fencer_id).await {
    Ok(Some(fields)) => fields.name,
    Ok(None) => {
      warn!(rsl_id = %rsl_id, "share link's connected fencer no longer exists");
      return unavailable();
    }
    Err(err) => {
      error!(rsl_id = %rsl_id, error = ?err, "failed to load fencer for share view");
      return internal_error();
    }
  };

  let tournaments = match results::get_tournaments(fencer_id.clone()).await {
    Ok(tournaments) => tournaments,
    Err(
      err @ (results::ResultsError::NotFound(_)
      | results::ResultsError::InvalidId(..)
      | results::ResultsError::FencerNotFound),
    ) => {
      warn!(rsl_id = %rsl_id, error = ?err, "share view tournaments were not found");
      return unavailable();
    }
    Err(err) => {
      error!(rsl_id = %rsl_id, error = ?err, "failed to load tournaments for share view");
      return internal_error();
    }
  };

  Json(ShareResultsViewResponse {
    fencer_id: fencer_id.to_string(),
    fencer_name,
    created_at: link.fields.created_at.to_rfc3339(),
    expires_at: link.fields.expires_at.to_rfc3339(),
    tournaments,
  })
  .into_response()
}

async fn get_share_event_view(
  headers: HeaderMap,
  Path((tournament_id, event_id)): Path<(String, String)>,
) -> Response {
  if !rate_limit::allow(&headers) {
    return too_many_requests();
  }

  let Some(token) = share_token(&headers) else {
    return unavailable();
  };

  let Ok(tournament_id) = parse_typed_id(&tournament_id, "tournament") else {
    return unavailable();
  };
  let Ok(event_id) = parse_typed_id(&event_id, "event") else {
    return unavailable();
  };

  let link = match share::resolve_live_link(token).await {
    Ok(Some(link)) => link,
    Ok(None) => return unavailable(),
    Err(err) => {
      error!(error = ?err, "failed to resolve share link for event view");
      return internal_error();
    }
  };

  render_event_view(link, tournament_id, event_id).await
}

async fn render_event_view(
  link: Identified<ResultsShareLinkFields>,
  tournament_id: TypedId<ids::TournamentId>,
  event_id: TypedId<ids::EventId>,
) -> Response {
  let rsl_id = TypedId::<ResultsShareLinkId>::database(&link.id);
  let owner_user_id = link.fields.owner_user_id.clone();
  let fencer_id = link.fields.fencer_id.clone();

  match results::get_event(fencer_id, tournament_id, event_id, Some(owner_user_id)).await {
    Ok(event) => share_event_response(event),
    Err(
      err @ (results::ResultsError::NotFound(_)
      | results::ResultsError::InvalidId(..)
      | results::ResultsError::FencerNotFound),
    ) => {
      warn!(rsl_id = %rsl_id, error = ?err, "share view event was not found");
      unavailable()
    }
    Err(err) => {
      error!(rsl_id = %rsl_id, error = ?err, "failed to load event for share view");
      internal_error()
    }
  }
}

fn share_event_response(event: Event) -> Response {
  Json(event).into_response()
}

/// Owner-scoped standings for a live share link: the internal standings
/// assembly entry point (`standings_fencer::get_fencer_standings`), reused
/// exactly as the owner's own `/view/standings/fencer/{fencer_id}` route
/// uses it, but resolving the British Fencing licence from the link's own
/// `owner_user_id` and bound `fencer_id` instead of a Clerk session. No
/// `fencer_id` path segment -- a link can only ever answer for the one
/// fencer it is bound to -- and no `Authorization`/identity header is ever
/// read here, so a signed-in recipient's own session cannot substitute a
/// different fencer or licence (see the module doc's "ignore-recipient-auth"
/// guarantee). Inherits the generic-404, no-store, and rate-limit
/// guarantees the same way every other handler in this module does.
async fn get_share_standings_view(headers: HeaderMap) -> Response {
  if !rate_limit::allow(&headers) {
    return too_many_requests();
  }

  let Some(token) = share_token(&headers) else {
    return unavailable();
  };

  let resolution = match share::resolve_live_link_with_owner(token).await {
    Ok(Some(resolution)) => resolution,
    Ok(None) => return unavailable(),
    Err(err) => {
      error!(error = ?err, "failed to resolve share link for standings view");
      return internal_error();
    }
  };

  render_standings_view(resolution).await
}

async fn render_standings_view(resolution: share::ResolvedResultsShareLink) -> Response {
  let link = resolution.link;
  let rsl_id = TypedId::<ResultsShareLinkId>::database(&link.id);
  let fencer_id = link.fields.fencer_id.clone();

  let british_licence =
    standings_fencer::licence_for_fencer(&resolution.owner.fields.tracked_fencers, &fencer_id);

  match standings_fencer::get_fencer_standings(fencer_id, british_licence.as_deref()).await {
    // Same payload as the owner handler: attach movement, then drop
    // unsubstantiated summaries. A Redis miss omits `movement` rather than
    // failing the share page.
    Ok(response) => Json(standings_fencer::standings_view_payload(response).await).into_response(),
    Err(err) => {
      error!(rsl_id = %rsl_id, error = ?err, "failed to load standings for share view");
      internal_error()
    }
  }
}

/// Composition for the exact fencer bound to a live results-share link. The
/// fencer id and British licence are both resolved from the link and owner;
/// neither may be supplied by the recipient.
async fn get_share_standing_composition_view(
  headers: HeaderMap,
  Path(raw_standing_key): Path<String>,
) -> Response {
  if !rate_limit::allow(&headers) {
    return too_many_requests();
  }

  let Some(token) = share_token(&headers) else {
    return unavailable();
  };
  let Ok(standing_key) = standings_fencer::parse_standing_key(&raw_standing_key) else {
    return unavailable();
  };

  let resolution = match share::resolve_live_link_with_owner(token).await {
    Ok(Some(resolution)) => resolution,
    Ok(None) => return unavailable(),
    Err(err) => {
      error!(error = ?err, "failed to resolve share link for standings composition");
      return internal_error();
    }
  };

  render_standing_composition_view(resolution, standing_key).await
}

async fn render_standing_composition_view(
  resolution: share::ResolvedResultsShareLink,
  standing_key: TypedId<ids::StandingId>,
) -> Response {
  let link = resolution.link;
  let rsl_id = TypedId::<ResultsShareLinkId>::database(&link.id);
  let fencer_id = link.fields.fencer_id.clone();
  let british_licence =
    standings_fencer::licence_for_fencer(&resolution.owner.fields.tracked_fencers, &fencer_id);

  match standings_fencer::get_standing_composition(
    fencer_id,
    standing_key,
    british_licence.as_deref(),
  )
  .await
  {
    Ok(response) => Json(response).into_response(),
    Err(
      err @ (crate::view::standings::StandingsError::InvalidStandingKey(_)
