    ) => {
      warn!(rsl_id = %rsl_id, error = ?err, "share view standing composition was not found");
      unavailable()
    }
    Err(err) => {
      error!(rsl_id = %rsl_id, error = ?err, "failed to load share view standing composition");
      internal_error()
    }
  }
}

