//! Per-run capture: walk tracked fencers, snapshot each standing, write
//! movement, then the receipt.

use std::collections::HashMap;
use std::time::{Duration, Instant};

use anyhow::{Context, Result};
use chrono::{DateTime, Utc};
use flunge_config::CONF;
use ids::{FencerId, TypedId};
use model_common::RecognizedClassifier;
use standings_history::{
  CompositionCapture, NotCapturedReason, ReceiptOutcome, SnapshotRunReceiptFields,
  SourceObservation, StandingSnapshotFields, StandingSnapshotProjection, compute_movement,
  generate_snapshot_id, repository,
};
use standings_index::RankingScope;
use tracing::{info, warn};

use crate::db::DB;
use crate::v2::user::get_all_connected_fencer_ids_and_licences;
use crate::view::standings::british_rankings_enabled;
use crate::view::standings::fencer::{
  FencerStandingItem, composition_route, get_fencer_standings, resolve_composition_body,
};

use super::composition::{composition_capture_from_body, skip_live_composition};
use super::state::{
  CaptureCounts, HistoryRunState, note_snapshot_bounds, read_run_state, slot_run_id,
  write_movement, write_run_state,
};

pub struct CaptureOutcome {
  pub run_id: String,
  pub counts: CaptureCounts,
}

pub async fn capture_run(explicit_run_id: Option<String>) -> Result<CaptureOutcome> {
  let now = Utc::now();
  let run_id = match explicit_run_id {
    Some(id) => id,
    None => slot_run_id(now)?,
  };
  let started = Instant::now();
  let deadline = started + Duration::from_secs(CONF.standings_history.max_run_seconds);
  let ttl = document_ttl_seconds();
  let capture_live = CONF.standings_history.capture_live_compositions;
  let cooldown_active = standings_index::refresh_cooldown_is_active(now)
    .await
    .unwrap_or_else(|error| {
      warn!(
        error = ?error,
        "Failed to read standings refresh cooldown; treating it as inactive"
      );
      false
    });

  let mut state = read_run_state().await.unwrap_or_default();
  state.last_attempt_at = Some(now);
  state.last_attempt_run_id = Some(run_id.clone());
  write_run_state(&state).await?;

  let (connected_fencer_ids, licence_pairs) = get_all_connected_fencer_ids_and_licences()
    .await
    .context("enumerating connected fencers and British Fencing licence assertions")?;
  let mut fencer_ids: Vec<u32> = connected_fencer_ids.into_iter().collect();
  fencer_ids.sort_unstable();

  let licence_assertions = group_licence_assertions(licence_pairs);

  let british_rankings_enabled = british_rankings_enabled().await.unwrap_or_else(|error| {
    warn!(
      error = ?error,
      "Failed to read British rankings runtime flag; treating standings history capture as British-disabled this run"
    );
    false
  });
  if !british_rankings_enabled {
    warn!(
      run_id = %run_id,
      "British rankings runtime flag (standings.british_rankings_enabled) is disabled; \
       this capture run will write no British (gb-) snapshots -- every tracked fencer with a \
       British licence will read as unranked rather than uncaptured until it is re-enabled"
    );
  }

  info!(
    run_id = %run_id,
    fencer_count = fencer_ids.len(),
    capture_live,
    cooldown_active,
    british_rankings_enabled,
    "Starting standings history capture"
  );

  let mut counts = CaptureCounts {
    british_rankings_flag_disabled: !british_rankings_enabled,
    ..CaptureCounts::default()
  };
  let mut last_live_fetch = Instant::now()
    .checked_sub(Duration::from_secs(3600))
    .unwrap_or_else(Instant::now);
  let mut attempted = 0usize;

  for usaf_id in &fencer_ids {
    if Instant::now() >= deadline {
      break;
    }
    attempted += 1;
    let fencer_id = TypedId::<FencerId>::usaf(&usaf_id.to_string());
    let british_licence = if british_rankings_enabled {
      resolve_fencer_british_licence(*usaf_id, &licence_assertions, &mut counts)
    } else {
      None
    };
    match capture_one_fencer(FencerCaptureParams {
      fencer_id: &fencer_id,
      run_id: &run_id,
      ttl,
      capture_live,
      cooldown_active,
      deadline,
      last_live_fetch: &mut last_live_fetch,
      counts: &mut counts,
      state: &mut state,
      british_licence,
    })
    .await
    {
      Ok(FencerCaptureResult::Succeeded) => {
        counts.fencers_attempted += 1;
        counts.fencers_succeeded += 1;
      }
      Ok(FencerCaptureResult::Failed) => {
        counts.fencers_attempted += 1;
        counts.fencers_failed += 1;
      }
      Err(error) => {
        counts.fencers_attempted += 1;
        counts.fencers_failed += 1;
        warn!(
          fencer_id = %fencer_id,
          run_id = %run_id,
          error = ?error,
          "Standings history capture failed for fencer"
        );
        if let Err(receipt_error) =
          upsert_failed_receipt(&fencer_id, &run_id, ttl, &error.to_string()).await
        {
          warn!(
            fencer_id = %fencer_id,
            error = ?receipt_error,
            "Failed to write standings history failure receipt"
          );
        }
      }
    }
  }

  counts.fencers_unattempted = (fencer_ids.len() - attempted) as u32;
  state.last_run_counts = Some(counts.clone());
  if counts.is_complete() {
    state.last_success_at = Some(Utc::now());
    state.last_failure_at = None;
    state.last_failure_reason = None;
  } else {
    state.last_failure_at = Some(Utc::now());
    state.last_failure_reason = Some(counts.summary());
  }
  write_run_state(&state).await?;

  Ok(CaptureOutcome { run_id, counts })
}

enum FencerCaptureResult {
  Succeeded,
  Failed,
}

struct FencerCaptureParams<'a> {
  fencer_id: &'a TypedId<FencerId>,
  run_id: &'a str,
  ttl: i64,
  capture_live: bool,
  cooldown_active: bool,
  deadline: Instant,
  last_live_fetch: &'a mut Instant,
  counts: &'a mut CaptureCounts,
  state: &'a mut HistoryRunState,
  /// This fencer's single unambiguous British Fencing licence, or `None`
  /// when nobody asserts one or households disagree -- see
  /// [`resolve_british_licence`]. `get_fencer_standings`/
  /// `resolve_composition_body` already omit British items on `None`
  /// regardless of the reason, so no separate USA-only path is needed here.
  british_licence: Option<String>,
}

async fn capture_one_fencer(params: FencerCaptureParams<'_>) -> Result<FencerCaptureResult> {
  let FencerCaptureParams {
    fencer_id,
    run_id,
    ttl,
    capture_live,
    cooldown_active,
    deadline,
    last_live_fetch,
    counts,
    state,
    british_licence,
  } = params;
  let response = match get_fencer_standings(fencer_id.clone(), british_licence.as_deref()).await {
    Ok(response) => response,
    Err(error) => {
      upsert_failed_receipt(fencer_id, run_id, ttl, &error.to_string()).await?;
      return Ok(FencerCaptureResult::Failed);
    }
  };
  if british_licence.is_some()
    && response
      .standings
      .iter()
      .any(|standing| standing.scope == RankingScope::British)
  {
    counts.british_captured += 1;
  }

  let captured_at = Utc::now();
  let mut written: Vec<StandingSnapshotFields> = Vec::with_capacity(response.standings.len());
  let mut standing_keys: Vec<String> = Vec::with_capacity(response.standings.len());
  let mut budget_exhausted = Instant::now() >= deadline;

  for standing in &response.standings {
    let composition = if budget_exhausted || Instant::now() >= deadline {
      budget_exhausted = true;
      CompositionCapture::NotCaptured {
        reason: NotCapturedReason::RunTimeBudgetExhausted,
      }
    } else {
      resolve_standing_composition(
        fencer_id,
        standing,
        capture_live,
        cooldown_active,
        last_live_fetch,
        british_licence.as_deref(),
      )
      .await
    };
    counts.record_composition(&composition);

    let fields = StandingSnapshotFields {
      schema_version: standings_history::model::SCHEMA_VERSION,
      fencer_id: fencer_id.to_string(),
      standing_key: standing.key.to_string(),
      run_id: run_id.to_string(),
      captured_at,
      scope: scope_wire(standing.scope),
      region_id: standing.region_id,
      classifier_code: standing.classifier.code.clone(),
      rank: standing.rank.clone(),
      points: standing.points,
      entrants: standing.entrants,
      source: source_observation(standing).await,
      composition,
      ttl,
    };
    repository::upsert_snapshot(&DB.standings_history_snapshots, fields.clone()).await?;
    note_snapshot_bounds(state, captured_at);
    standing_keys.push(standing.key.to_string());
    written.push(fields);
  }

  write_fencer_movement(
    fencer_id,
    run_id,
    captured_at,
    ttl,
    &written,
    &standing_keys,
  )
  .await?;

  repository::upsert_receipt(
    &DB.standings_history_receipts,
    SnapshotRunReceiptFields {
      fencer_id: fencer_id.to_string(),
      run_id: run_id.to_string(),
      captured_at,
      outcome: ReceiptOutcome::Succeeded { standing_keys },
      ttl,
    },
  )
  .await?;

  Ok(FencerCaptureResult::Succeeded)
}

async fn resolve_standing_composition(
  fencer_id: &TypedId<FencerId>,
  standing: &FencerStandingItem,
  capture_live: bool,
  cooldown_active: bool,
  last_live_fetch: &mut Instant,
  british_licence: Option<&str>,
) -> CompositionCapture {
  let route = composition_route(standing.scope, standing.classifier.category);
  if let Some(reason) = skip_live_composition(route, capture_live, cooldown_active) {
    return CompositionCapture::NotCaptured { reason };
  }
  if super::composition::is_live_composition(route) {
    pace_live_fetch(last_live_fetch).await;
  }
  composition_capture_from_body(
    resolve_composition_body(fencer_id, standing, british_licence).await,
  )
}

async fn pace_live_fetch(last_live_fetch: &mut Instant) {
  let spacing = Duration::from_millis(CONF.standings_history.upstream_delay_ms);
  let elapsed = last_live_fetch.elapsed();
  if elapsed < spacing {
    tokio::time::sleep(spacing - elapsed).await;
  }
  *last_live_fetch = Instant::now();
}

async fn source_observation(standing: &FencerStandingItem) -> SourceObservation {
  match standing.scope {
    RankingScope::Unified => {
      let freshness = standing.unified.as_ref().map(|meta| &meta.freshness);
      SourceObservation {
        source_updated_at: freshness
          .and_then(|f| f.source_updated_at)
          .and_then(unix_opt),
        list_refreshed_at: freshness.and_then(|f| f.fetched_at).and_then(unix_opt),
        stale: freshness.and_then(|f| f.is_stale).unwrap_or(false),
      }
    }
    RankingScope::National | RankingScope::Regional => national_regional_source(standing).await,
    RankingScope::British => SourceObservation {
      source_updated_at: standing
        .british
        .as_ref()
        .and_then(|f| f.source_updated_at)
        .and_then(unix_opt),
      list_refreshed_at: standing
        .british
        .as_ref()
        .and_then(|f| f.fetched_at)
        .and_then(unix_opt),
      stale: standing
        .british
        .as_ref()
        .and_then(|f| f.is_stale)
        .unwrap_or(false),
    },
  }
}

async fn national_regional_source(standing: &FencerStandingItem) -> SourceObservation {
  let Some(classifier) = RecognizedClassifier::from_code(&standing.classifier.code) else {
    return SourceObservation {
      source_updated_at: None,
      list_refreshed_at: None,
      stale: false,
    };
  };
  let regional_shared = standing.scope == RankingScope::Regional
    && standings_index::is_regional_shared_category(standing.classifier.category);
  let usa_region = if regional_shared {
    None
  } else {
    standing.region_id
  };
  let list_refreshed_at =
    match standings_index::job_last_refreshed_at(usa_region, regional_shared, classifier).await {
      Ok(at) => at,
      Err(error) => {
        warn!(
          standing_key = %standing.key,
          error = ?error,
          "Failed to look up standings job last-refreshed time"
        );
        None
      }
    };
  let stale = list_refreshed_at.is_some_and(|at| {
    Utc::now() - at > chrono::Duration::hours(i64::from(CONF.standings_history.stale_after_hours))
  });
  SourceObservation {
    source_updated_at: None,
    list_refreshed_at,
    stale,
  }
}

async fn write_fencer_movement(
  fencer_id: &TypedId<FencerId>,
  run_id: &str,
  captured_at: DateTime<Utc>,
  ttl: i64,
  written: &[StandingSnapshotFields],
  standing_keys: &[String],
) -> Result<()> {
  let since =
    captured_at - chrono::Duration::days(i64::from(CONF.standings_history.movement_window_days));
  let mut snapshots = repository::list_snapshots_in_window(
    &DB.standings_history_snapshots,
    &fencer_id.to_string(),
    since,
  )
  .await?;
  for fields in written {
    let projection = projection_from_fields(fields);
    snapshots.retain(|existing| {
      existing.standing_key != projection.standing_key || existing.run_id != projection.run_id
    });
    snapshots.push(projection);
  }

  let mut receipts: Vec<SnapshotRunReceiptFields> = repository::list_receipts_in_window(
    &DB.standings_history_receipts,
    &fencer_id.to_string(),
    since,
  )
  .await?
  .into_iter()
  .map(|doc| doc.fields)
  .collect();
  receipts.retain(|receipt| receipt.run_id != run_id);
  receipts.push(SnapshotRunReceiptFields {
    fencer_id: fencer_id.to_string(),
    run_id: run_id.to_string(),
    captured_at,
    outcome: ReceiptOutcome::Succeeded {
      standing_keys: standing_keys.to_vec(),
    },
    ttl,
  });

  let summaries = compute_movement(&snapshots, &receipts, captured_at);
  write_movement(&fencer_id.to_string(), &summaries).await
}

fn projection_from_fields(fields: &StandingSnapshotFields) -> StandingSnapshotProjection {
  let (composition_state, composition_reason) = match &fields.composition {
    CompositionCapture::Complete { .. } => (Some("complete".to_string()), None),
    CompositionCapture::Unavailable { reason } => {
      (Some("unavailable".to_string()), Some(reason.clone()))
    }
    CompositionCapture::NotCaptured { reason } => (
      Some("notCaptured".to_string()),
      Some(
        serde_json::to_value(reason)
          .ok()
          .and_then(|v| v.as_str().map(str::to_string))
          .unwrap_or_else(|| format!("{reason:?}")),
      ),
    ),
  };
  StandingSnapshotProjection {
    id: generate_snapshot_id(&fields.fencer_id, &fields.standing_key, &fields.run_id),
    fencer_id: fields.fencer_id.clone(),
    standing_key: fields.standing_key.clone(),
    run_id: fields.run_id.clone(),
    captured_at: fields.captured_at,
    scope: fields.scope.clone(),
    region_id: fields.region_id,
    classifier_code: fields.classifier_code.clone(),
    rank: fields.rank.clone(),
    points: fields.points,
    entrants: fields.entrants,
    source: fields.source.clone(),
    composition_state,
    composition_reason,
  }
}

async fn upsert_failed_receipt(
  fencer_id: &TypedId<FencerId>,
  run_id: &str,
  ttl: i64,
  error: &str,
) -> Result<()> {
  repository::upsert_receipt(
    &DB.standings_history_receipts,
    SnapshotRunReceiptFields {
      fencer_id: fencer_id.to_string(),
      run_id: run_id.to_string(),
      captured_at: Utc::now(),
      outcome: ReceiptOutcome::Failed {
        error: error.to_string(),
      },
      ttl,
    },
  )
  .await?;
  Ok(())
}

fn document_ttl_seconds() -> i64 {
  ttl_seconds(CONF.standings_history.retention_days)
}

fn ttl_seconds(retention_days: u32) -> i64 {
  i64::from(retention_days) * 86_400
}

fn scope_wire(scope: RankingScope) -> String {
  match serde_json::to_value(scope) {
    Ok(serde_json::Value::String(s)) => s,
    _ => format!("{scope:?}").to_lowercase(),
  }
}

fn unix_opt(secs: i64) -> Option<DateTime<Utc>> {
  DateTime::from_timestamp(secs, 0)
}

/// Groups `(usaf id, licence)` pairs by fencer, so [`resolve_british_licence`]
/// can be applied per fencer without re-scanning the whole population.
fn group_licence_assertions(pairs: Vec<(u32, String)>) -> HashMap<u32, Vec<String>> {
  let mut grouped: HashMap<u32, Vec<String>> = HashMap::new();
  for (usaf_id, licence) in pairs {
    grouped.entry(usaf_id).or_default().push(licence);
  }
  grouped
}

#[derive(Debug, PartialEq, Eq)]
enum BritishLicenceResolution {
  /// Nobody tracking this fencer has asserted a British Fencing licence.
  None,
  /// Every household asserting a licence for this fencer agrees on it.
  Licence(String),
  /// Two or more households assert *different* licences for this fencer.
  /// We refuse rather than guess: picking one licence would silently
  /// promote one household's assertion into a fact every other viewer
  /// sees -- see
  /// docs/design-docs/british-fencing-rankings-as-a-standings-source.md,
  /// Alternative C (rejected).
  Ambiguous { distinct_count: usize },
}

/// Pure refusal rule for British capture identity ambiguity. A licence is
/// one household's private assertion, not a global fact (see
/// [`crate::v2::user::get_all_connected_fencer_licences`]), so storage --
/// which has no owner dimension -- cannot safely hold two different
/// assertions for the same fencer. Dedupes first so two households
/// asserting the *same* licence collapse to one rather than reading as
/// disagreement. Split out from the capture loop so this is unit-testable
/// without a live Redis/Cosmos connection -- see `fencer.rs`'s
/// `select_british_row` for the same shape.
fn resolve_british_licence(licences: &[String]) -> BritishLicenceResolution {
  let mut distinct: Vec<&str> = licences.iter().map(String::as_str).collect();
  distinct.sort_unstable();
  distinct.dedup();
  match distinct.as_slice() {
    [] => BritishLicenceResolution::None,
    [only] => BritishLicenceResolution::Licence((*only).to_string()),
    many => BritishLicenceResolution::Ambiguous {
      distinct_count: many.len(),
    },
  }
}

/// Resolves one fencer's British licence for this run, recording the
/// ambiguous case in `counts` and logging it at `warn` -- fencer id and
/// distinct-licence count only, never the licence values themselves (the
/// membership id is deliberately never serialized -- see the design doc's
/// "Where the membership id lives"). USA scopes are unaffected by the
/// result either way: `get_fencer_standings`/`resolve_composition_body`
/// already omit British items on `None` regardless of why.
fn resolve_fencer_british_licence(
  usaf_id: u32,
  licence_assertions: &HashMap<u32, Vec<String>>,
  counts: &mut CaptureCounts,
) -> Option<String> {
  let licences = licence_assertions
    .get(&usaf_id)
    .map(Vec::as_slice)
    .unwrap_or(&[]);
  match resolve_british_licence(licences) {
    BritishLicenceResolution::None => None,
    BritishLicenceResolution::Licence(licence) => Some(licence),
    BritishLicenceResolution::Ambiguous { distinct_count } => {
      warn!(
        usaf_id,
        distinct_licence_count = distinct_count,
        "Multiple households assert different British Fencing licences for this fencer; \
         refusing to capture a British standings snapshot for it this run"
      );
      counts.british_licence_ambiguous += 1;
      None
    }
  }
}

#[cfg(test)]
mod tests {
  use super::*;
  use standings_history::NotCapturedReason;

  #[test]
  fn document_ttl_is_retention_days_in_seconds() {
    assert_eq!(ttl_seconds(730), 63_072_000);
    assert_eq!(ttl_seconds(0), 0);
  }

  #[test]
  fn scope_wire_is_camel_case() {
    assert_eq!(scope_wire(RankingScope::National), "national");
    assert_eq!(scope_wire(RankingScope::Regional), "regional");
    assert_eq!(scope_wire(RankingScope::Unified), "unified");
    assert_eq!(scope_wire(RankingScope::British), "british");
  }

  #[test]
  fn capture_counts_complete_only_when_nothing_failed_or_was_skipped() {
    let mut counts = CaptureCounts::default();
    assert!(counts.is_complete());
    counts.fencers_unattempted = 1;
    assert!(!counts.is_complete());
    counts.fencers_unattempted = 0;
    counts.fencers_failed = 1;
    assert!(!counts.is_complete());
  }

  #[test]
  fn capture_counts_tally_composition_states() {
    let mut counts = CaptureCounts::default();
    counts.record_composition(&CompositionCapture::Unavailable {
      reason: "didNotReconcile".to_string(),
    });
    counts.record_composition(&CompositionCapture::NotCaptured {
      reason: NotCapturedReason::RunTimeBudgetExhausted,
    });
    assert_eq!(counts.compositions_unavailable, 1);
    assert_eq!(counts.compositions_not_captured, 1);
  }

  #[test]
  fn group_licence_assertions_groups_pairs_by_fencer() {
    let grouped = group_licence_assertions(vec![
      (1, "BF-AAA".to_string()),
      (1, "BF-BBB".to_string()),
      (2, "BF-CCC".to_string()),
    ]);
    assert_eq!(
      grouped.get(&1).cloned(),
      Some(vec!["BF-AAA".to_string(), "BF-BBB".to_string()])
    );
    assert_eq!(grouped.get(&2).cloned(), Some(vec!["BF-CCC".to_string()]));
    assert!(!grouped.contains_key(&3));
  }

  #[test]
  fn resolve_british_licence_is_none_with_no_assertions() {
    assert_eq!(resolve_british_licence(&[]), BritishLicenceResolution::None);
  }

  #[test]
  fn resolve_british_licence_captures_one_households_licence() {
    let licences = vec!["BF-12345".to_string()];
    assert_eq!(
      resolve_british_licence(&licences),
      BritishLicenceResolution::Licence("BF-12345".to_string())
    );
  }

  #[test]
  fn resolve_british_licence_dedupes_two_households_asserting_the_same_licence() {
    let licences = vec!["BF-12345".to_string(), "BF-12345".to_string()];
    assert_eq!(
      resolve_british_licence(&licences),
      BritishLicenceResolution::Licence("BF-12345".to_string())
    );
  }

  #[test]
  fn resolve_british_licence_refuses_when_households_disagree() {
    let licences = vec!["BF-12345".to_string(), "BF-99999".to_string()];
    assert_eq!(
      resolve_british_licence(&licences),
      BritishLicenceResolution::Ambiguous { distinct_count: 2 }
    );
  }

  #[test]
  fn resolve_fencer_british_licence_returns_none_and_untallied_when_unasserted() {
    let assertions = HashMap::new();
    let mut counts = CaptureCounts::default();
    assert_eq!(
      resolve_fencer_british_licence(100, &assertions, &mut counts),
      None
    );
    assert_eq!(counts.british_licence_ambiguous, 0);
  }

  #[test]
  fn resolve_fencer_british_licence_returns_the_agreed_licence() {
    let mut assertions = HashMap::new();
    assertions.insert(100, vec!["BF-12345".to_string(), "BF-12345".to_string()]);
    let mut counts = CaptureCounts::default();
    assert_eq!(
      resolve_fencer_british_licence(100, &assertions, &mut counts),
      Some("BF-12345".to_string())
    );
    assert_eq!(counts.british_licence_ambiguous, 0);
  }

  #[test]
  fn resolve_fencer_british_licence_refuses_and_tallies_on_disagreement() {
    let mut assertions = HashMap::new();
    assertions.insert(100, vec!["BF-12345".to_string(), "BF-99999".to_string()]);
    let mut counts = CaptureCounts::default();
    assert_eq!(
      resolve_fencer_british_licence(100, &assertions, &mut counts),
      None
    );
    assert_eq!(counts.british_licence_ambiguous, 1);
  }
}

