//! Redis run-state, the cluster-wide snapshot lock, and the movement hash
//! the capture task writes after each fencer.

use std::collections::HashMap;

use anyhow::{Result, anyhow};
use cache::{Cache, RedisCache};
use chrono::{DateTime, Utc};
use cron_schedule::previous_execution_time;
use redis::AsyncCommands;
use redis::aio::MultiplexedConnection;
use serde::{Deserialize, Serialize};
use standings_history::MovementSummary;
use tracing::warn;
use uuid::Uuid;

use super::SCHEDULE;

pub const LOCK_KEY: &str = "standings:history:v1:snapshot-lock";
pub const RUN_STATE_KEY: &str = "standings:history:v1:run-state";
pub const MOVEMENT_HASH_KEY: &str = "standings:history:v1:movement";

/// Persisted at [`RUN_STATE_KEY`] so a process restart does not lose the
/// last capture outcome. Task history is in-memory only.
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct HistoryRunState {
  pub last_attempt_at: Option<DateTime<Utc>>,
  pub last_attempt_run_id: Option<String>,
  pub last_success_at: Option<DateTime<Utc>>,
  pub last_failure_at: Option<DateTime<Utc>>,
  pub last_failure_reason: Option<String>,
  pub last_run_counts: Option<CaptureCounts>,
  /// Oldest snapshot `capturedAt` observed by a capture run. Kept in Redis
  /// rather than queried from Cosmos: the query builder has no `ORDER BY` /
  /// `MIN`, and a container scan is not an admin-status cost we want.
  pub oldest_snapshot_at: Option<DateTime<Utc>>,
  pub newest_snapshot_at: Option<DateTime<Utc>>,
}

#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct CaptureCounts {
  pub fencers_attempted: u32,
  pub fencers_succeeded: u32,
  pub fencers_failed: u32,
  pub fencers_unattempted: u32,
  pub compositions_complete: u32,
  pub compositions_unavailable: u32,
  pub compositions_not_captured: u32,
  /// Fencers whose shared British Fencing licence was set this run and so
  /// had British items requested for them (a request that can still yield
  /// zero British standing items, the same "not on that table" degrade
  /// every other read of `british_standing_items` makes).
  pub british_captured: u32,
  /// True when `standings.british_rankings_enabled` was off at the start of
  /// this run, so every British snapshot was skipped regardless of licence
  /// resolution. Recorded so this state is distinguishable from "nobody
  /// tracked a British licence" without grepping logs.
  pub british_rankings_flag_disabled: bool,
}

impl CaptureCounts {
  pub fn summary(&self) -> String {
    format!(
      "fencers attempted={} succeeded={} failed={} unattempted={}; compositions complete={} unavailable={} notCaptured={}; british captured={} flagDisabled={}",
      self.fencers_attempted,
      self.fencers_succeeded,
      self.fencers_failed,
      self.fencers_unattempted,
      self.compositions_complete,
      self.compositions_unavailable,
      self.compositions_not_captured,
      self.british_captured,
      self.british_rankings_flag_disabled
    )
  }

  pub fn is_complete(&self) -> bool {
    self.fencers_failed == 0 && self.fencers_unattempted == 0
  }

  pub fn record_composition(&mut self, capture: &standings_history::CompositionCapture) {
    match capture {
      standings_history::CompositionCapture::Complete { .. } => self.compositions_complete += 1,
      standings_history::CompositionCapture::Unavailable { .. } => {
        self.compositions_unavailable += 1
      }
      standings_history::CompositionCapture::NotCaptured { .. } => {
        self.compositions_not_captured += 1
      }
    }
  }
}

pub async fn redis_connection() -> Result<MultiplexedConnection> {
  RedisCache::get()
    .await
    .get_connection()
    .ok_or_else(|| anyhow!("Redis connection not available for standings history capture"))
}

pub async fn try_acquire_snapshot_lock(token: &str, ttl_seconds: u64) -> Result<bool> {
  let mut conn = redis_connection().await?;
  Ok(cache::try_acquire_token_lock(&mut conn, LOCK_KEY, token, ttl_seconds).await?)
}

pub async fn release_snapshot_lock(token: &str) -> Result<()> {
  let mut conn = redis_connection().await?;
  let released = cache::release_token_lock(&mut conn, LOCK_KEY, token).await?;
  if !released {
    warn!(
      "Standings history snapshot lock was no longer owned when releasing it — \
       the run likely outlived the lock TTL; another replica may now hold it"
    );
  }
  Ok(())
}

pub fn new_lock_token() -> String {
  Uuid::new_v4().to_string()
}

pub async fn read_run_state() -> Result<HistoryRunState> {
  let mut conn = redis_connection().await?;
  let payload: Option<Vec<u8>> = conn.get(RUN_STATE_KEY).await?;
  match payload {
    Some(bytes) => Ok(serde_json::from_slice(&bytes)?),
    None => Ok(HistoryRunState::default()),
  }
}

pub async fn write_run_state(state: &HistoryRunState) -> Result<()> {
  let mut conn = redis_connection().await?;
  let payload = serde_json::to_vec(state)?;
  conn.set::<_, _, ()>(RUN_STATE_KEY, payload).await?;
  Ok(())
}

pub async fn write_movement(
  fencer_id: &str,
  summaries: &HashMap<String, MovementSummary>,
) -> Result<()> {
  let mut conn = redis_connection().await?;
  let payload = serde_json::to_string(summaries)?;
  conn
    .hset::<_, _, _, ()>(MOVEMENT_HASH_KEY, fencer_id, payload)
    .await?;
  Ok(())
}

/// Reads the card movement summaries for exactly one fencer. The read path is
/// intentionally one Redis hash lookup; a cache miss means no history yet.
pub async fn read_movement(fencer_id: &str) -> Result<HashMap<String, MovementSummary>> {
  let mut conn = redis_connection().await?;
  let payload: Option<String> = conn.hget(MOVEMENT_HASH_KEY, fencer_id).await?;
  match payload {
    Some(payload) => Ok(serde_json::from_str(&payload)?),
    None => Ok(HashMap::new()),
  }
}

pub fn slot_run_id(now: DateTime<Utc>) -> Result<String> {
  let slot = previous_execution_time(SCHEDULE, now).ok_or_else(|| {
    anyhow!("standings history schedule {SCHEDULE:?} has no previous execution time")
  })?;
  Ok(slot_run_id_from(slot))
}

pub fn slot_run_id_from(slot: DateTime<Utc>) -> String {
  slot.date_naive().to_string()
}

/// `runId` must be `YYYY-MM-DD`, a Mon/Thu 07:30 UTC slot, and not later
/// than the most recent scheduled slot at `now`.
pub fn validate_run_id_at(run_id: &str, now: DateTime<Utc>) -> Result<(), String> {
  let date = chrono::NaiveDate::parse_from_str(run_id, "%Y-%m-%d")
    .map_err(|_| "runId must be YYYY-MM-DD".to_string())?;
  let slot_time = date
    .and_hms_opt(7, 30, 0)
    .map(|t| t.and_utc())
    .ok_or_else(|| "runId is not a valid date".to_string())?;
  let Some(prev) = previous_execution_time(SCHEDULE, slot_time + chrono::Duration::seconds(1))
  else {
    return Err("standings history schedule could not be parsed".to_string());
  };
  if prev != slot_time {
    return Err(format!(
      "runId {run_id} is not a scheduled Monday/Thursday 07:30 UTC slot"
    ));
  }
  let latest = previous_execution_time(SCHEDULE, now)
    .ok_or_else(|| "standings history schedule could not be parsed".to_string())?;
  if slot_time > latest {
    return Err(format!(
      "runId {run_id} is later than the most recent slot {}",
      slot_run_id_from(latest)
    ));
  }
  Ok(())
}

pub fn validate_run_id(run_id: &str) -> Result<(), String> {
  validate_run_id_at(run_id, Utc::now())
}

/// True when no capture attempt has been recorded at or after the most
/// recent scheduled slot. A recorded failure for that slot is not a miss:
/// retrying it on every replica start would re-spend the run budget.
pub fn missed_scheduled_slot(state: &HistoryRunState, now: DateTime<Utc>) -> bool {
  let Some(slot) = previous_execution_time(SCHEDULE, now) else {
    return false;
  };
  let slot_id = slot_run_id_from(slot);
  if state.last_attempt_run_id.as_deref() == Some(slot_id.as_str()) {
    return false;
  }
  let last_outcome = [
    state.last_success_at,
    state.last_failure_at,
    state.last_attempt_at,
  ]
  .into_iter()
  .flatten()
  .max();
  match last_outcome {
    None => true,
    Some(at) => at < slot,
  }
}

pub fn note_snapshot_bounds(state: &mut HistoryRunState, captured_at: DateTime<Utc>) {
  match state.oldest_snapshot_at {
    Some(oldest) if captured_at >= oldest => {}
    _ => state.oldest_snapshot_at = Some(captured_at),
  }
  match state.newest_snapshot_at {
    Some(newest) if captured_at <= newest => {}
    _ => state.newest_snapshot_at = Some(captured_at),
  }
}

#[cfg(test)]
mod tests {
  use super::*;
  use chrono::TimeZone;

  fn utc(year: i32, month: u32, day: u32, hour: u32, min: u32, sec: u32) -> DateTime<Utc> {
    Utc
      .with_ymd_and_hms(year, month, day, hour, min, sec)
      .unwrap()
  }

  #[test]
  fn schedule_fires_monday_and_thursday_at_0730_utc() {
    // 2026-09-03 is a Thursday; 2026-09-07 is a Monday.
    assert_eq!(
      previous_execution_time(SCHEDULE, utc(2026, 9, 3, 7, 30, 1)),
      Some(utc(2026, 9, 3, 7, 30, 0))
    );
    assert_eq!(
      previous_execution_time(SCHEDULE, utc(2026, 9, 4, 12, 0, 0)),
      Some(utc(2026, 9, 3, 7, 30, 0))
    );
    assert_eq!(
      previous_execution_time(SCHEDULE, utc(2026, 9, 7, 7, 31, 0)),
      Some(utc(2026, 9, 7, 7, 30, 0))
    );
  }

  #[test]
  fn slot_run_id_is_the_utc_date_of_the_most_recent_slot() {
    assert_eq!(
      slot_run_id(utc(2026, 9, 3, 15, 0, 0)).unwrap(),
      "2026-09-03"
    );
    assert_eq!(slot_run_id(utc(2026, 9, 4, 1, 0, 0)).unwrap(), "2026-09-03");
    assert_eq!(
      slot_run_id(utc(2026, 9, 7, 7, 31, 0)).unwrap(),
      "2026-09-07"
    );
  }

  #[test]
  fn validate_run_id_rejects_malformed_future_and_non_slot_dates() {
    let now = utc(2026, 9, 3, 15, 0, 0);
    assert!(validate_run_id_at("2026-09-03", now).is_ok());
    assert!(validate_run_id_at("2026-08-31", now).is_ok());
    assert_eq!(
      validate_run_id_at("not-a-date", now).unwrap_err(),
      "runId must be YYYY-MM-DD"
    );
    assert!(
      validate_run_id_at("2026-09-02", now)
        .unwrap_err()
        .contains("not a scheduled")
    );
    assert!(
      validate_run_id_at("2026-09-07", now)
        .unwrap_err()
        .contains("later than the most recent slot")
    );
  }

  #[test]
  fn missed_scheduled_slot_is_true_when_nothing_has_run_since_the_slot() {
    let now = utc(2026, 9, 3, 8, 0, 0);
    assert!(missed_scheduled_slot(&HistoryRunState::default(), now));

    let attempted_this_slot = HistoryRunState {
      last_attempt_at: Some(utc(2026, 9, 3, 7, 31, 0)),
      last_attempt_run_id: Some("2026-09-03".to_string()),
      last_failure_at: Some(utc(2026, 9, 3, 7, 31, 0)),
      last_failure_reason: Some("boom".to_string()),
      ..HistoryRunState::default()
    };
    assert!(!missed_scheduled_slot(&attempted_this_slot, now));

    let last_week = HistoryRunState {
      last_attempt_at: Some(utc(2026, 8, 31, 7, 31, 0)),
      last_attempt_run_id: Some("2026-08-31".to_string()),
      last_success_at: Some(utc(2026, 8, 31, 7, 31, 0)),
      ..HistoryRunState::default()
    };
    assert!(missed_scheduled_slot(&last_week, now));
  }

  #[test]
  fn run_state_serializes_camel_case_keys() {
    let state = HistoryRunState {
      last_attempt_at: Some(utc(2026, 9, 3, 7, 31, 0)),
      last_attempt_run_id: Some("2026-09-03".to_string()),
      last_success_at: Some(utc(2026, 9, 3, 7, 31, 0)),
      last_failure_at: None,
      last_failure_reason: None,
      last_run_counts: Some(CaptureCounts {
        fencers_attempted: 2,
        fencers_succeeded: 2,
        ..CaptureCounts::default()
      }),
      oldest_snapshot_at: Some(utc(2026, 9, 3, 7, 31, 0)),
      newest_snapshot_at: Some(utc(2026, 9, 3, 7, 31, 0)),
    };
    let value = serde_json::to_value(&state).unwrap();
    assert_eq!(value["lastAttemptRunId"], "2026-09-03");
    assert_eq!(value["lastRunCounts"]["fencersAttempted"], 2);
    assert_eq!(value["lastRunCounts"]["fencersSucceeded"], 2);
    assert!(value.get("last_attempt_run_id").is_none());
    assert!(value["lastRunCounts"].get("fencers_attempted").is_none());
  }

  #[test]
  fn summary_includes_british_capture_fields() {
    let counts = CaptureCounts {
      british_captured: 3,
      british_rankings_flag_disabled: true,
      ..CaptureCounts::default()
    };
    assert!(
      counts
        .summary()
        .contains("british captured=3 flagDisabled=true")
    );
  }

  #[test]
  fn capture_counts_serializes_british_fields_as_camel_case() {
    let counts = CaptureCounts {
      british_captured: 3,
      british_rankings_flag_disabled: true,
      ..CaptureCounts::default()
    };
    let value = serde_json::to_value(&counts).unwrap();
    assert_eq!(value["britishCaptured"], 3);
    assert_eq!(value["britishRankingsFlagDisabled"], true);
    assert!(value.get("british_captured").is_none());
    assert!(value.get("britishLicenceAmbiguous").is_none());
    assert!(value.get("british_rankings_flag_disabled").is_none());
  }
}

