#[derive(Serialize, Clone, Debug, Deserialize, Hash, PartialEq, Eq, Builder)]
#[serde(rename_all = "camelCase")]
pub struct EventFields {
  pub id_detail: Option<IdDetail>,
  /// The category of this event
  pub classifier: EventClassifier,
  #[builder(default)]
  pub date: Option<NaiveDate>,
  #[builder(default)]
  pub matches: Option<Vec<Match>>,
  #[builder(default)]
  pub start_time: Option<NaiveTime>,
  #[builder(default)]
  pub end_time: Option<NaiveTime>,
  #[builder(default)]
  pub status: Option<EventStatus>,
  #[builder(default)]
  pub live: Option<LiveEvent>,
  #[builder(default)]
  pub rating: Option<EventRating>,
  #[builder(default)]
  pub registered_fencers: Option<u16>,
  #[builder(default)]
  pub total_spots: Option<u16>,

  /// The id of the timezone the event occurs in (e.g. "America/Los_Angeles"). You can
  /// use this along with the date + start_time to get the actual start time of the event.
  #[builder(default)]
  pub time_zone_id: Option<String>,
}

impl HasIdDetail for EventFields {
  fn id_detail(&self) -> &IdDetail {
    self.id_detail.as_ref().unwrap_or(&DEFAULT_ID_DETAIL)
  }
}

impl EventFields {
  /// Gets the start of this event as a NaiveDateTime. If there's no start time yet, this
  /// will return None.
  pub fn get_start(&self) -> Option<NaiveDateTime> {
    if let (Some(start_date), Some(start_time)) = (self.date, self.start_time) {
      Some(NaiveDateTime::new(start_date, start_time))
    } else {
      None
    }
  }

  pub fn set_ftl_id(&mut self, id: &str) {
    match self.id_detail {
      None => {
        self.id_detail = Some(
          IdDetailBuilder::default()
            .ftl_id(Some(id.to_string()))
            .build()
            .unwrap(),
        )
      }
      Some(ref mut id_detail) => {
        id_detail.ftl_id = Some(id.to_string());
      }
    }
  }

  fn has_match(&self, other: &Match) -> bool {
    if let Some(matches) = &self.matches {
      for m in matches {
        if m.left == other.left && m.right == other.right && m.stage == other.stage {
          return true;
        }
      }
    }
    false
  }

  /// Adds a match, but only if it's not already present, based on the left & right participant and
  /// stage.
  pub fn add_match(&mut self, m: Match) {
    if self.has_match(&m) {
      return;
    }
    match self.matches {
      None => {
        self.matches = Some(vec![m]);
      }
      Some(ref mut matches) => {
        matches.push(m);
      }
    }
  }
}

