#[cfg(test)]
mod model_behavior_tests {
  use super::*;
  use crate::usafencing::model::{TimelineItem, TimelineKind};
  use chrono::{DateTime, NaiveDate, NaiveTime, Utc};
  use ids::Identified;
  use model_common::{EventCategory, EventGender, RecognizedClassifier, Weapon};

  fn test_event(classifier: EventClassifier, id: &str) -> Event {
    let fields = EventFieldsBuilder::default()
      .id_detail(None)
      .classifier(classifier)
      .build()
      .unwrap();
    Identified::new(id, fields)
  }

  fn test_match() -> Match {
    Match {
      stage: Stage::Pool(PoolDetails { sequence: 1 }),
      left: Participant {
        seed: Some(1),
        individual: Some(Individual {
          fencer: MatchFencer::FencerId("left-id".to_string()),
          score: Some(5),
          outcome: Some(MatchOutcome::Win),
        }),
        is_bye: false,
      },
      right: Participant {
        seed: Some(2),
        individual: Some(Individual {
          fencer: MatchFencer::FencerId("right-id".to_string()),
          score: Some(3),
          outcome: Some(MatchOutcome::Lose),
        }),
        is_bye: false,
      },
      video_link: None,
    }
  }

  #[test]
  fn tournament_date_range_methods_require_dates() {
    let with_dates = TournamentFieldsBuilder::default()
      .id_detail(IdDetailBuilder::default().build().unwrap())
      .name("Tournament".to_string())
      .start_date(Some(NaiveDate::from_ymd_opt(2026, 3, 1).unwrap()))
      .end_date(Some(NaiveDate::from_ymd_opt(2026, 3, 3).unwrap()))
      .build()
      .unwrap();
    let without_dates = TournamentFieldsBuilder::default()
      .id_detail(IdDetailBuilder::default().build().unwrap())
      .name("Tournament".to_string())
      .build()
      .unwrap();

    assert!(with_dates.in_date_range(
      NaiveDate::from_ymd_opt(2026, 2, 28).unwrap(),
      NaiveDate::from_ymd_opt(2026, 3, 5).unwrap()
    ));
    assert!(with_dates.starts_after(NaiveDate::from_ymd_opt(2026, 2, 28).unwrap()));
    assert!(!without_dates.in_date_range(
      NaiveDate::from_ymd_opt(2026, 2, 28).unwrap(),
      NaiveDate::from_ymd_opt(2026, 3, 5).unwrap()
    ));
    assert!(!without_dates.starts_after(NaiveDate::from_ymd_opt(2026, 2, 28).unwrap()));
  }

  #[test]
  fn tournament_registration_open_uses_timeline_registration_open_event() {
    let open_date = DateTime::parse_from_rfc3339("2026-01-10T12:00:00Z")
      .unwrap()
      .with_timezone(&Utc);
    let before = DateTime::parse_from_rfc3339("2026-01-10T11:59:59Z")
      .unwrap()
      .with_timezone(&Utc);
    let after = DateTime::parse_from_rfc3339("2026-01-10T12:00:01Z")
      .unwrap()
      .with_timezone(&Utc);

    let tournament = TournamentFieldsBuilder::default()
      .id_detail(IdDetailBuilder::default().build().unwrap())
      .name("Tournament".to_string())
      .timeline(vec![TimelineItem {
        kind: TimelineKind::RegistrationOpens,
        date: open_date,
      }])
      .build()
      .unwrap();

    assert!(!tournament.is_registration_open(before));
    assert!(tournament.is_registration_open(after));
  }

  #[test]
  fn tournament_event_lookup_and_classifier_aggregation_work() {
    let recognized = EventClassifier::Recognized(RecognizedClassifier {
      weapon: Weapon::Foil,
      gender: EventGender::Mens,
      category: EventCategory::Junior,
      team: false,
    });
    let unrecognized = EventClassifier::Unrecognized("OPEN".to_string());

    let event1 = test_event(recognized.clone(), "event-1");
    let event2 = test_event(unrecognized.clone(), "event-2");

    let tournament = TournamentFieldsBuilder::default()
      .id_detail(IdDetailBuilder::default().build().unwrap())
      .name("Tournament".to_string())
      .events(vec![event1.clone(), event2.clone()])
      .build()
      .unwrap();

    assert_eq!(tournament.get_weapons(), vec!["Foil".to_string()]);
    assert!(tournament.get_classifiers().contains(&recognized));
    assert!(tournament.get_classifiers().contains(&unrecognized));
    assert_eq!(
      tournament.find_event(&recognized).map(|e| e.id.clone()),
      Some(event1.id)
    );
    assert_eq!(
      tournament.get_event("event-2").map(|e| e.id.clone()),
      Some(event2.id)
    );
  }

  #[test]
  fn event_fields_get_start_combines_date_and_time() {
    let fields = EventFieldsBuilder::default()
      .id_detail(None)
      .classifier(EventClassifier::Unrecognized("OPEN".to_string()))
      .date(Some(NaiveDate::from_ymd_opt(2026, 4, 3).unwrap()))
      .start_time(Some(NaiveTime::from_hms_opt(9, 30, 0).unwrap()))
      .build()
      .unwrap();

    assert_eq!(
      fields.get_start(),
      Some(
        NaiveDate::from_ymd_opt(2026, 4, 3)
          .unwrap()
          .and_hms_opt(9, 30, 0)
          .unwrap()
      )
    );
  }

  #[test]
  fn event_fields_add_match_deduplicates_same_match() {
    let mut fields = EventFieldsBuilder::default()
      .id_detail(None)
      .classifier(EventClassifier::Unrecognized("OPEN".to_string()))
      .build()
      .unwrap();
    let m = test_match();

    fields.add_match(m.clone());
    fields.add_match(m);

    assert_eq!(fields.matches.as_ref().map(|ms| ms.len()), Some(1));
  }

  #[test]
  fn event_fields_set_ftl_id_creates_or_updates_id_detail() {
    let mut fields = EventFieldsBuilder::default()
      .id_detail(None)
      .classifier(EventClassifier::Unrecognized("OPEN".to_string()))
      .build()
      .unwrap();
    fields.set_ftl_id("ftl-1");
    assert_eq!(
      fields.id_detail.as_ref().and_then(|d| d.ftl_id.clone()),
      Some("ftl-1".to_string())
    );

    fields.set_ftl_id("ftl-2");
    assert_eq!(
      fields.id_detail.as_ref().and_then(|d| d.ftl_id.clone()),
      Some("ftl-2".to_string())
    );
  }

  #[test]
  fn user_capability_is_known_returns_false_only_for_unknown() {
    assert!(UserCapability::Developer.is_known());
    assert!(!UserCapability::Unknown.is_known());
  }
}

