#[serde(rename_all = "camelCase")]
pub struct TrackedFencer {
  pub fencer_id: ViewTypedId<FencerId>,
  #[serde(default)]
  pub results_backfill: ResultsBackfillStatus,
  /// British Fencing membership id (their "Licence"), joined against the
  /// British Fencing live-ranking tables' `Licence` column. Optional; most
  /// tracked fencers will never have one. See
  /// docs/design-docs/british-fencing-rankings-as-a-standings-source.md,
  /// "Where the membership id lives".
  #[serde(default, skip_serializing_if = "Option::is_none")]
