}

#[derive(Default, Deserialize, Serialize, Clone, Debug, Hash, PartialEq, Eq)]
#[serde(rename_all = "camelCase")]
pub enum ResultsBackfillState {
  #[default]
  LegacyComplete,
  BlockedOnCapability,
  Queued,
  Running,
  Complete,
  Failed,
}

#[derive(Deserialize, Serialize, Clone, Debug, Hash, PartialEq, Eq)]
#[serde(rename_all = "camelCase")]
pub struct ResultsBackfillStatus {
  pub state: ResultsBackfillState,
  pub requested_at: Option<DateTime<Utc>>,
  pub started_at: Option<DateTime<Utc>>,
  pub completed_at: Option<DateTime<Utc>>,
  pub attempts: u32,
  pub events_total: Option<u32>,
  pub events_processed: u32,
  pub bouts_upserted: u32,
  pub unresolved_event_ids: u32,
  pub last_error: Option<String>,
}

impl Default for ResultsBackfillStatus {
  fn default() -> Self {
    Self {
      state: ResultsBackfillState::LegacyComplete,
      requested_at: None,
      started_at: None,
      completed_at: None,
      attempts: 0,
      events_total: None,
      events_processed: 0,
      bouts_upserted: 0,
      unresolved_event_ids: 0,
      last_error: None,
    }
  }
}

impl ResultsBackfillStatus {
  pub fn blocked_on_capability() -> Self {
    Self {
      state: ResultsBackfillState::BlockedOnCapability,
      ..Default::default()
    }
  }

  pub fn queued(requested_at: DateTime<Utc>) -> Self {
    Self {
      state: ResultsBackfillState::Queued,
      requested_at: Some(requested_at),
      ..Default::default()
    }
  }
}

#[cfg(test)]
mod tracked_fencer_tests {
  use super::*;

  #[test]
  fn test_deserialize_usaf_id() {
    let json = r#"{"fencerId": "f.u.12345678"}"#;
    let tf: TrackedFencer = serde_json::from_str(json).unwrap();
    assert!(tf.fencer_id.is_usaf());
    assert_eq!(tf.fencer_id.as_str(), "12345678");
    assert_eq!(tf.fencer_id.to_view_string(), "f.u.12345678");
    assert_eq!(
      tf.results_backfill.state,
      ResultsBackfillState::LegacyComplete
    );
    assert_eq!(tf.british_fencing_licence, None);
  }

  #[test]
  fn test_british_fencing_licence_round_trips_and_is_omitted_when_absent() {
    let json = r#"{"fencerId": "f.u.12345678"}"#;
    let tf: TrackedFencer = serde_json::from_str(json).unwrap();
    assert_eq!(tf.british_fencing_licence, None);
    let serialized = serde_json::to_string(&tf).unwrap();
    assert!(!serialized.contains("britishFencingLicence"));

    let json = r#"{"fencerId": "f.u.12345678", "britishFencingLicence": "142013"}"#;
    let tf: TrackedFencer = serde_json::from_str(json).unwrap();
    assert_eq!(tf.british_fencing_licence, Some("142013".to_string()));
    let serialized = serde_json::to_string(&tf).unwrap();
    assert!(serialized.contains(r#""britishFencingLicence":"142013""#));
  }

  #[test]
  fn test_deserialize_with_backfill_status() {
    let json = r#"{
      "fencerId": "f.u.12345678",
      "resultsBackfill": {
        "state": "queued",
        "attempts": 1,
        "eventsProcessed": 2,
        "boutsUpserted": 3,
        "unresolvedEventIds": 4
      }
    }"#;
    let tf: TrackedFencer = serde_json::from_str(json).unwrap();
    assert_eq!(tf.results_backfill.state, ResultsBackfillState::Queued);
    assert_eq!(tf.results_backfill.attempts, 1);
    assert_eq!(tf.results_backfill.events_processed, 2);
    assert_eq!(tf.results_backfill.bouts_upserted, 3);
    assert_eq!(tf.results_backfill.unresolved_event_ids, 4);
  }

  #[test]
  fn test_deserialize_with_blocked_state() {
    let json = r#"{
      "fencerId": "f.u.12345678",
      "resultsBackfill": {
        "state": "blockedOnCapability",
        "attempts": 0,
        "eventsProcessed": 0,
        "boutsUpserted": 0,
        "unresolvedEventIds": 0
      }
    }"#;
    let tf: TrackedFencer = serde_json::from_str(json).unwrap();
    assert_eq!(
      tf.results_backfill.state,
      ResultsBackfillState::BlockedOnCapability
    );
  }
}

