  pub super_circuit: Option<bool>,

  #[builder(setter(into), default)]
  #[serde(default, deserialize_with = "null_as_default")]
  pub timeline: Vec<TimelineItem>,

  /// This is only filled in for scheduled events before they're
  /// live on usafencing, replacing the events.
  #[builder(setter(into, strip_option), default)]
  #[serde(default, deserialize_with = "null_as_default")]
  pub categories: Vec<EventCategory>,
}

impl HasIdDetail for TournamentFields {
  fn id_detail(&self) -> &IdDetail {
    &self.id_detail
  }
}

impl TournamentFields {
  pub fn in_date_range(&self, start: NaiveDate, end: NaiveDate) -> bool {
    if let (Some(my_start), Some(my_end)) = (self.start_date, self.end_date) {
      return my_start >= start && my_end <= end;
    }
    false
  }

  pub fn starts_after(&self, start: NaiveDate) -> bool {
    if let Some(my_start) = self.start_date {
      return my_start >= start;
    }
    false
  }

  fn get_timeline_time(&self, kind: TimelineKind) -> Option<DateTime<Utc>> {
    self
      .timeline
      .iter()
      .find(|tl| tl.kind == kind)
      .map(|tl| tl.date)
  }

  /// Returns true if now is >= the registration open date for this tournament,
  /// based on its timeline.
  pub fn is_registration_open(&self, now: DateTime<Utc>) -> bool {
    let open_date = self.get_timeline_time(TimelineKind::RegistrationOpens);
    open_date.map(|d| now >= d).unwrap_or_default()
  }

  /// The timestamp registration opened for this tournament, per its cached
  /// timeline, or `None` if that timeline entry hasn't been observed.
  pub fn registration_opened_at(&self) -> Option<DateTime<Utc>> {
    self.get_timeline_time(TimelineKind::RegistrationOpens)
  }

  pub fn get_weapons(&self) -> Vec<String> {
    self
      .events
      .iter()
      .filter_map(|e| e.fields.classifier.get_weapon())
      .map(|w| w.to_string())
      .collect_vec()
  }

  pub fn get_classifiers(&self) -> HashSet<EventClassifier> {
    self
      .events
      .iter()
      .map(|e| e.fields.classifier.clone())
      .collect::<HashSet<_>>()
  }

  pub fn find_event(&self, classifier: &EventClassifier) -> Option<&Event> {
    self
      .events
      .iter()
      .find(|e| e.fields.classifier == *classifier)
  }

  pub fn get_event(&self, event_id: &str) -> Option<&Event> {
    self.events.iter().find(|e| e.id == event_id)
  }
}

