use anyhow::{Result, anyhow};
use chrono::Utc;
use json_patch::Patch;
use thiserror::Error;
use tracing::warn;

use crate::db::DB;
use cache::{RedisCache, redis_cached};
use ids::{FamilyGroupId, FencerId, System, TypedId as ViewTypedId, UserId};
use util::eq;

use super::model::{
  CapabilityConfigDoc, CapabilityConfigFields, CapabilityRollout, Fencer, FencerRelationship,
  FencerRelationshipDisplay, Identified, ResultsBackfillState, ResultsBackfillStatus,
  TrackedFencer, User, UserCapability,
};

/// The well-known ID for the capability config document.
pub const CAPABILITY_CONFIG_ID: &str = "capability-config";

// ============================================================================
// Error types
// ============================================================================

/// Errors that can occur during user operations.
#[derive(Error, Debug)]
pub enum UserError {
  #[error("User not found: {0}")]
  NotFound(String),

  #[error("Database error: {0}")]
  Database(#[from] anyhow::Error),
}

