pub async fn get_user(id: &str) -> Result<Option<User>> {
  DB.users.first_document_where(&eq!("c.id", id)).await
}

redis_cached! {
  name = "user_by_id",
  key = String,
  value = User,
  map_err = |e| anyhow::anyhow!("Cache error: {}", e),
  // Preserve the existing sliding TTL-on-read policy.
  refresh = true,
  /// Gets a user by ID, using Redis cache to avoid repeated DB lookups.
  /// The cache has a 30-minute TTL (configured via `user_by_id` in cache.ttl config).
  pub async fn get_user_cached(id: String) -> Result<User> {
    get_user(&id)
      .await?
      .ok_or_else(|| anyhow!("User not found: {}", id))
  }
}

/// Invalidates all cached user data for a user given their User object.
/// This is the preferred method when you already have the user data.
///
/// This function directly deletes from Redis rather than going through the
/// OnceCell-based cache clients, ensuring invalidation works even if the
/// cached functions haven't been called yet on this server instance.
pub async fn invalidate_all_user_caches(user: &User) {
  let cache = RedisCache::get().await;

  // Invalidate by ID
  cache.invalidate_io_cached_key("user_by_id", &user.id).await;

  // Invalidate by clerk_id if present
  if let Some(clerk_id) = &user.fields.clerk_user_id {
    cache
      .invalidate_io_cached_key("user_by_clerk_id", clerk_id)
      .await;
  }

  // Invalidate by email
  cache
    .invalidate_io_cached_key("user_by_email", &user.fields.primary_user.email)
    .await;
}

/// Invalidates all cached user data for a user by ID.
/// This fetches the user first to get clerk_id and email for full invalidation.
pub async fn invalidate_user_cache(id: &str) {
  // First, try to get the user to find their clerk_id and email for cache invalidation
  // We fetch from DB directly to avoid using stale cached data
  if let Ok(Some(user)) = get_user(id).await {
    invalidate_all_user_caches(&user).await;
  } else {
    // At minimum, invalidate by ID even if we can't find the user
    let cache = RedisCache::get().await;
    cache.invalidate_io_cached_key("user_by_id", &id).await;
  }
}

redis_cached! {
  name = "user_by_clerk_id",
  key = String,
  value = Option<User>,
  map_err = |e| anyhow::anyhow!("Cache error: {}", e),
  // Preserve the existing sliding TTL-on-read policy.
  refresh = true,
  /// Gets a user by Clerk ID, using Redis cache to avoid repeated DB lookups.
  pub async fn get_user_by_clerk_id_cached(clerk_id: String) -> Result<Option<User>> {
    DB.users
      .first_document_where(&eq!("c.clerkUserId", &clerk_id))
      .await
  }
}

redis_cached! {
