pub async fn get_all_users() -> Result<Vec<User>> {
  DB.users.list_documents().await
}

pub async fn set_user_capabilities(
  id: &str,
  capabilities: Vec<super::model::UserCapability>,
) -> Result<User> {
  let original = get_user(id).await?;
  if let Some(mut original) = original {
    let had_results_capability = has_results_capability(&original.fields.capabilities);
    let has_results_capability = has_results_capability(&capabilities);

    // Update the capabilities field
    original.fields.capabilities = capabilities;

    if !had_results_capability && has_results_capability {
      enqueue_blocked_backfills(&mut original.fields.tracked_fencers, Utc::now());
    }

    // Use upsert to replace the entire document - this avoids all the PATCH issues
    // with missing fields in legacy documents
    let result = DB.users.upsert_document(original).await?;
    invalidate_user_cache(id).await;
    return Ok(result);
  }
  Err(anyhow!("Can't find user"))
}

/// Adds a tracked fencer to the user's tracked_fencers list.
/// Returns error if the fencer is already being tracked.
/// The fencer_id should be a ViewTypedId - either f.u.{usaf_id} for USAF IDs or f.d.{db_id} for database IDs.
pub async fn add_tracked_fencer(user_id: &str, fencer_id: ViewTypedId<FencerId>) -> Result<()> {
  let user = get_user(user_id)
    .await?
    .ok_or_else(|| anyhow!("User not found: {}", user_id))?;

  // Check if already tracking this fencer (compare raw ID part)
  if user
    .fields
    .tracked_fencers
    .iter()
    .any(|tf| tf.fencer_id.as_str() == fencer_id.as_str())
  {
    return Err(anyhow!("Already tracking fencer: {}", fencer_id.as_str()));
  }

  let mut updated_user = user.clone();
  let results_backfill =
    initial_backfill_status_for_capabilities(&user.fields.capabilities, Utc::now());
  updated_user.fields.tracked_fencers.push(TrackedFencer {
    fencer_id,
    results_backfill,
    british_fencing_licence: None,
  });

  DB.users.patch_document(&user, &updated_user).await?;
  invalidate_user_cache(user_id).await;
  Ok(())
}

fn has_results_capability(capabilities: &[UserCapability]) -> bool {
  capabilities.contains(&UserCapability::TabResults)
}

fn initial_backfill_status_for_capabilities(
  capabilities: &[UserCapability],
  requested_at: chrono::DateTime<Utc>,
) -> ResultsBackfillStatus {
  if has_results_capability(capabilities) {
    ResultsBackfillStatus::queued(requested_at)
  } else {
    ResultsBackfillStatus::blocked_on_capability()
  }
}

fn enqueue_blocked_backfills(
  tracked_fencers: &mut [TrackedFencer],
  requested_at: chrono::DateTime<Utc>,
) {
  for tracked in tracked_fencers.iter_mut() {
    if tracked.results_backfill.state == ResultsBackfillState::BlockedOnCapability {
      tracked.results_backfill = ResultsBackfillStatus::queued(requested_at);
    }
  }
}

/// Removes a tracked fencer from the user's tracked_fencers list.
/// The fencer_id should be in view format: "f.u.12345"
pub async fn remove_tracked_fencer(user_id: &str, fencer_id: &str) -> Result<()> {
  let user = get_user(user_id)
    .await?
    .ok_or_else(|| anyhow!("User not found: {}", user_id))?;

  let original_len = user.fields.tracked_fencers.len();
  let mut updated_user = user.clone();

  updated_user
    .fields
    .tracked_fencers
    .retain(|tf| tf.fencer_id.to_view_string() != fencer_id);

  if updated_user.fields.tracked_fencers.len() == original_len {
    return Err(anyhow!("Fencer not being tracked: {}", fencer_id));
  }

  DB.users.patch_document(&user, &updated_user).await?;
  invalidate_user_cache(user_id).await;
  Ok(())
}

/// Sets or clears the British Fencing membership id (their "Licence") on a
/// tracked fencer. `licence: None` clears it. Returns an error if the fencer
/// is not being tracked.
/// Returns `Ok(false)` (rather than an error) if `fencer_id` is not one of
/// the user's tracked fencers, so callers can distinguish "not tracked" (a
/// 404) from a genuine database failure (a 500) instead of matching on an
/// `anyhow` error message.
pub async fn set_tracked_fencer_british_fencing_licence(
  user_id: &str,
  fencer_id: &str,
  licence: Option<String>,
) -> Result<bool> {
  let user = get_user(user_id)
    .await?
    .ok_or_else(|| anyhow!("User not found: {}", user_id))?;

  let mut updated_user = user.clone();
  let Some(tracked) = updated_user
    .fields
    .tracked_fencers
    .iter_mut()
    .find(|tf| tf.fencer_id.to_view_string() == fencer_id)
  else {
    return Ok(false);
  };
  tracked.british_fencing_licence = licence;

  DB.users.patch_document(&user, &updated_user).await?;
  invalidate_user_cache(user_id).await;
  Ok(true)
}

fn same_fencer_id(left: &ViewTypedId<FencerId>, right: &ViewTypedId<FencerId>) -> bool {
  left.to_view_string() == right.to_view_string()
}

fn relationship_for_fencer_mut<'a>(
  relationships: &'a mut [FencerRelationship],
  fencer_id: &ViewTypedId<FencerId>,
) -> Option<&'a mut FencerRelationship> {
  relationships
    .iter_mut()
    .find(|relationship| same_fencer_id(&relationship.fencer_id, fencer_id))
}

fn first_rating_classification(fencer: &Fencer) -> Option<String> {
  let ratings = fencer.fields.current_ratings.as_ref()?;
  ratings
    .foil
    .as_ref()
    .or(ratings.epee.as_ref())
    .or(ratings.sabre.as_ref())
    .map(|rating| rating.classification.clone())
}

async fn lookup_fencer_for_relationship(
  fencer_id: &ViewTypedId<FencerId>,
) -> Result<Option<Fencer>> {
  match fencer_id.system() {
    System::Usaf => {
      let mut matches = DB
        .fencers
        .list_documents_where(&eq!("c.idDetail.usafId", fencer_id.as_str()))
        .await?;
      Ok(matches.pop())
    }
    System::Database => DB.fencers.get_document(fencer_id.as_str()).await,
    unsupported => {
      warn!(
        fencer_id = %fencer_id,
        ?unsupported,
        "Skipping relationship display lookup for unsupported fencer system"
      );
      Ok(None)
    }
  }
}

async fn build_relationship_display_snapshot(
  fencer_id: &ViewTypedId<FencerId>,
) -> Result<Option<FencerRelationshipDisplay>> {
  let fencer = lookup_fencer_for_relationship(fencer_id).await?;
  Ok(fencer.map(|fencer| FencerRelationshipDisplay {
    name: fencer.fields.name.clone(),
    club: fencer.fields.current_club_name.clone(),
    country: fencer.fields.country.clone(),
    rating: first_rating_classification(&fencer),
  }))
}

pub async fn follow_fencer(
  user_id: &str,
  fencer_id: ViewTypedId<FencerId>,
) -> Result<FencerRelationship> {
  let user = get_user(user_id)
    .await?
    .ok_or_else(|| anyhow!("User not found: {}", user_id))?;
  let mut updated_user = user.clone();

  if let Some(existing) =
    relationship_for_fencer_mut(&mut updated_user.fields.fencer_relationships, &fencer_id)
  {
    existing.following = true;
    if existing.display.is_none() {
      existing.display = build_relationship_display_snapshot(&fencer_id).await?;
    }
    let result = existing.clone();
    DB.users.patch_document_safe(&user, &updated_user).await?;
    invalidate_user_cache(user_id).await;
    return Ok(result);
  }

  let relationship = FencerRelationship {
    fencer_id: fencer_id.clone(),
    following: true,
    notify: true,
    competition_history: Vec::new(),
    display: build_relationship_display_snapshot(&fencer_id).await?,
  };
  updated_user
    .fields
    .fencer_relationships
    .push(relationship.clone());

  DB.users.patch_document_safe(&user, &updated_user).await?;
  invalidate_user_cache(user_id).await;
  Ok(relationship)
}

pub async fn unfollow_fencer(user_id: &str, fencer_id: &ViewTypedId<FencerId>) -> Result<()> {
  let user = get_user(user_id)
    .await?
    .ok_or_else(|| anyhow!("User not found: {}", user_id))?;
  let mut updated_user = user.clone();

  let idx = updated_user
    .fields
    .fencer_relationships
    .iter()
    .position(|relationship| same_fencer_id(&relationship.fencer_id, fencer_id))
    .ok_or_else(|| anyhow!("Fencer relationship not found: {}", fencer_id))?;

  if updated_user.fields.fencer_relationships[idx]
    .competition_history
    .is_empty()
  {
    updated_user.fields.fencer_relationships.remove(idx);
  } else {
    updated_user.fields.fencer_relationships[idx].following = false;
  }

  DB.users.patch_document_safe(&user, &updated_user).await?;
  invalidate_user_cache(user_id).await;
  Ok(())
}

pub async fn set_fencer_relationship_notify(
  user_id: &str,
  fencer_id: &ViewTypedId<FencerId>,
  notify: bool,
) -> Result<FencerRelationship> {
  let user = get_user(user_id)
    .await?
    .ok_or_else(|| anyhow!("User not found: {}", user_id))?;
  let mut updated_user = user.clone();

  let relationship =
    relationship_for_fencer_mut(&mut updated_user.fields.fencer_relationships, fencer_id)
      .ok_or_else(|| anyhow!("Fencer relationship not found: {}", fencer_id))?;

  if !relationship.following {
    return Err(anyhow!(
      "Cannot update notify setting for unfollowed fencer: {}",
      fencer_id
    ));
  }

  relationship.notify = notify;
  let result = relationship.clone();

  DB.users.patch_document_safe(&user, &updated_user).await?;
  invalidate_user_cache(user_id).await;
  Ok(result)
}

pub async fn patch_user(id: &str, patch: &Patch) -> Result<User> {
  let original = get_user(id).await?;
  if let Some(original) = original {
    let tracked_fencer_patch_lockdown_enabled = load_tracked_fencer_patch_lockdown_enabled().await;
    validate_user_patch_paths(patch, tracked_fencer_patch_lockdown_enabled)?;

    // Apply the user's patch to the fields portion
    let mut fields_json = serde_json::to_value(&original.fields)?;
    json_patch::patch(&mut fields_json, patch)?;
    let updated_fields = serde_json::from_value(fields_json)?;

    let mut updated_user = original.clone();
    updated_user.fields = updated_fields;

    // Use patch_document_safe to handle Cosmos DB quirks with empty arrays
    // and missing parent paths (e.g., preferences.events.weapons)
    let result = DB
      .users
      .patch_document_safe(&original, &updated_user)
      .await?;
    invalidate_user_cache(id).await;
    return Ok(result);
  }
  Err(anyhow!("Can't find user"))
}

async fn load_tracked_fencer_patch_lockdown_enabled() -> bool {
  match crate::flags::list_flags().await {
    Ok(statuses) => crate::flag!(statuses, USER_PATCH_TRACKED_FENCERS_LOCKDOWN_ENABLED),
    Err(error) => {
      warn!(
        error = %error,
        "Failed to load runtime flags; allowing trackedFencers patch operations"
      );
      false
    }
  }
}

fn validate_user_patch_paths(
  patch: &Patch,
  tracked_fencer_patch_lockdown_enabled: bool,
) -> Result<()> {
  // Security check: prevent users from modifying their own capabilities or groups.
  // These can only be modified through admin endpoints.
  for op in patch.0.iter() {
    let path = match op {
      json_patch::PatchOperation::Add(a) => &a.path,
      json_patch::PatchOperation::Remove(r) => &r.path,
      json_patch::PatchOperation::Replace(r) => &r.path,
      json_patch::PatchOperation::Move(m) => &m.path,
      json_patch::PatchOperation::Copy(c) => &c.path,
      json_patch::PatchOperation::Test(t) => &t.path,
    };

    let path_str = path.as_str();
    if path_str.contains("capabilities") {
      return Err(anyhow!("Users cannot modify their own capabilities"));
    }
    if path_str.contains("groups") {
      return Err(anyhow!("Users cannot modify their own groups"));
    }
    if tracked_fencer_patch_lockdown_enabled
      && (path_str == "/trackedFencers" || path_str.starts_with("/trackedFencers/"))
    {
      return Err(anyhow!(
        "Users cannot modify trackedFencers via generic patch endpoint"
      ));
    }
  }

  Ok(())
}

