/// Gets the capability configuration document, creating a default one if it doesn't exist.
pub async fn get_capability_config() -> Result<CapabilityConfigDoc> {
  let result = DB.config.get_document(CAPABILITY_CONFIG_ID).await?;

  if let Some(config) = result {
    Ok(config)
  } else {
    // Create default config
    let default_config = Identified {
      id: CAPABILITY_CONFIG_ID.to_string(),
      partition: Some("flunge".to_string()),
      fields: CapabilityConfigFields::default(),
    };
    DB.config.upsert_document(default_config.clone()).await?;
    Ok(default_config)
  }
}

#[cfg(test)]
mod tests {
  use super::*;

  fn parse_patch(json: &str) -> Patch {
    serde_json::from_str(json).unwrap()
  }

  #[test]
  fn validate_user_patch_paths_rejects_capabilities_changes() {
    let patch = parse_patch(r#"[{"op":"replace","path":"/capabilities","value":[]}]"#);
    let result = validate_user_patch_paths(&patch, false);
    assert!(result.is_err());
    assert!(
      result
        .unwrap_err()
        .to_string()
        .contains("cannot modify their own capabilities")
    );
  }

  #[test]
  fn validate_user_patch_paths_rejects_groups_changes() {
    let patch = parse_patch(r#"[{"op":"add","path":"/groups/0","value":"beta"}]"#);
    let result = validate_user_patch_paths(&patch, false);
    assert!(result.is_err());
    assert!(
      result
        .unwrap_err()
        .to_string()
        .contains("cannot modify their own groups")
    );
  }

  #[test]
  fn validate_user_patch_paths_rejects_tracked_fencer_changes_when_lockdown_enabled() {
    let patch =
      parse_patch(r#"[{"op":"add","path":"/trackedFencers/-","value":{"fencerId":"f.u.123"}}]"#);
    let result = validate_user_patch_paths(&patch, true);
    assert!(result.is_err());
    assert!(
      result
        .unwrap_err()
        .to_string()
        .contains("cannot modify trackedFencers")
    );
  }

  #[test]
  fn validate_user_patch_paths_allows_tracked_fencer_changes_when_lockdown_disabled() {
    let patch =
      parse_patch(r#"[{"op":"add","path":"/trackedFencers/-","value":{"fencerId":"f.u.123"}}]"#);
    assert!(validate_user_patch_paths(&patch, false).is_ok());
  }

  #[test]
  fn validate_user_patch_paths_allows_other_profile_changes() {
    let patch = parse_patch(r#"[{"op":"replace","path":"/primaryUser/name","value":"Jane"}]"#);
    assert!(validate_user_patch_paths(&patch, true).is_ok());
  }

  #[test]
  fn initial_backfill_status_blocks_when_tab_results_missing() {
    let status = initial_backfill_status_for_capabilities(&[], Utc::now());
    assert_eq!(status.state, ResultsBackfillState::BlockedOnCapability);
    assert_eq!(status.requested_at, None);
  }

  #[test]
  fn initial_backfill_status_queues_when_tab_results_present() {
    let requested_at = Utc::now();
    let status =
      initial_backfill_status_for_capabilities(&[UserCapability::TabResults], requested_at);
    assert_eq!(status.state, ResultsBackfillState::Queued);
    assert_eq!(status.requested_at, Some(requested_at));
  }

  #[test]
  fn enqueue_blocked_backfills_transitions_only_blocked_entries() {
    let now = Utc::now();
    let preexisting_requested_at = now - chrono::Duration::minutes(10);
    let mut tracked = vec![
      TrackedFencer {
        fencer_id: ViewTypedId::<FencerId>::usaf("123"),
        results_backfill: ResultsBackfillStatus::blocked_on_capability(),
        british_fencing_licence: None,
      },
      TrackedFencer {
        fencer_id: ViewTypedId::<FencerId>::usaf("456"),
        results_backfill: ResultsBackfillStatus::queued(preexisting_requested_at),
        british_fencing_licence: None,
      },
    ];

    enqueue_blocked_backfills(&mut tracked, now);

    assert_eq!(
      tracked[0].results_backfill.state,
      ResultsBackfillState::Queued
    );
    assert_eq!(tracked[0].results_backfill.requested_at, Some(now));
    assert_eq!(
      tracked[1].results_backfill.state,
      ResultsBackfillState::Queued
    );
    assert_eq!(
      tracked[1].results_backfill.requested_at,
      Some(preexisting_requested_at)
    );
  }

  #[test]
  fn same_fencer_id_matches_identical_view_ids() {
    let left = ViewTypedId::<FencerId>::usaf("12345");
    let right = ViewTypedId::<FencerId>::usaf("12345");
    assert!(same_fencer_id(&left, &right));
  }

  #[test]
  fn relationship_for_fencer_mut_finds_matching_entry() {
    let target = ViewTypedId::<FencerId>::usaf("999");
    let mut relationships = vec![
      FencerRelationship {
        fencer_id: ViewTypedId::<FencerId>::usaf("111"),
        following: true,
        notify: true,
        competition_history: Vec::new(),
        display: None,
      },
      FencerRelationship {
        fencer_id: target.clone(),
        following: false,
        notify: true,
        competition_history: Vec::new(),
        display: None,
      },
    ];

    let relationship = relationship_for_fencer_mut(&mut relationships, &target).unwrap();
    relationship.following = true;

    assert!(relationships[1].following);
  }
}

/// Updates the rollout configuration for a specific capability.
pub async fn set_capability_rollout(rollout: CapabilityRollout) -> Result<CapabilityConfigDoc> {
  let mut config = get_capability_config().await?;

  // Find and update existing, or add new
  let existing_idx = config
    .fields
    .capabilities
    .iter()
    .position(|c| c.capability == rollout.capability);

  match existing_idx {
    Some(idx) => config.fields.capabilities[idx] = rollout,
    None => config.fields.capabilities.push(rollout),
  }

  DB.config.upsert_document(config.clone()).await?;

  // Invalidate the capability config cache
  crate::v2::capabilities::invalidate_capability_config_cache().await;

  Ok(config)
}

