/// Sets or clears a user's family_group_id.
pub async fn set_user_family_group(
  user_id: &ViewTypedId<UserId>,
  group_id: Option<&ViewTypedId<FamilyGroupId>>,
) -> std::result::Result<(), UserError> {
  let user = DB
    .users
    .get_document(user_id.as_str())
    .await?
    .ok_or_else(|| UserError::NotFound(user_id.as_str().to_string()))?;

  let mut updated = user.clone();
  updated.fields.family_group_id = group_id.cloned();

  DB.users.patch_document(&user, &updated).await?;
  invalidate_user_cache(user_id.as_str()).await;

  Ok(())
}

// ============================================================================
// Connected Fencers functions
// ============================================================================

/// Gets all unique connected fencer USAF IDs across all users.
/// Returns a set of USAF IDs (extracted from view format `f.u.xxx`).
/// Fencers with non-USAF IDs (e.g., database IDs) are skipped.
pub async fn get_all_connected_fencer_ids() -> Result<std::collections::HashSet<u32>> {
  let users = get_all_users().await?;
  let mut fencer_ids = std::collections::HashSet::new();

  for user in users {
    for tracked in user.fields.tracked_fencers {
      if let Some(usaf_id) = tracked.fencer_id.usaf_id() {
        fencer_ids.insert(usaf_id);
      }
    }
  }

  Ok(fencer_ids)
}

/// Gets all distinct `(USAF id, British Fencing licence)` pairs asserted by
/// any household's tracked-fencer records, across every user. A licence is a
/// household's own private assertion (`TrackedFencer::british_fencing_licence`),
/// never a global fact -- see
/// docs/design-docs/british-fencing-rankings-as-a-standings-source.md,
/// "Where the membership id lives". Two households can assert *different*
/// licences for the same fencer; this enumeration keeps both pairs so the
/// standings-history capture task can detect that disagreement and refuse to
/// capture British standings for that fencer rather than guessing. Unlike
/// [`get_all_connected_fencer_ids`], which discards the licence, this keeps
/// it -- the two exist side by side because most callers of the former have
/// no use for a licence at all.
pub async fn get_all_connected_fencer_licences() -> Result<Vec<(u32, String)>> {
  let users = get_all_users().await?;
  let mut pairs = std::collections::HashSet::new();

  for user in users {
    for tracked in user.fields.tracked_fencers {
      if let (Some(usaf_id), Some(licence)) =
        (tracked.fencer_id.usaf_id(), tracked.british_fencing_licence)
      {
        pairs.insert((usaf_id, licence));
      }
    }
  }

  Ok(pairs.into_iter().collect())
}

/// Same walk as [`get_all_connected_fencer_ids`] and
/// [`get_all_connected_fencer_licences`] combined into a single
/// `get_all_users` scan, for callers (like standings-history capture) that
/// need both the id set and the licence pairs from the same run and would
/// otherwise pay for the full users-container scan twice.
pub async fn get_all_connected_fencer_ids_and_licences()
-> Result<(std::collections::HashSet<u32>, Vec<(u32, String)>)> {
  let users = get_all_users().await?;
  let mut fencer_ids = std::collections::HashSet::new();
  let mut pairs = std::collections::HashSet::new();

  for user in users {
    for tracked in user.fields.tracked_fencers {
      if let Some(usaf_id) = tracked.fencer_id.usaf_id() {
        fencer_ids.insert(usaf_id);
        if let Some(licence) = &tracked.british_fencing_licence {
          pairs.insert((usaf_id, licence.clone()));
        }
      }
    }
  }

  Ok((fencer_ids, pairs.into_iter().collect()))
}

/// Gets one user's own connected fencer USAF IDs (their household's tracked
/// fencers only). Unlike [`get_all_connected_fencer_ids`], which unions
/// every user in the database and exists solely for admin/background jobs
/// that intentionally operate over the whole population, this is the
/// household-scoped lookup for user-facing (authenticated) request handlers.
pub fn get_connected_fencer_ids_for_user(user: &User) -> std::collections::HashSet<u32> {
  user
    .fields
    .tracked_fencers
    .iter()
    .filter_map(|tracked| tracked.fencer_id.usaf_id())
    .collect()
}

