/// Updates the rollout configuration for a specific capability.
pub async fn set_capability_rollout(rollout: CapabilityRollout) -> Result<CapabilityConfigDoc> {
  let mut config = get_capability_config().await?;

  // Find and update existing, or add new
  let existing_idx = config
    .fields
    .capabilities
    .iter()
    .position(|c| c.capability == rollout.capability);

  match existing_idx {
    Some(idx) => config.fields.capabilities[idx] = rollout,
    None => config.fields.capabilities.push(rollout),
  }

  DB.config.upsert_document(config.clone()).await?;

  // Invalidate the capability config cache
  crate::v2::capabilities::invalidate_capability_config_cache().await;

  Ok(config)
}

// ============================================================================
// User Groups functions
// ============================================================================

/// Sets the groups for a user.
pub async fn set_user_groups(id: &str, groups: Vec<String>) -> Result<User> {
  let original = get_user(id).await?;
  if let Some(mut user) = original {
    let original_user = user.clone();
    user.fields.groups = groups;
    let result = DB.users.patch_document_safe(&original_user, &user).await?;
    invalidate_user_cache(id).await;
    return Ok(result);
  }
  Err(anyhow!("Can't find user"))
}

/// Gets a summary of all groups and user counts.
pub async fn get_groups_summary() -> Result<Vec<GroupSummary>> {
  let users = get_all_users().await?;
  let mut group_counts: std::collections::HashMap<String, usize> = std::collections::HashMap::new();

  for user in users {
    for group in user.fields.groups {
      *group_counts.entry(group).or_insert(0) += 1;
    }
  }

  let mut summaries: Vec<GroupSummary> = group_counts
    .into_iter()
    .map(|(name, user_count)| GroupSummary { name, user_count })
    .collect();

  summaries.sort_by(|a, b| a.name.cmp(&b.name));
  Ok(summaries)
}

/// Summary of a group including user count.
#[derive(serde::Serialize)]
#[serde(rename_all = "camelCase")]
pub struct GroupSummary {
  pub name: String,
  pub user_count: usize,
}

// ============================================================================
// Family Group functions
// ============================================================================

/// Sets or clears a user's family_group_id.
pub async fn set_user_family_group(
  user_id: &ViewTypedId<UserId>,
  group_id: Option<&ViewTypedId<FamilyGroupId>>,
) -> std::result::Result<(), UserError> {
  let user = DB
    .users
    .get_document(user_id.as_str())
    .await?
    .ok_or_else(|| UserError::NotFound(user_id.as_str().to_string()))?;

  let mut updated = user.clone();
  updated.fields.family_group_id = group_id.cloned();

  DB.users.patch_document(&user, &updated).await?;
  invalidate_user_cache(user_id.as_str()).await;

  Ok(())
}

// ============================================================================
// Connected Fencers functions
// ============================================================================

/// Gets all unique connected fencer USAF IDs across all users.
/// Returns a set of USAF IDs (extracted from view format `f.u.xxx`).
/// Fencers with non-USAF IDs (e.g., database IDs) are skipped.
pub async fn get_all_connected_fencer_ids() -> Result<std::collections::HashSet<u32>> {
  let users = get_all_users().await?;
  let mut fencer_ids = std::collections::HashSet::new();

  for user in users {
    for tracked in user.fields.tracked_fencers {
      if let Some(usaf_id) = tracked.fencer_id.usaf_id() {
        fencer_ids.insert(usaf_id);
      }
    }
  }

  Ok(fencer_ids)
}

/// Connected fencer USAF ids plus each fencer's shared British Fencing
/// licence, when one is set. One licence per fencer: the value is a
/// property of the fencer, not a per-account assertion, so this cannot
/// return two licences for the same id.
pub async fn get_all_connected_fencer_ids_and_licences()
-> Result<(std::collections::HashSet<u32>, Vec<(u32, String)>)> {
  let fencer_ids = get_all_connected_fencer_ids().await?;
  let licences = crate::fencer_licence::repository::list_all(&DB.fencer_british_licences).await?;
  let mut pairs = Vec::new();
  for doc in licences {
    let Some(usaf_id) = doc.fields.fencer_id.usaf_id() else {
      continue;
    };
    if !fencer_ids.contains(&usaf_id) {
      continue;
    }
    let Some(membership_id) = doc.fields.membership_id else {
      continue;
    };
    pairs.push((usaf_id, membership_id));
  }
  Ok((fencer_ids, pairs))
}

/// Gets one user's own connected fencer USAF IDs (the fencers this account
/// tracks). Unlike [`get_all_connected_fencer_ids`], which unions every user
/// in the database and exists solely for admin/background jobs that
/// intentionally operate over the whole population, this is the
/// account-scoped lookup for user-facing (authenticated) request handlers.
pub fn get_connected_fencer_ids_for_user(user: &User) -> std::collections::HashSet<u32> {
  user
    .fields
    .tracked_fencers
    .iter()
    .filter_map(|tracked| tracked.fencer_id.usaf_id())
    .collect()
}

