use crate::auth::AuthenticatedUser;
use crate::db::DB;
use crate::recommendations::projected_impact_data::BlobProjectedImpactData;
use crate::usafencing::api as usafencing_api;
use crate::usafencing::standings::breakdown::regional_event_type;
use crate::usafencing::standings::{DETAIL_RECONCILE_TOLERANCE, NationalFencerBreakdown};
use crate::v2::model::TrackedFencer;
use crate::view::ids::parse_typed_id;

use super::source_event_matcher::candidate_source_event_id;
use super::{
  NATIONAL_STANDINGS_VIEW_CACHE_KEY, NationalCompositionEntry, REGIONAL_STANDINGS_VIEW_CACHE_KEY,
  SOURCE_STALE_AFTER, StandingsError, UnifiedStandingMetadata, british_rankings_enabled,
  national_cache_field, read_cached_standings, read_national_composition, regional_cache_field,
  unified_list_season, unified_new_marker_enabled, unified_standing_metadata,
};

type Result<T> = std::result::Result<T, StandingsError>;

#[path = "fencer_history.rs"]
pub(crate) mod history;

/// Negative reconciliation evidence captured by an explicit composition
/// request. The list endpoint only reads this cache: a miss is deliberately
/// treated as unknown and never triggers an upstream composition fetch.
const COMPOSITION_VERDICT_CACHE_KEY: &str = "view:standings:composition-verdict:v1";

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct FencerStandingsResponse {
  /// `pub(crate)` alongside `standings` (see below) so the recommendations
  /// module's shared per-fencer fetch (`crate::recommendations::standings::
  /// fetch_fencer_standings`) can log this id from call sites that only hold
  /// the response, not the fencer id that produced it.
  pub(crate) fencer_id: TypedId<FencerId>,
  /// `false` when this fencer's id could not be resolved to a USA Fencing
  /// identity (a non-USAF-system id with no linked USAF membership number).
  /// Distinguishes "no current standings" from "standings could not be
  /// looked up": `standings` may still contain British items when this is
  /// `false`, because those are matched by British Fencing licence rather
  /// than USA Fencing identity. An empty `standings` with
  /// `identity_resolved: true` is a confirmed lack of any current standing.
  pub(crate) identity_resolved: bool,
  /// `pub(crate)` so the recommendations Standings contributor module
  /// (`crate::recommendations::standings`) can reuse this endpoint's own
  /// fetch + enrichment logic instead of re-deriving it against
  /// `standings_index` directly.
  pub(crate) standings: Vec<FencerStandingItem>,
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub(crate) struct FencerStandingItem {
  pub(crate) key: TypedId<StandingId>,
  pub(crate) scope: StandingScope,
  pub(crate) region_id: Option<u8>,
  pub(crate) classifier: ClassifierInfo,
  pub(crate) rank: Rank,
  #[serde(skip_serializing_if = "Option::is_none")]
  pub(crate) points: Option<f32>,
  #[serde(skip_serializing_if = "Option::is_none")]
  pub(crate) entrants: Option<usize>,
  /// The capture task's cached comparison with the prior week. Its absence is
  /// meaningful: no history is not the same as a flat standing.
  #[serde(skip_serializing_if = "Option::is_none")]
  pub(crate) movement: Option<MovementSummary>,
  /// Unified source provenance. This is absent for legacy National and
  /// Regional rows, whose caches do not carry an atomic snapshot's freshness
  /// metadata. Its optional timestamps remain explicit `null` fields when a
  /// Unified source lacks them, matching the Unified list response.
  #[serde(flatten, skip_serializing_if = "Option::is_none")]
  pub(crate) unified: Option<UnifiedStandingItemMetadata>,
  /// British Fencing source provenance -- the same [`SourceFreshness`] block
  /// Unified populates, and nothing else: British has no `listCode`/
  /// `isNew`/`pointsFloor`/`eligibility` analogue. `Some` only for a British
  /// item; `None` for every other scope.
  #[serde(flatten, skip_serializing_if = "Option::is_none")]
  pub(crate) british: Option<SourceFreshness>,
}

/// Snapshot provenance shared by every snapshot-backed standings source.
/// Both Unified and British populate the identical
/// `sourceUpdatedAt`/`fetchedAt`/`isStale` trio against the same
/// [`super::SOURCE_STALE_AFTER`] threshold. Flattened at both sites, so each
/// source's wire keys stay top-level; the Unified wire shape is byte-for-byte
/// unchanged -- see
/// `unified_response_projects_private_rows_and_preserves_source_metadata`
/// and `source_freshness_flatten_matches_prior_unified_wire_shape` below.
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub(crate) struct SourceFreshness {
  pub(crate) source_updated_at: Option<i64>,
  pub(crate) fetched_at: Option<i64>,
  pub(crate) is_stale: Option<bool>,
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub(crate) struct UnifiedStandingItemMetadata {
  #[serde(flatten)]
  pub(crate) freshness: SourceFreshness,
  /// USA Fencing's own list code (e.g. `SNRWS`), mirroring the Unified list
  /// envelope's `source.listCode`. This is the code clients must render on a
  /// Unified chip: `classifier.code` diverges from it for Senior individual
  /// events, since `EventCategory::Senior::code()` returns the team-shaped
  /// `"STM"` regardless of whether the standing is individual or team.
  pub(crate) list_code: Option<String>,
  /// The server-owned launch marker. `false` remains explicit when the
  /// runtime flag is off; it never removes the Unified standing itself.
  pub(crate) is_new: bool,
  /// Mirrors the Unified list endpoint's per-row `pointsFloor`: `Some` when
  /// this fencer's `points` is a minimum tied to their weapon rating rather
  /// than earned from `counted` results.
  #[serde(skip_serializing_if = "Option::is_none")]
  pub(crate) points_floor: Option<unified_snapshot::PointsFloor>,
  /// Mirrors the Unified list endpoint's per-row `eligibility`: whether this
  /// fencer's current `points` meets the national-event registration minimum
  /// for this standing's category. `None` when there is no resolved standing
  /// to evaluate (no cached points) or no national-event minimum configured
  /// for this list's season/category.
  #[serde(skip_serializing_if = "Option::is_none")]
  pub(crate) eligibility:
    Option<points_tables::national_event_eligibility::NationalEventEligibility>,
  /// The source-declared counted set retained for recommendation context only.
  /// It is deliberately not part of the standings response wire shape; the
  /// composition endpoint owns that public representation.
  #[serde(skip)]
  pub(crate) counted: Vec<UnifiedResult>,
}

/// The composition route's header followed by the availability-specific body.
///
/// Keeping the body flattened makes `availability` the top-level discriminator
/// while ensuring an unavailable response cannot accidentally contain a
/// partial contribution list.
#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct StandingCompositionResponse {
  fencer_id: TypedId<FencerId>,
  standing_key: TypedId<StandingId>,
  scope: StandingScope,
  region_id: Option<u8>,
  classifier: ClassifierInfo,
  points: Option<f32>,
  #[serde(flatten)]
  body: StandingCompositionBody,
}

#[derive(Debug, Serialize)]
#[serde(
  tag = "availability",
  rename_all = "camelCase",
  rename_all_fields = "camelCase"
)]
pub enum StandingCompositionBody {
  Complete {
    source: CompositionSource,
    as_of: i64,
    /// Present only for Unified's on-demand per-fencer source. This says when
    /// Flunge retrieved the complete result set, not when USA Fencing updated
    /// the ranking list.
    #[serde(skip_serializing_if = "Option::is_none")]
    retrieved_at: Option<i64>,
    rule: CountingRule,
    counted_total: f32,
    counted: Vec<CompositionEntry>,
    excluded: Vec<CompositionEntry>,
    /// British Fencing publishes the number of counted results in each
    /// bucket, but not which equal-scoring result won a bucket boundary tie.
    /// Absent for every source that publishes an unambiguous selection.
    #[serde(skip_serializing_if = "Option::is_none")]
    counted_selection_ambiguous: Option<bool>,
    /// Whether `excluded` is the source's complete excluded set. See
    /// [`ExcludedAvailability`]; an empty `excluded` alone never distinguishes
    /// "the source published no exclusions" from "we could not retrieve them".
    excluded_availability: ExcludedAvailability,
  },
  Unavailable {
    reason: UnavailableReason,
  },
}

/// Whether a `Complete` composition's `excluded` list is the source's whole
/// excluded set.
///
/// Every source but Unified derives its exclusions from the same result set it
/// counts, so its excluded list is always complete. Unified is the exception:
/// its counted set travels with the published list snapshot, while its excluded
/// set lives only behind a separate per-fencer upstream handle that USA Fencing
/// re-mints on every ranking recompute. When that handle can no longer be
/// resolved, the counted breakdown is still exact and worth showing — but the
/// empty `excluded` array must not be read as a claim that the fencer had no
/// non-counting results.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub enum ExcludedAvailability {
  Complete,
  Unavailable,
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub enum CompositionSource {
  NationalDetailPdf,
  NationalPointsPage,
  RegionalPointsPage,
  UnifiedRankings,
  BritishFencingLiveRanking,
}

/// The counting model applied to select a standing's counted set, tagged by
/// `code` so the client can key UI copy off it without string-matching
/// `label`.
#[derive(Debug, Serialize)]
#[serde(
  tag = "code",
  rename_all = "camelCase",
  rename_all_fields = "camelCase"
)]
pub enum CountingRule {
  GroupSplit {
    label: String,
    // `rename_all`'s camelCase transform capitalizes only the first letter of
    // each underscore-separated word (`group_ii_best` -> `groupIiBest`), not
    // `groupIIBest` — explicit renames pin the acronym casing, matching
    // `NationalCompositionEntry`'s own `groupIBest`/`groupIIBest` precedent.
    #[serde(rename = "groupIBest")]
    group_i_best: usize,
    #[serde(rename = "groupIIBest")]
    group_ii_best: usize,
  },
  YouthBestFour {
    label: String,
  },
  BestN {
    label: String,
    best: usize,
  },
  DomesticInternationalSplit {
    label: String,
    domestic_counted: usize,
    international_counted: usize,
  },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub enum CompositionEntryGroup {
  GroupI,
  GroupII,
}

/// British Fencing's own per-event classification. This is deliberately
/// separate from USA Fencing's Group I/II aggregation terminology.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub enum CompositionEntryBucket {
  Domestic,
  International,
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct CompositionEntry {
  pub(crate) event_name: String,
  /// Raw USA Fencing event code, when the composition source supplies it.
  #[serde(skip_serializing_if = "Option::is_none")]
  pub(crate) event_code: Option<String>,
  /// The matching Flunge event, when the contribution can be attributed
  /// unambiguously. Clients can use this to navigate to the event's results.
  #[serde(skip_serializing_if = "Option::is_none")]
  pub(crate) source_event_id: Option<String>,
  #[serde(skip_serializing_if = "Option::is_none")]
  pub(crate) event_type: Option<EventType>,
  #[serde(skip_serializing_if = "Option::is_none")]
  pub(crate) category: Option<RankingCategory>,
  pub(crate) group: Option<CompositionEntryGroup>,
  /// British Fencing's published domestic/international classification.
  /// Omitted for every USA Fencing source.
  #[serde(skip_serializing_if = "Option::is_none")]
  pub(crate) bucket: Option<CompositionEntryBucket>,
  #[serde(skip_serializing_if = "Option::is_none")]
  pub(crate) date: Option<String>,
  #[serde(skip_serializing_if = "Option::is_none")]
  pub(crate) placing: Option<u32>,
  pub(crate) points: f32,
  #[serde(skip_serializing_if = "Option::is_none")]
  pub(crate) excluded_reason: Option<ExcludedReason>,
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub enum ExcludedReason {
  DisplacedByBestN,
  CappedOutSyc,
  CappedOutNationalPerAge,
  OutsideGroupWindow,
  RolledOffBySlotReoccurrence,
  PriorSeason,
  /// USA Fencing marks this result as not counted but does not publish why.
  SourceDidNotCount,
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub enum UnavailableReason {
  ListNotSupported,
  /// The fencer's member id was absent from the composition source (an
  /// enrichment miss).
  NotInSourceList,
  /// A cache read, upstream fetch, regional entry-id lookup, or the published
  /// points value required for reconciliation was unavailable.
  UpstreamUnavailable,
  /// Flunge could not map every source result into the shared composition
  /// vocabulary. This is a local coverage gap, not an upstream outage.
  ResultMappingUnavailable,
  DidNotReconcile,
}

/// Mints a Flunge-owned typed standing id.
///
/// The opaque id preserves the scope and classifier: `nat-{code}` for national
/// standings, `r{regionId}-{code}` for genuine per-region standings,
/// `rs-{code}` for `RegionalShared` (Division) categories, `uni-{code}`
/// for Unified standings, and `gb-{code}` for British Fencing standings. As a
/// derived, Flunge-owned record it uses the database system, yielding view
/// ids such as `s.d.nat-SRMF` and `s.d.r3-JRME`.
pub(crate) fn build_standing_key(
  scope: StandingScope,
  region_id: Option<u8>,
  code: &str,
) -> TypedId<StandingId> {
  let opaque_id = match (scope, region_id) {
    (StandingScope::National, _) => format!("nat-{code}"),
    (StandingScope::Regional, Some(region_id)) => format!("r{region_id}-{code}"),
    (StandingScope::Regional, None) => format!("rs-{code}"),
    (StandingScope::Unified, _) => format!("uni-{code}"),
    (StandingScope::British, _) => format!("gb-{code}"),
  };
  TypedId::<StandingId>::new_with_system(&opaque_id, System::Database)
}

/// Parses and validates a server-minted standing key.
///
/// A syntactically valid `StandingId` alone is not sufficient: this endpoint
/// only accepts the database-owned `nat-`, `r{region}-`, `rs-`, `uni-`, and
/// `gb-` forms that [`build_standing_key`] creates.
pub(crate) fn parse_standing_key(raw: &str) -> Result<TypedId<StandingId>> {
  let key = parse_typed_id::<StandingId>(raw, "standing")
    .map_err(|_| StandingsError::InvalidStandingKey(raw.to_string()))?;
  if key.system() != &System::Database {
    return Err(StandingsError::InvalidStandingKey(raw.to_string()));
  }

  let valid = match key.as_str().split_once('-') {
    Some(("nat", classifier))
    | Some(("rs", classifier))
    | Some(("uni", classifier))
    | Some(("gb", classifier)) => RecognizedClassifier::from_code(classifier).is_some(),
    Some((region, classifier)) => {
      region
        .strip_prefix('r')
        .and_then(|region| region.parse::<u8>().ok())
        .is_some_and(|region| region > 0)
        && RecognizedClassifier::from_code(classifier).is_some()
    }
    None => false,
  };
  if valid {
    Ok(key)
  } else {
    Err(StandingsError::InvalidStandingKey(raw.to_string()))
  }
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub(crate) struct ClassifierInfo {
  pub(crate) weapon: Weapon,
  pub(crate) gender: EventGender,
  pub(crate) category: EventCategory,
  pub(crate) code: String,
  pub(crate) label: String,
}

pub(super) fn category_priority(category: EventCategory) -> u8 {
  match category {
    EventCategory::Y8 => 0,
    EventCategory::Y10 => 1,
    EventCategory::Y12 => 2,
    EventCategory::Y14 => 3,
    EventCategory::Cadet => 4,
    EventCategory::Junior => 5,
    EventCategory::Senior => 6,
    EventCategory::Adult => 7,
    EventCategory::Division1 => 8,
    EventCategory::Division1A => 9,
    EventCategory::Division2 => 10,
    EventCategory::Division3 => 11,
    EventCategory::Veteran => 12,
    EventCategory::Veteran40 => 13,
    EventCategory::Veteran50 => 14,
    EventCategory::Veteran60 => 15,
    EventCategory::Veteran70 => 16,
    EventCategory::Veteran80 => 17,
    EventCategory::Para => 18,
    EventCategory::Unknown => 19,
  }
}

pub(crate) fn build_classifier_info(classifier: RecognizedClassifier) -> ClassifierInfo {
  ClassifierInfo {
    weapon: classifier.weapon,
    gender: classifier.gender,
    category: classifier.category,
    code: classifier.code(),
    label: classifier.label(),
  }
}

async fn resolve_standings_usaf_id(fencer_id: &TypedId<FencerId>) -> Result<Option<u32>> {
  if let System::Usaf = fencer_id.system() {
    return Ok(fencer_id.usaf_id());
  }
  if let System::Database = fencer_id.system() {
    match DB.fencers.get_document(fencer_id.as_str()).await {
      Ok(Some(doc)) => {
        return Ok(
          doc
            .fields
            .id_detail
            .usaf_id
            .as_deref()
            .and_then(|id| id.parse().ok()),
        );
      }
      Ok(None) => return Ok(None),
      Err(err) => {
        warn!(
          fencer_id = %fencer_id,
          ?err,
          "DB lookup failed while resolving USAF id for standings"
        );
        return Err(StandingsError::Database(err.to_string()));
      }
    }
  }
  Ok(None)
}

/// Region used to look up the view cache for division categories with a combined
/// regional ranking list (RegionalShared). The index builder fetches from region 1.
const REGIONAL_SHARED_LOOKUP_REGION: u8 = 1;

#[derive(Debug, Default)]
struct StandingEnrichment {
  points: Option<f32>,
  entrants: Option<usize>,
  unified_metadata: Option<UnifiedStandingMetadata>,
  /// `Some` only for a resolved Unified row whose points are a points floor
  /// rather than earned from results. Mirrors the Unified list endpoint's
  /// per-row `pointsFloor`.
  points_floor: Option<unified_snapshot::PointsFloor>,
  /// The Unified list's own season, used to look up the national-event
  /// eligibility minimum that applied when this snapshot was published.
  /// `None` for non-Unified rows.
  unified_season: Option<Season>,
  /// Source-declared counted results for a resolved Unified row. `Some(vec![])`
  /// is meaningful for a floored row, while `None` means no snapshot row was
  /// available to project into recommendation context.
  unified_counted: Option<Vec<UnifiedResult>>,
  /// Membership in the season-scoped regional view. `Some(false)` is only
  /// produced when the view was read successfully and did not list this
  /// fencer. `None` covers non-regional rows, unresolved regions, cache
  /// misses, and read errors; none of those establishes absence, so serving
  /// falls back to the index.
  regional_member_present: Option<bool>,
}

fn cached_standings_enrichment(
  scope: StandingScope,
  list: &[crate::usafencing::model::FencerStanding],
  usaf_id: u32,
) -> StandingEnrichment {
  let standing = list.iter().find(|standing| standing.id == Some(usaf_id));
  StandingEnrichment {
    points: standing.map(|standing| standing.points),
    entrants: Some(list.len()),
    unified_metadata: None,
    points_floor: None,
    unified_season: None,
    unified_counted: None,
    regional_member_present: (scope == StandingScope::Regional).then_some(standing.is_some()),
  }
}

fn unified_enrichment(
  list: &unified_snapshot::UnifiedListPayload,
  usaf_id: u32,
  now: chrono::DateTime<Utc>,
) -> StandingEnrichment {
  // Membership id is the only identity shared with the connected-fencer
  // endpoint. USA Fencing's source_user_id is intentionally not used here:
  // it is a source-private structural join key, not a member number.
  let record = list
    .standings
    .iter()
    .find(|record| record.standing.id == Some(usaf_id));

  StandingEnrichment {
    points: record.map(|record| record.standing.points),
    entrants: Some(list.standings.len()),
    unified_metadata: Some(unified_standing_metadata(list, now)),
    points_floor: record.and_then(|record| record.points_floor.clone()),
    unified_season: unified_list_season(list),
    unified_counted: record.map(|record| record.counted.clone()),
    regional_member_present: None,
  }
}

async fn enrich_unified_ranking(
  classifier: RecognizedClassifier,
  usaf_id: u32,
) -> StandingEnrichment {
  match unified_snapshot::read_list(classifier).await {
    Ok(Some(list)) => unified_enrichment(&list, usaf_id, Utc::now()),
    Ok(None) => StandingEnrichment::default(),
    Err(err) => {
      warn!(
        classifier = %classifier,
        ?err,
        "Failed to read Unified standings snapshot for enrichment"
      );
      StandingEnrichment::default()
    }
  }
}

async fn enrich_ranking(ranking: &CategoryRanking, usaf_id: u32) -> StandingEnrichment {
  let (hash_key, field) = match ranking.scope {
    StandingScope::Unified => return enrich_unified_ranking(ranking.classifier, usaf_id).await,
    StandingScope::National => (
      NATIONAL_STANDINGS_VIEW_CACHE_KEY,
      national_cache_field(ranking.classifier),
    ),
    StandingScope::Regional if ranking.regional_shared => (
      REGIONAL_STANDINGS_VIEW_CACHE_KEY,
      regional_cache_field(REGIONAL_SHARED_LOOKUP_REGION as u32, ranking.classifier),
    ),
    StandingScope::Regional => match ranking.usa_region {
      Some(region_id) => (
        REGIONAL_STANDINGS_VIEW_CACHE_KEY,
        regional_cache_field(region_id as u32, ranking.classifier),
      ),
      None => return StandingEnrichment::default(),
    },
    // `CategoryRanking` never carries `British`: British items are assembled
    // separately from the British Fencing licence index, not from
    // `standings_index::lookup_standings` (see the design doc's rejection of
    // putting British rows in `standings:index`). Kept exhaustive and
    // defensive rather than reachable.
    StandingScope::British => return StandingEnrichment::default(),
  };

  match read_cached_standings(hash_key, &field).await {
    Ok(Some(list)) => cached_standings_enrichment(ranking.scope, &list, usaf_id),
    // A missing field has not established that this fencer is absent. This is
    // expected after a view-cache version or field-format change, until the
    // rebuild sweep writes the current-season list.
    Ok(None) => StandingEnrichment::default(),
    Err(err) => {
      warn!(
        cache_key = hash_key,
        cache_field = %field,
        ?err,
        "Failed to read cached standings for enrichment"
      );
      StandingEnrichment::default()
    }
  }
}

/// Collapses stale old-format per-region Division entries into a single combined
/// regional row, matching what a freshly-built index would produce.
///
/// Old-format entries (pre-PR #682) for regional-shared categories have
/// `regional_shared = false` and `usa_region = Some(1..6)`. The new builder
/// stores a single `regional_shared = true, usa_region = None` entry instead.
/// This function normalizes both formats to the new shape at read time so the
/// endpoint is correct regardless of index freshness.
///
/// Genuine per-region categories (Junior/Cadet/Youth) are left untouched.
fn collapse_regional_shared_entries(rankings: Vec<CategoryRanking>) -> Vec<CategoryRanking> {
  use std::collections::HashMap;

  let mut result: Vec<CategoryRanking> = Vec::new();
  // Collect old-format per-region entries keyed by classifier
  let mut stale_by_classifier: HashMap<RecognizedClassifier, Vec<CategoryRanking>> = HashMap::new();

  for ranking in rankings {
    if ranking.scope != StandingScope::Regional
      || !is_regional_shared_category(ranking.classifier.category)
    {
      result.push(ranking);
      continue;
    }
    // New-format: already correctly stored — pass through directly.
    if ranking.regional_shared {
      result.push(ranking);
      continue;
    }
    // Old-format: accumulate per-region entries; will collapse below.
    stale_by_classifier
      .entry(ranking.classifier)
      .or_default()
      .push(ranking);
  }

  // For each classifier with old-format entries, emit exactly one row.
  // Prefer the region-1 entry (matches what the builder fetches) for rank data.
  for (classifier, entries) in stale_by_classifier {
    let representative = entries
      .iter()
      .find(|e| e.usa_region == Some(REGIONAL_SHARED_LOOKUP_REGION))
      .or_else(|| entries.first());

    if let Some(entry) = representative {
      result.push(CategoryRanking {
        scope: StandingScope::Regional,
        usa_region: None,
        regional_shared: true,
        classifier,
        rank: entry.rank.clone(),
      });
    }
  }

  result
}

/// Derives a fencer's home region from their standings. Junior/Cadet/Youth
/// regional lists are fetched **per region**, so a fencer only ever appears
/// on the one region's list matching their division — `region_id` on that
/// entry is therefore the fencer's home region, not just the list it came
/// from. `regional_shared` categories (Division) carry no `region_id` (a
/// single combined list across all regions) and never match. `None` when the
/// fencer holds no genuine per-region standing to derive one from.
pub(crate) fn fencer_home_region(standings: &FencerStandingsResponse) -> Option<u8> {
  standings.standings.iter().find_map(|item| item.region_id)
}

/// Builds one served row, using the season-scoped regional view as the
/// membership authority for lists that reset wholesale. The shared legacy
/// index can still contain a row written by an older binary, but a missing
/// member in the current season's empty/new list must not become a standing.
/// Rolling RJCC rows remain index-authoritative across the season boundary.
fn fencer_standing_item(
  ranking: &CategoryRanking,
  enrichment: StandingEnrichment,
  unified_is_new: Option<bool>,
) -> Option<FencerStandingItem> {
  if ranking.scope == StandingScope::Regional
    && regional_list_is_season_reset(ranking.classifier.category)
    && enrichment.regional_member_present == Some(false)
  {
    return None;
  }

  let scope = ranking.scope;
  let classifier = build_classifier_info(ranking.classifier);
  let key = build_standing_key(scope, ranking.usa_region, &classifier.code);
  Some(FencerStandingItem {
    key,
    scope,
    region_id: ranking.usa_region,
    classifier,
    rank: ranking.rank.clone(),
    points: enrichment.points,
    entrants: enrichment.entrants,
    movement: None,
    unified: if scope == StandingScope::Unified {
      Some(UnifiedStandingItemMetadata {
        freshness: SourceFreshness {
          source_updated_at: enrichment
            .unified_metadata
            .as_ref()
            .and_then(|metadata| metadata.source_updated_at),
          fetched_at: enrichment
            .unified_metadata
            .as_ref()
            .map(|metadata| metadata.fetched_at),
          is_stale: enrichment
            .unified_metadata
            .as_ref()
            .map(|metadata| metadata.is_stale),
        },
        list_code: enrichment
          .unified_metadata
          .as_ref()
          .map(|metadata| metadata.source_list_code.clone()),
        is_new: unified_is_new.expect("Unified rows require the Unified runtime flag"),
        points_floor: enrichment.points_floor.clone(),
        eligibility: enrichment.points.zip(enrichment.unified_season).and_then(
          |(points, season)| {
            let category = points_tables::national_event_eligibility::NationalEventCategory::for_classifier_category(
              ranking.classifier.category,
            )?;
            points_tables::national_event_eligibility::evaluate(category, points, season)
          },
        ),
        counted: enrichment.unified_counted.unwrap_or_default(),
      })
    } else {
      None
    },
    // `fencer_standing_item` only ever builds rows from `standings_index`
    // rankings, which never carry `British` -- see `enrich_ranking`'s
    // matching defensive arm. British items are built separately by
    // `british_standing_item_for_row`.
    british: None,
  })
}

/// Resolves the caller's British Fencing licence for `fencer_id` from their
/// own tracked-fencer record, if any. Shared by the owner-scoped handler
/// below and the anonymous results-share view (`crate::share::view`), which
/// each resolve a different tracked-fencer list -- the signed-in caller's
/// own, versus the share link owner's -- but need the identical lookup.
/// `None` covers both "fencer not tracked by this caller" and "tracked with
/// no licence configured"; every caller degrades to no British items in
/// either case rather than erroring.
pub(crate) fn licence_for_fencer(
  tracked: &[TrackedFencer],
  fencer_id: &TypedId<FencerId>,
) -> Option<String> {
  tracked
    .iter()
    .find(|tracked| &tracked.fencer_id == fencer_id)
    .and_then(|tracked| tracked.british_fencing_licence.clone())
}

/// Assembles a fencer's current standings across every scope. `british_licence`
/// -- the caller's own tracked-fencer record's British Fencing licence, when
/// resolvable -- is the internal assembly entry point's British extension:
/// `None` (the public route's default, and every in-process caller that has
/// no owner-scoped context, e.g. `crate::recommendations::standings`) omits
/// British items entirely, regardless of the runtime flag. `Some(licence)`
/// additionally assembles that licence's British items, still gated on
/// [`british_rankings_enabled`]. See
/// docs/design-docs/british-fencing-rankings-as-a-standings-source.md,
/// "Extending the response contract".
pub async fn get_fencer_standings(
  fencer_id: TypedId<FencerId>,
  british_licence: Option<&str>,
) -> Result<FencerStandingsResponse> {
  let usaf_id = resolve_standings_usaf_id(&fencer_id).await?;

  let raw_rankings = if let Some(usaf_id) = usaf_id {
    standings_index::lookup_standings(usaf_id)
      .await
      .map_err(|e| StandingsError::StandingsIndex(e.to_string()))?
  } else {
    Vec::new()
  };
  let rankings = collapse_regional_shared_entries(raw_rankings);
  let unified_is_new = if rankings
    .iter()
    .any(|ranking| ranking.scope == StandingScope::Unified)
  {
    Some(unified_new_marker_enabled().await?)
  } else {
    None
  };

  let mut items: Vec<FencerStandingItem> = Vec::with_capacity(rankings.len());
  for ranking in &rankings {
    let enrichment = if let Some(uid) = usaf_id {
      enrich_ranking(ranking, uid).await
    } else {
      StandingEnrichment::default()
    };
    if let Some(item) = fencer_standing_item(ranking, enrichment, unified_is_new) {
      items.push(item);
    }
  }

  if let Some(licence) = british_licence {
    items.extend(british_standing_items(licence).await);
  }

  sort_standings(&mut items);

  Ok(fencer_standings_response(fencer_id, usaf_id, items))
}

/// Shapes the response after USA Fencing and British items have been
/// assembled. `identity_resolved` deliberately reports USA Fencing identity
/// resolution only; British licence-matched items remain usable without one.
fn fencer_standings_response(
  fencer_id: TypedId<FencerId>,
  usaf_id: Option<u32>,
  standings: Vec<FencerStandingItem>,
) -> FencerStandingsResponse {
  FencerStandingsResponse {
    fencer_id,
    identity_resolved: usaf_id.is_some(),
    standings,
  }
}

/// Assembles this licence's British Fencing standing items, one per
/// configured table it appears on, gated on [`british_rankings_enabled`].
/// Ingestion runs regardless of the flag; this is the only place a British
/// item is ever kept from the response. A read failure (a bad Redis
/// connection, a corrupted payload) degrades to no British items rather than
/// failing the whole standings response, matching every other secondary
/// enrichment source in this file (see [`enrich_ranking`]'s own
/// cache-miss-is-not-an-error handling).
async fn british_standing_items(licence: &str) -> Vec<FencerStandingItem> {
  match british_rankings_enabled().await {
    Ok(true) => {}
    Ok(false) => return Vec::new(),
    Err(error) => {
      warn!(
        licence,
        ?error,
        "Failed to read British rankings runtime flag; omitting British standings"
      );
      return Vec::new();
    }
  }

  let mut conn = british_redis_connection().await;
  let entries = match british_fencing::store::read_licence_index_entries(&mut conn, licence).await {
    Ok(entries) => entries,
    Err(error) => {
      warn!(
        licence,
        ?error,
        "Failed to read British rankings licence index"
      );
      return Vec::new();
    }
  };

  let mut items = Vec::with_capacity(entries.len());
  for entry in &entries {
    match british_standing_item(&mut conn, entry).await {
      Ok(Some(item)) => items.push(item),
      // Not-yet-ranked: the entry's own table has since dropped this row (or
      // the table was never published). No item for that table, no error,
      // no placeholder -- see the design doc's "Not-yet-ranked".
      Ok(None) => {}
      Err(error) => {
        warn!(
          licence,
          table_id = %entry.table_id,
          ?error,
          "Failed to read a British rankings table"
        );
      }
    }
  }
  items
}

async fn british_redis_connection() -> redis::aio::MultiplexedConnection {
  RedisCache::get()
    .await
    .get_connection()
    .expect("RedisCache should provide a Redis connection")
}

/// Resolves one licence-index entry into a standing item, tolerating the
/// entry's `row_index` having drifted out from under it: `row_index` is
/// re-derived on every refresh (see
/// [`british_fencing::store::LicenceIndexEntry`]'s doc), so a reader that
/// trusted it blindly could return a different fencer's row if a refresh
/// landed between the licence-index read and this one. Falls back to a scan
/// when the pointer no longer lines up.
async fn british_standing_item(
  conn: &mut redis::aio::MultiplexedConnection,
  entry: &british_fencing::store::LicenceIndexEntry,
) -> anyhow::Result<Option<FencerStandingItem>> {
  let Some(table) = british_fencing::store::read_table(conn, &entry.table_id).await? else {
    return Ok(None);
  };

  Ok(
    select_british_row(&table, entry.row_index, &entry.licence)
      .map(|row| british_standing_item_for_row(&table, row)),
  )
}

/// Pure lookup: the entry's `row_index` fast path, falling back to a scan by
/// licence on a miss or a mismatch. Split out from [`british_standing_item`]
/// so it is unit-testable without a live Redis connection.
fn select_british_row<'a>(
  table: &'a british_fencing::BritishRankingTable,
  row_index: usize,
  licence: &str,
) -> Option<&'a british_fencing::BritishRankingRow> {
  table
    .rows
    .get(row_index)
    .filter(|row| row.licence == licence)
    .or_else(|| table.rows.iter().find(|row| row.licence == licence))
}

/// Builds a British standing item from one table's row. Pure, so this is
/// unit-testable without a live Redis connection. British has no analogue of
/// `regionId` (British Fencing publishes no regional dimension -- `None`,
/// the same `scope: "regional"`-with-`null`-region shape Division lists
/// already forced clients to handle) or the Unified-only `listCode`/`isNew`/
/// `pointsFloor`/`eligibility` fields.
fn british_standing_item_for_row(
  table: &british_fencing::BritishRankingTable,
  row: &british_fencing::BritishRankingRow,
) -> FencerStandingItem {
  let classifier = build_classifier_info(table.classifier);
  let key = build_standing_key(StandingScope::British, None, &classifier.code);
  let now = Utc::now();
  FencerStandingItem {
    key,
    scope: StandingScope::British,
    region_id: None,
    classifier,
    rank: row.rank.clone(),
    points: Some(row.total_points as f32),
    entrants: Some(table.rows.len()),
    movement: None,
    unified: None,
    british: Some(SourceFreshness {
      source_updated_at: Some(table.source_updated_at.timestamp()),
      fetched_at: Some(table.fetched_at.timestamp()),
      is_stale: Some(now - table.fetched_at > SOURCE_STALE_AFTER),
    }),
  }
}

/// Builds a British Fencing composition from the same validated table payload
/// that produced the standing chip. The source publishes per-bucket counts,
/// and the parser reconstructs a deterministic selected set at ingestion;
/// this read path only projects that stored source evidence and verifies it
/// still supports the card total.
async fn resolve_british_composition(
  licence: Option<&str>,
  classifier: &ClassifierInfo,
  displayed_points: Option<f32>,
) -> StandingCompositionBody {
  let Some(licence) = licence else {
    return unavailable(UnavailableReason::NotInSourceList);
  };
  let Some(points) = displayed_points else {
    return unavailable(UnavailableReason::UpstreamUnavailable);
  };

  let mut conn = british_redis_connection().await;
  let entries = match british_fencing::store::read_licence_index_entries(&mut conn, licence).await {
    Ok(entries) => entries,
    Err(error) => {
      warn!(
        licence,
        ?error,
        "Failed to read British rankings licence index for composition"
      );
      return unavailable(UnavailableReason::UpstreamUnavailable);
    }
  };

  for entry in entries {
    let table = match british_fencing::store::read_table(&mut conn, &entry.table_id).await {
      Ok(Some(table)) => table,
      Ok(None) => continue,
      Err(error) => {
        warn!(
          licence,
          table_id = %entry.table_id,
          ?error,
          "Failed to read British rankings table for composition"
        );
        return unavailable(UnavailableReason::UpstreamUnavailable);
      }
    };
    if table.classifier.code() != classifier.code {
      continue;
    }
    let Some(row) = select_british_row(&table, entry.row_index, licence) else {
      continue;
    };
    return resolve_british_composition_body(&table, row, points);
  }

  unavailable(UnavailableReason::NotInSourceList)
}

/// Projects a parser-validated British row into the shared composition shape.
/// Returning `upstreamUnavailable` for an impossible persisted index protects
/// the endpoint from silently omitting a source result if a manually-corrupt
/// Redis payload ever bypasses the ingestion validator.
fn resolve_british_composition_body(
  table: &british_fencing::BritishRankingTable,
  row: &british_fencing::BritishRankingRow,
  displayed_points: f32,
) -> StandingCompositionBody {
  let domestic_indexes = &row.counted_selection.domestic_event_indexes;
  let international_indexes = &row.counted_selection.international_event_indexes;
  if domestic_indexes.len() != row.domestic.counted_events
    || international_indexes.len() != row.international.counted_events
  {
    return unavailable(UnavailableReason::UpstreamUnavailable);
  }
  for &index in domestic_indexes {
    if !matches!(
      table.events.get(index).map(|event| event.kind),
      Some(british_fencing::BritishEventKind::Domestic)
    ) {
      return unavailable(UnavailableReason::UpstreamUnavailable);
    }
  }
  for &index in international_indexes {
    if !matches!(
      table.events.get(index).map(|event| event.kind),
      Some(british_fencing::BritishEventKind::International)
    ) {
      return unavailable(UnavailableReason::UpstreamUnavailable);
    }
  }

  let selected_indexes = domestic_indexes
    .iter()
    .chain(international_indexes)
    .copied()
    .collect::<std::collections::HashSet<_>>();
  let expected_count = row.domestic.counted_events + row.international.counted_events;
  if selected_indexes.len() != expected_count {
    return unavailable(UnavailableReason::UpstreamUnavailable);
  }

  let mut counted = Vec::with_capacity(expected_count);
  let mut excluded = Vec::with_capacity(row.results.len().saturating_sub(expected_count));
  for result in &row.results {
    let Some(mut entry) = british_composition_entry(table, result) else {
      return unavailable(UnavailableReason::UpstreamUnavailable);
    };
    if selected_indexes.contains(&result.event_index) {
      counted.push(entry);
    } else {
      entry.excluded_reason = Some(ExcludedReason::DisplacedByBestN);
      excluded.push(entry);
    }
  }
  if counted.len() != expected_count {
    return unavailable(UnavailableReason::UpstreamUnavailable);
  }

  let domestic_counted_total = counted
    .iter()
    .filter(|entry| entry.bucket == Some(CompositionEntryBucket::Domestic))
    .map(|entry| entry.points)
    .sum::<f32>();
  let international_counted_total = counted
    .iter()
    .filter(|entry| entry.bucket == Some(CompositionEntryBucket::International))
    .map(|entry| entry.points)
    .sum::<f32>();
  if (domestic_counted_total - row.domestic.points as f32).abs() > DETAIL_RECONCILE_TOLERANCE
    || (international_counted_total - row.international.points as f32).abs()
      > DETAIL_RECONCILE_TOLERANCE
  {
    warn!(
      domestic_counted_total,
      international_counted_total,
      published_domestic = row.domestic.points,
      published_international = row.international.points,
      licence = row.licence,
      table_id = table.table_id,
      "British composition per-bucket subtotals did not reconcile with the published bucket totals"
    );
    return unavailable(UnavailableReason::DidNotReconcile);
  }

  let counted_total = counted.iter().map(|entry| entry.points).sum::<f32>();
  if (counted_total - displayed_points).abs() > DETAIL_RECONCILE_TOLERANCE {
    warn!(
      counted_total,
      published_total = displayed_points,
      licence = row.licence,
      table_id = table.table_id,
      "British composition did not reconcile with the displayed standing"
    );
    return unavailable(UnavailableReason::DidNotReconcile);
  }

  StandingCompositionBody::Complete {
    source: CompositionSource::BritishFencingLiveRanking,
    as_of: table.source_updated_at.timestamp(),
    retrieved_at: None,
    rule: CountingRule::DomesticInternationalSplit {
      label: format!(
        "British Fencing counted {} domestic and {} international results",
        row.domestic.counted_events, row.international.counted_events
      ),
      domestic_counted: row.domestic.counted_events,
      international_counted: row.international.counted_events,
    },
    counted_total,
    counted,
    excluded,
    counted_selection_ambiguous: Some(row.counted_selection.is_ambiguous),
    excluded_availability: ExcludedAvailability::Complete,
  }
}

fn british_composition_entry(
  table: &british_fencing::BritishRankingTable,
  result: &british_fencing::BritishRankingResult,
) -> Option<CompositionEntry> {
  let event = table.events.get(result.event_index)?;
  Some(CompositionEntry {
    event_name: event.name.clone(),
    event_code: None,
    source_event_id: None,
    event_type: None,
    category: None,
    group: None,
    bucket: Some(match event.kind {
      british_fencing::BritishEventKind::Domestic => CompositionEntryBucket::Domestic,
      british_fencing::BritishEventKind::International => CompositionEntryBucket::International,
    }),
    date: Some(event.date.to_string()),
    placing: (result.placing != 0).then_some(result.placing),
    points: result.points as f32,
    excluded_reason: None,
  })
}

/// A failed reconciliation is different from a composition being unavailable
/// for another reason: it explicitly says the displayed total cannot be
/// supported by the source evidence. Do not surface a confident rank and
/// points for that row. Unsupported breakdowns, transient fetch failures, and
/// identity misses do not make the cached standing itself untrustworthy.
///
/// **Must be paired with [`total_is_rating_derived`].** After the points-floor
/// exemption, [`UnavailableReason::DidNotReconcile`] covers two cases: a
/// genuine earned-total/evidence mismatch, and the structural refusal of a
/// floored row (whose total is rating-derived, so no counted set can explain
/// it). This function alone cannot tell them apart — every consumer that would
/// treat a failed reconciliation as negative evidence about the standing must
/// also consult `total_is_rating_derived` (as `retain_substantiated` and
/// `should_record_did_not_reconcile` already do). A later call site that reads
/// only this verdict will silently suppress healthy floored standings.
fn composition_substantiates_summary(composition: &StandingCompositionBody) -> bool {
  !matches!(
    composition,
    StandingCompositionBody::Unavailable {
      reason: UnavailableReason::DidNotReconcile
    }
  )
}

/// Whether this row's published total comes from a weapon-rating points floor
/// rather than from results.
///
/// Keys on the presence of `points_floor` on the Unified enrichment — the same
/// floored-ness signal catalog validation uses (`is_floored_row`), independent
/// of whether the nested `weapon_rating` classification parsed. Such a total
/// is rating-derived by construction, so no counted set can ever sum to it and
/// its composition always refuses with [`UnavailableReason::DidNotReconcile`]
/// — see `docs/backend/standings.md` on the snapshot-side reconcile gate, whose
/// only serving-time effect is to refuse exactly these rows. That refusal is
/// the expected outcome for a floored row, not evidence that its total is
/// wrong, so it must never be read as negative evidence about the standing
/// itself. Pair with [`composition_substantiates_summary`] at every consumer.
fn total_is_rating_derived(standing: &FencerStandingItem) -> bool {
  standing
    .unified
    .as_ref()
    .is_some_and(|unified| unified.points_floor.is_some())
}

/// Retains summaries unless the composition evidence explicitly says their
/// published total did not reconcile. `None` represents no cached evidence,
/// which must remain visible rather than causing the list endpoint to warm an
/// on-demand source.
///
/// A points-floor row is exempt: its non-reconciliation is structural (see
/// [`total_is_rating_derived`]), so honouring that verdict would delete a
/// perfectly good standing from the list the first time anyone opened its
/// breakdown. Exempting it here — rather than only at write time — also heals
/// verdicts already persisted by earlier builds, without a cache bump.
fn retain_substantiated(
  items: Vec<(FencerStandingItem, Option<StandingCompositionBody>)>,
) -> Vec<FencerStandingItem> {
  items
    .into_iter()
    .filter_map(|(item, composition)| {
      (total_is_rating_derived(&item)
        || composition
          .as_ref()
          .is_none_or(composition_substantiates_summary))
      .then_some(item)
    })
    .collect()
}

/// Whether a composition outcome is worth persisting as negative evidence
/// against this standing's published total.
///
/// A points-floor row always refuses to reconcile, so recording that verdict
/// would say nothing about the standing and only suppress it. `false` is
/// written rather than the write being skipped, so a row that became floored
/// after an earlier earned-total verdict overwrites it instead of inheriting
/// it.
fn should_record_did_not_reconcile(
  standing: &FencerStandingItem,
  composition: &StandingCompositionBody,
) -> bool {
  !composition_substantiates_summary(composition) && !total_is_rating_derived(standing)
}

fn composition_verdict_cache_field(
  fencer_id: &TypedId<FencerId>,
  standing: &FencerStandingItem,
) -> String {
  // The displayed total is part of the identity: a refreshed published value
  // is unknown until its own composition request has been reconciled.
  format!(
    "{}:{}:{:08x}",
    fencer_id,
    standing.key,
    standing.points.unwrap_or_default().to_bits()
  )
}

async fn cached_composition_verdict(
  fencer_id: &TypedId<FencerId>,
  standing: &FencerStandingItem,
) -> Option<StandingCompositionBody> {
  let cache = RedisCache::get().await;
  let mut connection = cache
    .get_connection()
    .expect("RedisCache should provide a Redis connection");
  let field = composition_verdict_cache_field(fencer_id, standing);
  match connection
    .hget::<_, _, Option<bool>>(COMPOSITION_VERDICT_CACHE_KEY, field)
    .await
  {
    Ok(Some(true)) => Some(unavailable(UnavailableReason::DidNotReconcile)),
    Ok(Some(false) | None) => None,
    Err(error) => {
      warn!(
        fencer_id = %fencer_id,
        standing_key = %standing.key,
        %error,
        "Failed to read cached standings composition verdict"
      );
      None
    }
  }
}

async fn persist_composition_verdict(
  fencer_id: &TypedId<FencerId>,
  standing: &FencerStandingItem,
  composition: &StandingCompositionBody,
) {
  let cache = RedisCache::get().await;
  let mut connection = cache
    .get_connection()
    .expect("RedisCache should provide a Redis connection");
  let field = composition_verdict_cache_field(fencer_id, standing);
  let did_not_reconcile = should_record_did_not_reconcile(standing, composition);
  if let Err(error) = connection
    .hset::<_, _, _, ()>(COMPOSITION_VERDICT_CACHE_KEY, field, did_not_reconcile)
    .await
  {
    warn!(
      fencer_id = %fencer_id,
      standing_key = %standing.key,
      %error,
      "Failed to persist standings composition verdict"
    );
  }
}

/// Owner and anonymous share standings views both go through this so
/// movement attachment cannot drift from composition-verdict filtering.
/// Recommendations still call [`get_fencer_standings`] directly and never
/// see `movement`.
pub(crate) async fn standings_view_payload(
  response: FencerStandingsResponse,
) -> FencerStandingsResponse {
  standings_for_view(history::attach_movement(response).await).await
}

/// `pub(crate)` so the anonymous results-share standings view
/// (`crate::share::view`) can apply the same composition-verdict filtering
/// the owner endpoint applies, rather than serving unsubstantiated summaries
/// through the share surface alone.
pub(crate) async fn standings_for_view(
  response: FencerStandingsResponse,
) -> FencerStandingsResponse {
  let fencer_id = response.fencer_id.clone();
  let identity_resolved = response.identity_resolved;
  let mut evidence = Vec::with_capacity(response.standings.len());
  for item in response.standings {
    let composition = cached_composition_verdict(&fencer_id, &item).await;
    evidence.push((item, composition));
  }

  FencerStandingsResponse {
    fencer_id,
    identity_resolved,
    standings: retain_substantiated(evidence),
  }
}

/// Scope ordering: Unified, then National, then Regional, then British.
/// `sort_standings` sorts scope-major -- every row of a higher-priority
/// scope precedes every row of a lower one, regardless of category;
/// `standings_sort_scope_first_then_orders_categories_within_scope` pins the
/// actual behaviour. A single ranking function keeps this rule stable
/// regardless of which scopes a given fencer actually has, rather than
/// depending on a hardcoded per-call-site array order.
fn scope_priority(scope: StandingScope) -> u8 {
  match scope {
    StandingScope::Unified => 0,
    StandingScope::National => 1,
    StandingScope::Regional => 2,
    StandingScope::British => 3,
  }
}

fn sort_standings(items: &mut [FencerStandingItem]) {
  items.sort_by_key(|item| {
    (
      scope_priority(item.scope),
      category_priority(item.classifier.category),
    )
  });
}

/// `authed` is populated by `optional_auth_middleware` when the caller
/// carries a valid Clerk bearer token, and stays `None` for a signed-out
/// caller -- this route remains fully public either way. A signed-in caller
/// additionally gets their own British Fencing licence for this fencer, when
/// they track it, resolved from their own tracked-fencer record only: a
/// caller signed in as someone else's fencer's tracker sees nothing extra,
/// since `licence_for_fencer` only ever matches records in `authed`'s own
/// `tracked_fencers`.
#[axum::debug_handler]
pub async fn get_fencer_standings_handler(
  Path(raw_fencer_id): Path<String>,
  authed: Option<Extension<AuthenticatedUser>>,
) -> Result<Json<FencerStandingsResponse>> {
  let typed_id = parse_typed_id::<FencerId>(&raw_fencer_id, "fencer")?;
  let british_licence = authed.and_then(|Extension(authed)| {
    licence_for_fencer(&authed.user.fields.tracked_fencers, &typed_id)
  });
  let standings = get_fencer_standings(typed_id, british_licence.as_deref()).await?;
  Ok(Json(standings_view_payload(standings).await))
}

#[axum::debug_handler]
pub async fn get_standing_composition_handler(
  Path((raw_fencer_id, raw_standing_key)): Path<(String, String)>,
  authed: Option<Extension<AuthenticatedUser>>,
) -> Result<Json<StandingCompositionResponse>> {
  let fencer_id = parse_typed_id::<FencerId>(&raw_fencer_id, "fencer")?;
  let standing_key = parse_standing_key(&raw_standing_key)?;
  let british_licence = authed.and_then(|Extension(authed)| {
    licence_for_fencer(&authed.user.fields.tracked_fencers, &fencer_id)
  });
  Ok(Json(
    get_standing_composition(fencer_id, standing_key, british_licence.as_deref()).await?,
  ))
}

/// Resolves one composition using the same owner-scoped British licence as
/// standings assembly. The public fencer route has no owner context and
/// passes `None`; the anonymous share route supplies its link owner's licence
/// without ever accepting one from the caller.
pub(crate) async fn get_standing_composition(
  fencer_id: TypedId<FencerId>,
  standing_key: TypedId<StandingId>,
  british_licence: Option<&str>,
) -> Result<StandingCompositionResponse> {
  let standing = get_fencer_standings(fencer_id.clone(), british_licence)
    .await?
    .standings
    .into_iter()
    .find(|standing| standing.key == standing_key)
    .ok_or_else(|| StandingsError::StandingNotFound(standing_key.to_string()))?;

  let body = resolve_composition_body(&fencer_id, &standing, british_licence).await;
  persist_composition_verdict(&fencer_id, &standing, &body).await;

  Ok(StandingCompositionResponse {
    fencer_id,
    standing_key,
    scope: standing.scope,
    region_id: standing.region_id,
    classifier: standing.classifier,
    points: standing.points,
    body,
  })
}

/// The source family selected for a standings card. Keeping the routing pure
/// makes the supported-list contract exhaustive and regression-testable before
/// any live fetch or cache access begins.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum CompositionRoute {
  NationalCjs,
  YouthNational,
  Regional,
  UnifiedRankings,
  British,
  Unsupported,
}

/// Selects the correct source family for a standing. Youth and regional lists
/// must not be widened into the national-detail route: their source data and
/// aggregation policies differ. Veteran and Division IA/II national lists
/// deliberately remain unsupported.
pub(crate) fn composition_route(scope: StandingScope, category: EventCategory) -> CompositionRoute {
  match (scope, category) {
    (
      StandingScope::National,
      EventCategory::Cadet | EventCategory::Junior | EventCategory::Senior,
    ) => CompositionRoute::NationalCjs,
    (StandingScope::National, EventCategory::Y10 | EventCategory::Y12 | EventCategory::Y14) => {
      CompositionRoute::YouthNational
    }
    (StandingScope::Regional, _) => CompositionRoute::Regional,
    (
      StandingScope::Unified,
      EventCategory::Cadet | EventCategory::Junior | EventCategory::Senior,
    ) => CompositionRoute::UnifiedRankings,
    (StandingScope::British, _) => CompositionRoute::British,
    (StandingScope::National | StandingScope::Unified, _) => CompositionRoute::Unsupported,
  }
}

/// Resolves a standing composition using the source selected for its exact
/// scope/category pair. Each resolver retains its own reconciliation and
/// availability behaviour so an upstream or source-list refusal is not
/// mistaken for an unsupported list.
pub(crate) async fn resolve_composition_body(
  fencer_id: &TypedId<FencerId>,
  standing: &FencerStandingItem,
  british_licence: Option<&str>,
) -> StandingCompositionBody {
  match composition_route(standing.scope, standing.classifier.category) {
    CompositionRoute::NationalCjs => {
      national_composition(fencer_id, &standing.classifier, standing.points).await
    }
    CompositionRoute::YouthNational => {
      resolve_youth_composition(
        fencer_id,
        &standing.classifier.code,
        standing.classifier.category,
        standing.points,
      )
      .await
    }
    CompositionRoute::Regional => {
      resolve_regional_composition(
        fencer_id,
        &standing.classifier.code,
        standing.classifier.category,
        standing.region_id,
        standing.points,
      )
      .await
    }
    CompositionRoute::UnifiedRankings => {
      resolve_unified_composition(fencer_id, &standing.classifier, standing.points).await
    }
    CompositionRoute::British => {
      resolve_british_composition(british_licence, &standing.classifier, standing.points).await
    }
    CompositionRoute::Unsupported => StandingCompositionBody::Unavailable {
      reason: UnavailableReason::ListNotSupported,
    },
  }
}

/// Unified composition keeps the source's declared counted set intact.
///
/// The counted set is served from the published snapshot, which already stores
/// every carried result USA Fencing attributed to the row and whose scores sum
/// to the published points by construction (`unified_catalog::
/// validate_catalog_list` refuses to publish a list where they do not). No
/// upstream request is required to answer "what makes up this total".
///
/// The source-published *excluded* set is the one thing the snapshot does not
/// carry: it exists only behind `/rankings/{source_ranking_id}/results`, whose
/// handle USA Fencing re-mints on every ranking recompute — many times a day,
/// against a catalog refreshed daily — so a stored handle is usually already
/// dead (HTTP 404). That fetch is therefore a best-effort enrichment: when it
/// succeeds the response carries the full counted-plus-excluded set exactly as
/// before, and when it fails the counted breakdown is still returned, with
/// [`ExcludedAvailability::Unavailable`] marking the excluded set as
/// unretrieved rather than empty.
async fn resolve_unified_composition(
  fencer_id: &TypedId<FencerId>,
  classifier: &ClassifierInfo,
  _displayed_points: Option<f32>,
) -> StandingCompositionBody {
  let Some(classifier) = RecognizedClassifier::from_code(&classifier.code) else {
    return unavailable(UnavailableReason::ListNotSupported);
  };
  let Some(usaf_id) = resolve_standings_usaf_id(fencer_id).await.ok().flatten() else {
    return unavailable(UnavailableReason::NotInSourceList);
  };
  let active = match unified_snapshot::read_active_list(classifier).await {
    Ok(Some(active)) => Some(active),
    Ok(None) => None,
    Err(error) => {
      warn!(
        fencer_id = %fencer_id,
        %classifier,
        ?error,
        "Failed to read the active Unified snapshot for standings composition"
      );
      None
    }
  };
  let Some((snapshot_id, list)) = active else {
    return unavailable(UnavailableReason::UpstreamUnavailable);
  };
  let Some(row) = list
    .standings
    .iter()
    .find(|record| record.standing.id == Some(usaf_id))
  else {
    return unavailable(UnavailableReason::NotInSourceList);
  };
  // The snapshot can change between the parent fencer-standing lookup and
  // this on-open request. Reconcile against the exact active row that
  // published these results, never a possibly older card value.
  let points = row.standing.points;
  let Some(as_of) = list
    .source_updated_at
    .map(|timestamp| timestamp.timestamp())
  else {
    warn!(
      fencer_id = %fencer_id,
      %classifier,
      "Active Unified snapshot carries no source-update pivot to date a composition with"
    );
    return unavailable(UnavailableReason::UpstreamUnavailable);
  };

  // Try the richer answer first, so the snapshot arm's mapping and tournament
  // lookup are only paid for when the enrichment could not supply them.
  if let Some(body) =
    unified_full_result_body(fencer_id, classifier, row, &list, points, as_of, || {
      unified_client::resolve_live_fencer_results(
        &snapshot_id,
        classifier,
        &row.source_ranking_uuid,
        row.source_user_id,
        &row.standing.name,
      )
    })
    .await
  {
    return body;
  }

  let mut snapshot_counted = match unified_contributions(&row.counted) {
    Ok(candidates) => candidates,
    Err(error) => {
      warn!(
        fencer_id = %fencer_id,
        %classifier,
        %error,
        "Snapshot Unified counted set contained an unmappable source result"
      );
      return unavailable(UnavailableReason::ResultMappingUnavailable);
    }
  };
  // The reconcile-or-refuse gate runs against the set we are certain of. A
  // points-floor row legitimately fails it: its points come from the fencer's
  // weapon rating, not from results, so no counted list can explain the total —
  // and the enrichment arm's own gate has already rejected it for the same
  // reason, which is how it reached this point.
  let snapshot_counted_total = counted_total(&row.counted);
  if (snapshot_counted_total - points).abs() > DETAIL_RECONCILE_TOLERANCE {
    warn!(
      fencer_id = %fencer_id,
      %classifier,
      snapshot_counted_total,
      published_total = points,
      points_floor = row.points_floor.is_some(),
      "Snapshot Unified counted set did not reconcile with the active standing"
    );
    return unavailable(UnavailableReason::DidNotReconcile);
  }
  populate_source_event_ids(&mut snapshot_counted, classifier).await;

  unified_snapshot_composition_body(&list, &snapshot_counted, snapshot_counted_total, as_of)
}

/// Assembles the Unified body from the counted set the published snapshot
/// already holds. `excluded` is deliberately empty and flagged
/// [`ExcludedAvailability::Unavailable`]: this arm never saw the source's
/// excluded results, so it must not imply there were none. `retrieved_at` is
/// likewise absent — nothing was retrieved on this request, and the snapshot's
/// own provenance is already carried by `as_of`.
fn unified_snapshot_composition_body(
  list: &unified_snapshot::UnifiedListPayload,
  counted: &[StandingContribution],
  counted_total: f32,
  as_of: i64,
) -> StandingCompositionBody {
  unified_body(
    list,
    as_of,
    None,
    counted_total,
    counted
      .iter()
      .map(|contribution| composition_entry(contribution, None))
      .collect(),
    Vec::new(),
    ExcludedAvailability::Unavailable,
  )
}

/// Attempts the per-fencer upstream fetch that carries the source-published
/// excluded set, returning `None` whenever it cannot produce a body the caller
/// should prefer over the snapshot-derived one. Every `None` is logged: an
/// unavailable live lookup is expected background noise, but a mapping or
/// reconciliation failure means the two source views disagree.
///
/// The fetch itself is injected as `fetch_results` so tests can exercise the
/// fetch-fails-then-fall-back-to-the-snapshot wiring without the real
/// upstream call's cache, Redis gate, and HTTP dependencies; production
/// always passes [`unified_client::resolve_live_fencer_results`].
async fn unified_full_result_body<F, Fut>(
  fencer_id: &TypedId<FencerId>,
  classifier: RecognizedClassifier,
  row: &unified_snapshot::UnifiedStandingRecord,
  list: &unified_snapshot::UnifiedListPayload,
  points: f32,
  as_of: i64,
  fetch_results: F,
) -> Option<StandingCompositionBody>
where
  F: FnOnce() -> Fut,
  Fut: std::future::Future<Output = unified_client::Result<unified_client::UnifiedFencerResults>>,
{
  let results = match fetch_results().await {
    Ok(results) => results,
    Err(error) => {
      match error {
        unified_client::UnifiedClientError::BudgetExhausted => debug!(
          fencer_id = %fencer_id, %classifier,
          "Unified excluded-result resolution skipped because the request-unit budget is exhausted"
        ),
        unified_client::UnifiedClientError::LiveLookupNoRows { .. } => debug!(
          fencer_id = %fencer_id, %classifier, source_user_id = row.source_user_id, ?error,
          "Unified excluded-result live lookup did not resolve this snapshot row"
        ),
        unified_client::UnifiedClientError::LiveLookupUserMismatch { .. }
        | unified_client::UnifiedClientError::LiveLookupPageLimit { .. } => warn!(
          fencer_id = %fencer_id, %classifier, source_user_id = row.source_user_id, ?error,
          "Unified excluded-result live lookup disagreed with this snapshot row"
        ),
        unified_client::UnifiedClientError::FencerResultsFetch { ranking_id, .. } => debug!(
          fencer_id = %fencer_id, %classifier, source_ranking_id = ranking_id, ?error,
          "Unified excluded-result fetch failed after live ranking resolution"
        ),
        _ => debug!(fencer_id = %fencer_id, %classifier, ?error,
          "Unified excluded-result fetch failed after live ranking resolution"),
      }
      return None;
    }
  };
  let mut candidates = match unified_contributions(&results.results) {
    Ok(candidates) => candidates,
    Err(error) => {
      warn!(
        fencer_id = %fencer_id,
        %classifier,
        %error,
        "Unified full result set contained an unmappable source result"
      );
      return None;
    }
  };
  populate_source_event_ids(&mut candidates, classifier).await;

  match resolve_unified_composition_body(
    list,
    &results.results,
    &candidates,
    points,
    as_of,
    results.retrieved_at.timestamp(),
  ) {
    body @ StandingCompositionBody::Complete { .. } => Some(body),
    StandingCompositionBody::Unavailable { reason } => {
      warn!(
        fencer_id = %fencer_id,
        %classifier,
        ?reason,
        "Unified full result set was rejected; serving the snapshot counted set alone"
      );
      None
    }
  }
}

/// Sums the ranking scores USA Fencing marked as counting.
fn counted_total(results: &[UnifiedResult]) -> f32 {
  results
    .iter()
    .filter(|result| result.counted)
    .map(|result| result.ranking_score)
    .sum()
}

fn unavailable(reason: UnavailableReason) -> StandingCompositionBody {
  StandingCompositionBody::Unavailable { reason }
}

/// Maps every required upstream event field into the shared composition shape.
/// Unknown event codes, categories, or tournament classifications reject the
/// entire response: omitting an event would falsely claim a complete result
/// set and could mask a reconciliation mismatch.
fn unified_contributions(
  results: &[UnifiedResult],
) -> std::result::Result<Vec<StandingContribution>, String> {
  results
    .iter()
    .map(|result| {
      let event_classifier = RecognizedClassifier::from_code(&result.event_code)
        .filter(|classifier| !classifier.team)
        .ok_or_else(|| format!("unrecognized individual event code {:?}", result.event_code))?;
      let category = ranking_category_for(event_classifier.category)
        .ok_or_else(|| format!("unsupported event category in {:?}", result.event_code))?;
      let event_type = classify_event(&EventClassificationInputs {
        scope: None,
        tournament_name: &result.tournament_name,
        tournament_id: &result.event_id.to_string(),
        location: "",
        usa_region: None,
        category: event_classifier.category,
        allow_international_default: true,
      })
      .event_type
      .ok_or_else(|| {
        format!(
          "unclassified Unified tournament {:?}",
          result.tournament_name
        )
      })?;
      let placement = result.placement.ok_or_else(|| {
        format!(
          "missing placement for Unified event {:?}",
          result.event_code
        )
      })?;
      let mut contribution = StandingContribution::slot(
        result.event_id.to_string(),
        format!("{}-{}", result.tournament_name, result.event_code),
        event_type,
        category,
        ResultDate::with_day(
          result.event_date.year(),
          result.event_date.month(),
          result.event_date.day(),
        ),
        placement,
        result.ranking_score,
      )
      .with_event_name(result.tournament_name.clone())
      .with_event_code(result.event_code.clone());
      // Unified publishes one undifferentiated best-N pool. The legacy
      // national Group I/II split does not apply to these source-declared
      // results, even when their event type normally belongs to Group I.
      contribution.group = ContributionGroup::None;
      Ok(contribution)
    })
    .collect()
}

/// Builds Unified's source-declared counted/excluded sets after every result
/// has passed strict mapping. Unlike legacy points sources, Unified does not
/// let Flunge recompute which entries count; only its published boolean does.
fn resolve_unified_composition_body(
  list: &unified_snapshot::UnifiedListPayload,
  results: &[UnifiedResult],
  candidates: &[StandingContribution],
  points: f32,
  as_of: i64,
  retrieved_at: i64,
) -> StandingCompositionBody {
  if results.len() != candidates.len() {
    return unavailable(UnavailableReason::UpstreamUnavailable);
  }
  let counted_total = counted_total(results);
  if (counted_total - points).abs() > DETAIL_RECONCILE_TOLERANCE {
    warn!(
      counted_total,
      published_total = points,
      "Unified composition did not reconcile with the active standing"
    );
    return unavailable(UnavailableReason::DidNotReconcile);
  }

  let mut counted = Vec::new();
  let mut excluded = Vec::new();
  for (result, contribution) in results.iter().zip(candidates) {
    let mut entry = composition_entry(contribution, None);
    if result.counted {
      counted.push(entry);
    } else {
      entry.excluded_reason = Some(ExcludedReason::SourceDidNotCount);
      excluded.push(entry);
    }
  }

  unified_body(
    list,
    as_of,
    Some(retrieved_at),
    counted_total,
    counted,
    excluded,
    ExcludedAvailability::Complete,
  )
}

/// The one place a Unified `Complete` body is shaped, so the snapshot-only and
/// full-result-set arms cannot drift in rule label, source, or field order.
fn unified_body(
  list: &unified_snapshot::UnifiedListPayload,
  as_of: i64,
  retrieved_at: Option<i64>,
  counted_total: f32,
  counted: Vec<CompositionEntry>,
  excluded: Vec<CompositionEntry>,
  excluded_availability: ExcludedAvailability,
) -> StandingCompositionBody {
  StandingCompositionBody::Complete {
    source: CompositionSource::UnifiedRankings,
    as_of,
    retrieved_at,
    rule: CountingRule::BestN {
      label: format!("Best {} results", list.max_results),
      best: list.max_results as usize,
    },
    counted_total,
    counted,
    excluded,
    counted_selection_ambiguous: None,
    excluded_availability,
  }
}

/// Youth-national (Y10/Y12/Y14) composition is fetched from the tracked
/// fencer's per-fencer points page and evaluated with Youth's own caps and
/// slot-reoccurrence window.
async fn resolve_youth_composition(
  fencer_id: &TypedId<FencerId>,
  classifier_code: &str,
  category: EventCategory,
  points: Option<f32>,
) -> StandingCompositionBody {
  let Some(points) = points else {
    return StandingCompositionBody::Unavailable {
      reason: UnavailableReason::UpstreamUnavailable,
    };
  };
  let Some(classifier) = RecognizedClassifier::from_code(classifier_code) else {
    return StandingCompositionBody::Unavailable {
      reason: UnavailableReason::ListNotSupported,
    };
  };
  let Some(usaf_id) = resolve_standings_usaf_id(fencer_id).await.ok().flatten() else {
    return StandingCompositionBody::Unavailable {
      reason: UnavailableReason::NotInSourceList,
    };
  };
  let youth_category = match category {
    EventCategory::Y10 => YouthCategory::Y10,
    EventCategory::Y12 => YouthCategory::Y12,
    EventCategory::Y14 => YouthCategory::Y14,
    _ => {
      return StandingCompositionBody::Unavailable {
        reason: UnavailableReason::ListNotSupported,
      };
    }
  };

  let mut candidates =
    match usafencing_api::get_national_fencer_breakdown(classifier, usaf_id).await {
      Ok(NationalFencerBreakdown::Contributions(candidates)) => candidates,
      // A 404 on a list USA Fencing does serve means this fencer holds no rows
      // on it — that is a fact about the fencer, so it reads as
      // `NotInSourceList` rather than the `UpstreamUnavailable` an error used
      // to produce. `ListNotBreakdownBacked` is unreachable behind the
      // youth-category match above, and maps to the same `ListNotSupported`
      // that match already returns.
      Ok(NationalFencerBreakdown::FencerNotRanked) => {
        return StandingCompositionBody::Unavailable {
          reason: UnavailableReason::NotInSourceList,
        };
      }
      Ok(NationalFencerBreakdown::ListNotBreakdownBacked) => {
        return StandingCompositionBody::Unavailable {
          reason: UnavailableReason::ListNotSupported,
        };
      }
      Err(err) => {
        warn!(
          fencer_id = %fencer_id,
          classifier = %classifier,
          ?err,
          "Failed to fetch Youth-national breakdown for composition"
        );
        return StandingCompositionBody::Unavailable {
          reason: UnavailableReason::UpstreamUnavailable,
        };
      }
    };
  populate_source_event_ids(&mut candidates, classifier).await;

  build_composition_body(
    CompositionSource::NationalPointsPage,
    CountingRule::YouthBestFour {
      label: "Best 4 results, with per-age caps".to_string(),
    },
    WindowKind::SlotReoccurrence,
    AggregationPolicy::YouthBestFour(youth_caps(youth_category)),
    &candidates,
    points,
  )
}

/// Regional composition reuses the existing regional-entry-id resolver and
/// its cached per-fencer points-page fetch. This keeps composition aligned with
/// the projected-impact path that already owns regional entry-id semantics.
async fn resolve_regional_composition(
  fencer_id: &TypedId<FencerId>,
  classifier_code: &str,
  category: EventCategory,
  region_id: Option<u8>,
  points: Option<f32>,
) -> StandingCompositionBody {
  let Some(points) = points else {
    return StandingCompositionBody::Unavailable {
      reason: UnavailableReason::UpstreamUnavailable,
    };
  };
  let Some(classifier) = RecognizedClassifier::from_code(classifier_code) else {
    return StandingCompositionBody::Unavailable {
      reason: UnavailableReason::ListNotSupported,
    };
  };
  let Some(ranking_category) = ranking_category_for(category) else {
    return StandingCompositionBody::Unavailable {
      reason: UnavailableReason::ListNotSupported,
    };
  };
  let Some(region_id) = region_id else {
    return StandingCompositionBody::Unavailable {
      reason: UnavailableReason::ListNotSupported,
    };
  };
  let Some(best) = regional_best_n(ranking_category) else {
    return StandingCompositionBody::Unavailable {
      reason: UnavailableReason::ListNotSupported,
    };
  };
  let window = regional_composition_window(category);
  let Some(usaf_id) = resolve_standings_usaf_id(fencer_id).await.ok().flatten() else {
    return StandingCompositionBody::Unavailable {
      reason: UnavailableReason::NotInSourceList,
    };
  };

  let (candidates, _standings) = fetch_regional_contributions(
    &BlobProjectedImpactData,
    region_id as u32,
    classifier,
    usaf_id,
  )
  .await;
  let Some(mut candidates) = candidates else {
    return StandingCompositionBody::Unavailable {
      reason: UnavailableReason::UpstreamUnavailable,
    };
  };
  populate_source_event_ids(&mut candidates, classifier).await;

  build_composition_body(
    CompositionSource::RegionalPointsPage,
    CountingRule::BestN {
      label: regional_counting_label(best, window),
      best,
    },
    window,
    AggregationPolicy::BestN(best),
    &candidates,
    points,
  )
}

/// The regional breakdown query is pinned to this season's configured list
/// identifiers, which is the window for lists that reset at the season boundary.
fn regional_composition_season() -> Season {
  Season::latest_configured()
}

/// Selects the regional list's window from the shared rolling/season-reset
/// model. RJCC lists retain active prior-season results until a later instance
/// of the same slot replaces them; all other categories use the historical
/// season-reset default when they have no explicit regional-list mapping.
fn regional_composition_window(category: EventCategory) -> WindowKind {
  if regional_list_rolls_off(category) {
    WindowKind::SlotReoccurrence
  } else {
    WindowKind::SeasonReset(regional_composition_season())
  }
}

fn regional_counting_label(best: usize, window: WindowKind) -> String {
  match window {
    WindowKind::SlotReoccurrence => {
      format!("Best {best} results, kept until the same event is fenced again")
    }
    WindowKind::SeasonReset(_) => format!("Best {best} results this season"),
  }
}

/// Maps each regional list family to its configured current-season Best-N
/// window. A missing mapping remains an explicit unsupported-list refusal.
fn regional_best_n(category: RankingCategory) -> Option<usize> {
  match regional_event_type(category) {
    EventType::Ryc | EventType::Roc => Some(3),
    EventType::Rjcc => Some(2),
    _ => None,
  }
}

#[derive(Clone, Copy)]
enum WindowKind {
  SlotReoccurrence,
  SeasonReset(Season),
}

impl WindowKind {
  fn counting(
    &self,
    policy: AggregationPolicy,
    candidates: &[StandingContribution],
  ) -> Vec<StandingContribution> {
    match self {
      Self::SlotReoccurrence => current_counting(policy, candidates),
      Self::SeasonReset(season) => current_counting_in_season(policy, candidates, *season),
    }
  }
}

/// Builds the reconcile-or-refuse body shared by the two live points-page
/// sources. The warning retains both totals, which is the operational signal
/// needed to investigate Youth reconciliation without weakening the gate.
fn build_composition_body(
  source: CompositionSource,
  rule: CountingRule,
  window: WindowKind,
  policy: AggregationPolicy,
  candidates: &[StandingContribution],
  points: f32,
) -> StandingCompositionBody {
  let counting = window.counting(policy, candidates);
  let drop_map = drop_reasons(policy, candidates, &counting);
  let counted_total: f32 = counting
    .iter()
    .map(|contribution| contribution.points)
    .sum();

  if (counted_total - points).abs() > DETAIL_RECONCILE_TOLERANCE {
    warn!(
      counted_total,
      published_total = points,
      "Composition candidate pool did not reconcile with the displayed points total"
    );
    return StandingCompositionBody::Unavailable {
      reason: UnavailableReason::DidNotReconcile,
    };
  }

  let counted: Vec<_> = counting
    .iter()
    .map(|contribution| composition_entry(contribution, None))
    .collect();
  let excluded = candidates
    .iter()
    .filter(|candidate| {
      !counting
        .iter()
        .any(|counted| counted.result_id == candidate.result_id)
    })
    .map(|candidate| {
      let reason = drop_map
        .get(&candidate.result_id)
        .map(excluded_reason)
        .unwrap_or(ExcludedReason::DisplacedByBestN);
      composition_entry_with_excluded_reason(candidate, Some(reason))
    })
    .collect();

  StandingCompositionBody::Complete {
    source,
    as_of: chrono::Utc::now().timestamp(),
    retrieved_at: None,
    rule,
    counted_total,
    counted,
    excluded,
    counted_selection_ambiguous: None,
    // Youth and regional exclusions are derived from the same candidate pool
    // that produced the counted set, so the excluded list is always whole.
    excluded_availability: ExcludedAvailability::Complete,
  }
}

/// Resolves composition for a national Cadet/Junior/Senior standing from the
/// per-member composition index ([`read_national_composition`]) written at
/// ingest: builds the candidate pool, selects the counting set with the
/// list's own stored `GroupSplit` window, labels exclusions, and applies the
/// reconcile-or-refuse gate against the card's `points` before ever returning
/// `Complete`.
async fn national_composition(
  fencer_id: &TypedId<FencerId>,
  classifier: &ClassifierInfo,
  points: Option<f32>,
) -> StandingCompositionBody {
  let Some(points) = points else {
    return StandingCompositionBody::Unavailable {
      reason: UnavailableReason::NotInSourceList,
    };
  };
  let Some(usaf_id) = resolve_standings_usaf_id(fencer_id).await.ok().flatten() else {
    return StandingCompositionBody::Unavailable {
      reason: UnavailableReason::NotInSourceList,
    };
  };
  let Some(recognized) = RecognizedClassifier::from_code(&classifier.code) else {
    warn!(
      code = %classifier.code,
      "Unrecognized classifier code resolving national standings composition"
    );
    return StandingCompositionBody::Unavailable {
      reason: UnavailableReason::UpstreamUnavailable,
    };
  };

  let mut entry = match read_national_composition(recognized, usaf_id).await {
    Ok(Some(entry)) => entry,
    Ok(None) => {
      return StandingCompositionBody::Unavailable {
        reason: UnavailableReason::NotInSourceList,
      };
    }
    Err(err) => {
      warn!(
        fencer_id = %fencer_id,
        code = %classifier.code,
        error = %err,
        "Failed to read national standings composition index"
      );
      return StandingCompositionBody::Unavailable {
        reason: UnavailableReason::UpstreamUnavailable,
      };
    }
  };
  populate_source_event_ids(&mut entry.contributions, recognized).await;

  resolve_national_composition_body(&entry, points).unwrap_or_else(|(counted_total, published)| {
    warn!(
      fencer_id = %fencer_id,
      code = %classifier.code,
      counted_total,
      published_total = published,
      "National standings composition did not reconcile against the published total"
    );
    StandingCompositionBody::Unavailable {
      reason: UnavailableReason::DidNotReconcile,
    }
  })
}

/// Adds links only when the source matcher finds exactly one compatible
/// Flunge event. A database-read failure preserves the composition response;
/// it simply leaves the optional event links unavailable.
async fn populate_source_event_ids(
  contributions: &mut [StandingContribution],
  classifier: RecognizedClassifier,
) {
  let tournaments = match DB.tournaments.list_documents().await {
    Ok(tournaments) => tournaments,
    Err(error) => {
      warn!(
        %classifier,
        ?error,
        "Failed to load tournaments while linking standings composition contributions"
      );
      return;
    }
  };

  for contribution in contributions
    .iter_mut()
    .filter(|contribution| contribution.source_event_id.is_empty())
  {
    contribution.source_event_id =
      candidate_source_event_id(contribution, classifier, &tournaments).unwrap_or_default();
  }
}

/// The pure counting-set-selection, exclusion-labelling and reconcile-or-refuse
/// core of [`national_composition`], factored out so it is unit-testable
/// without a live Redis connection. `Err((counted_total, points))` is the
/// reconcile-gate failure — both totals, for the caller to log — everything
/// else is a plain `Ok(Complete)`.
fn resolve_national_composition_body(
  entry: &NationalCompositionEntry,
  points: f32,
) -> std::result::Result<StandingCompositionBody, (f32, f32)> {
  let policy = AggregationPolicy::GroupSplit {
    group_i_best: entry.group_i_best,
    group_ii_best: entry.group_ii_best,
  };
  // The national detail parser reconciles this family with the Group I/II
  // aggregation alone. Do not apply slot-reoccurrence roll-off or season
  // windowing here: the parser has not validated that extra step for the
  // composition it emits, so exclusions must only ever be labelled with the
  // plain Group I/II diagnosis this selection actually applied — never a
  // roll-off or prior-season diagnosis inferred from data this policy never
  // consulted. `drop_reasons_without_window_diagnoses` enforces that.
  let counting = counting_for_policy(policy, &entry.contributions);
  let counted_total: f32 = counting.iter().map(|c| c.points).sum();

  if (counted_total - points).abs() > DETAIL_RECONCILE_TOLERANCE {
    return Err((counted_total, points));
  }

  let (counted_candidates, excluded_candidates) =
    partition_counting_candidates(&entry.contributions, &counting);
  let exclusion_reasons =
    drop_reasons_without_window_diagnoses(policy, &entry.contributions, &counting);
  let counted = counted_candidates
    .iter()
    .map(|c| composition_entry(c, None))
    .collect();
  let excluded = excluded_candidates
    .iter()
    .map(|candidate| {
      let fallback = DropReason::OutsideGroupWindow {
        group: candidate.group,
      };
      let reason = exclusion_reasons
        .get(&candidate.result_id)
        .unwrap_or(&fallback);
      composition_entry(candidate, Some(reason))
    })
    .collect();

  Ok(StandingCompositionBody::Complete {
    source: CompositionSource::NationalDetailPdf,
    as_of: entry.as_of,
    retrieved_at: None,
    rule: CountingRule::GroupSplit {
      label: format!(
        "Best {} domestic + best {} international",
        entry.group_i_best, entry.group_ii_best
      ),
      group_i_best: entry.group_i_best,
      group_ii_best: entry.group_ii_best,
    },
    counted_total,
    counted,
    excluded,
    counted_selection_ambiguous: None,
    // The national detail entry carries every candidate result, so what it
    // does not count is exactly what this excluded list holds.
    excluded_availability: ExcludedAvailability::Complete,
  })
}

fn composition_entry(
  contribution: &StandingContribution,
  reason: Option<&DropReason>,
) -> CompositionEntry {
  composition_entry_with_excluded_reason(contribution, reason.map(excluded_reason))
}

fn composition_entry_with_excluded_reason(
  contribution: &StandingContribution,
  excluded_reason: Option<ExcludedReason>,
) -> CompositionEntry {
  CompositionEntry {
    event_name: if contribution.event_name.is_empty() {
      event_name(contribution)
    } else {
      contribution.event_name.clone()
    },
    event_code: contribution.event_code.clone(),
    source_event_id: (!contribution.source_event_id.is_empty())
      .then(|| contribution.source_event_id.clone()),
    event_type: Some(contribution.event_type),
    category: Some(contribution.category),
    group: match contribution.group {
      ContributionGroup::None => None,
      ContributionGroup::GroupI => Some(CompositionEntryGroup::GroupI),
      ContributionGroup::GroupII => Some(CompositionEntryGroup::GroupII),
    },
    bucket: None,
    date: contribution.date.map(|date| match date.day {
      Some(day) => format!("{:04}-{:02}-{day:02}", date.year, date.month),
      None => format!("{:04}-{:02}", date.year, date.month),
    }),
    placing: contribution.placing,
    points: contribution.points,
    excluded_reason,
  }
}

/// A display-usable event name for a composition row, e.g. "October NAC",
/// matching the vocabulary [`event_type_noun`]/[`month_name`] already use for
/// projected-impact defensive copy.
fn event_name(contribution: &StandingContribution) -> String {
  let noun = event_type_noun(contribution.event_type);
  match contribution.date {
    Some(date) => format!("{} {noun}", month_name(date.month)),
    None => noun.to_string(),
  }
}

fn excluded_reason(reason: &DropReason) -> ExcludedReason {
  match reason {
    DropReason::CappedOut { kind, .. } => match kind {
      YouthCapKind::Syc => ExcludedReason::CappedOutSyc,
      YouthCapKind::NationalPerAge => ExcludedReason::CappedOutNationalPerAge,
    },
    DropReason::DisplacedByBestN => ExcludedReason::DisplacedByBestN,
    DropReason::OutsideGroupWindow { .. } => ExcludedReason::OutsideGroupWindow,
    DropReason::RolledOffBySlotReoccurrence => ExcludedReason::RolledOffBySlotReoccurrence,
    DropReason::PriorSeason => ExcludedReason::PriorSeason,
  }
}

