//! British Fencing standings tests, split out from `fencer_tests.rs` (see
//! its own note at the split point) purely to keep that file under the
//! file-size check's line cap -- there is no functional reason these live
//! in a separate module from the rest of `fencer.rs`'s tests.

use super::*;
use chrono::{Duration, NaiveDate};

#[test]
fn standing_key_round_trips_british() {
  let key = build_standing_key(StandingScope::British, None, "CDTWS");
  assert_eq!(key.to_string(), "s.d.gb-CDTWS");
  assert_eq!(key.as_str(), "gb-CDTWS");
  assert_eq!(parse_standing_key(&key.to_string()).unwrap(), key);
}

#[test]
fn standing_key_parser_rejects_a_british_key_with_an_unrecognized_classifier() {
  assert!(parse_standing_key("s.d.gb-NOTAREALCODE").is_err());
}

#[test]
fn standings_sort_places_british_last_after_regional() {
  let cadet = RecognizedClassifier::from_code("CDTWS").unwrap();
  let mut items = vec![
    super::tests::sortable_item(StandingScope::British, cadet),
    super::tests::sortable_item(StandingScope::Regional, cadet),
    super::tests::sortable_item(StandingScope::Unified, cadet),
    super::tests::sortable_item(StandingScope::National, cadet),
  ];

  sort_standings(&mut items);

  assert_eq!(
    items.iter().map(|item| item.scope).collect::<Vec<_>>(),
    vec![
      StandingScope::Unified,
      StandingScope::National,
      StandingScope::Regional,
      StandingScope::British,
    ]
  );
}

#[test]
fn composition_route_selects_british_payload_for_every_british_category() {
  for category in [
    EventCategory::Cadet,
    EventCategory::Junior,
    EventCategory::Senior,
    EventCategory::Y10,
    EventCategory::Y12,
    EventCategory::Y14,
  ] {
    assert_eq!(
      composition_route(StandingScope::British, category),
      CompositionRoute::British
    );
  }
}

#[test]
fn source_freshness_flatten_matches_prior_unified_wire_shape() {
  // Regression for the `SourceFreshness` extraction: `sourceUpdatedAt`/
  // `fetchedAt`/`isStale` used to be flat fields directly on
  // `UnifiedStandingItemMetadata`; they are now `#[serde(flatten)]`ed from a
  // nested `SourceFreshness`, and the wire keys must be byte-for-byte
  // unchanged. `points_floor`/`eligibility` stay `None` here deliberately, so
  // the object contains exactly the five keys this asserts -- no stray key
  // survives an accidental un-skip.
  let metadata = UnifiedStandingItemMetadata {
    freshness: SourceFreshness {
      source_updated_at: Some(1700000000),
      fetched_at: Some(1700000100),
      is_stale: Some(false),
    },
    list_code: Some("CDTWS".to_string()),
    is_new: true,
    points_floor: None,
    eligibility: None,
    counted: Vec::new(),
  };

  let value = serde_json::to_value(&metadata).unwrap();
  assert_eq!(value["sourceUpdatedAt"], 1700000000);
  assert_eq!(value["fetchedAt"], 1700000100);
  assert_eq!(value["isStale"], false);
  assert_eq!(value["listCode"], "CDTWS");
  assert_eq!(value["isNew"], true);
  assert_eq!(value.as_object().unwrap().len(), 5);
}

fn british_row(
  licence: &str,
  position: u32,
  total_points: i64,
) -> british_fencing::BritishRankingRow {
  british_fencing::BritishRankingRow {
    rank: model_common::Rank {
      position,
      is_tied: false,
    },
    name: "Fencer, Test".to_string(),
    year_of_birth: None,
    club: None,
    licence: licence.to_string(),
    total_points,
    domestic: british_fencing::BritishBucketTotal {
      points: total_points,
      counted_events: 1,
    },
    international: british_fencing::BritishBucketTotal {
      points: 0,
      counted_events: 0,
    },
    results: Vec::new(),
    counted_selection: Default::default(),
  }
}

fn british_table(
  rows: Vec<british_fencing::BritishRankingRow>,
  fetched_at: chrono::DateTime<Utc>,
) -> british_fencing::BritishRankingTable {
  british_fencing::BritishRankingTable {
    table_id: "cadet-womens-sabre".to_string(),
    classifier: RecognizedClassifier::from_code("CDTWS").unwrap(),
    source_title: "Cadet Women's Sabre".to_string(),
    source_updated_at: fetched_at - Duration::hours(2),
    fetched_at,
    events: Vec::new(),
    rows,
  }
}

fn british_event(
  name: &str,
  date: &str,
  kind: british_fencing::BritishEventKind,
) -> british_fencing::BritishRankingEvent {
  british_fencing::BritishRankingEvent {
    name: name.to_string(),
    date: NaiveDate::parse_from_str(date, "%Y-%m-%d").unwrap(),
    kind,
  }
}

fn british_result(
  event_index: usize,
  placing: u32,
  points: i64,
) -> british_fencing::BritishRankingResult {
  british_fencing::BritishRankingResult {
    event_index,
    placing,
    points,
  }
}

#[test]
fn british_composition_projects_source_buckets_and_ambiguity() {
  let mut table = british_table(vec![], Utc::now());
  table.events = vec![
    british_event(
      "London Open",
      "2026-01-10",
      british_fencing::BritishEventKind::Domestic,
    ),
    british_event(
      "Birmingham Open",
      "2026-02-10",
      british_fencing::BritishEventKind::Domestic,
    ),
    british_event(
      "European Cup",
      "2026-03-10",
      british_fencing::BritishEventKind::International,
    ),
  ];
  let mut row = british_row("142013", 12, 125);
  row.domestic = british_fencing::BritishBucketTotal {
    points: 50,
    counted_events: 1,
  };
  row.international = british_fencing::BritishBucketTotal {
    points: 75,
    counted_events: 1,
  };
  row.results = vec![
    british_result(0, 3, 50),
    british_result(1, 8, 30),
    british_result(2, 5, 75),
  ];
  row.counted_selection = british_fencing::BritishCountedSelection {
    domestic_event_indexes: vec![0],
    international_event_indexes: vec![2],
    is_ambiguous: true,
  };

  let body = resolve_british_composition_body(&table, &row, 125.0);
  let StandingCompositionBody::Complete {
    source,
    rule,
    counted_total,
    counted,
    excluded,
    counted_selection_ambiguous,
    excluded_availability,
    ..
  } = body
  else {
    panic!("expected complete British composition");
  };

  assert!(matches!(
    source,
    CompositionSource::BritishFencingLiveRanking
  ));
  assert!(matches!(
    rule,
    CountingRule::DomesticInternationalSplit {
      domestic_counted: 1,
      international_counted: 1,
      ..
    }
  ));
  assert_eq!(counted_total, 125.0);
  assert_eq!(
    counted.iter().map(|entry| entry.bucket).collect::<Vec<_>>(),
    vec![
      Some(CompositionEntryBucket::Domestic),
      Some(CompositionEntryBucket::International),
    ]
  );
  assert_eq!(excluded.len(), 1);
  assert_eq!(
    excluded[0]
      .excluded_reason
      .as_ref()
      .map(|reason| serde_json::to_value(reason).unwrap()),
    Some(serde_json::json!("displacedByBestN"))
  );
  assert_eq!(counted_selection_ambiguous, Some(true));
  assert!(matches!(
    excluded_availability,
    ExcludedAvailability::Complete
  ));
}

#[test]
