}

#[test]
fn british_composition_refuses_when_the_counted_selection_index_count_disagrees_with_published_counts()
 {
  let mut table = british_table(vec![], Utc::now());
  table.events = vec![british_event(
    "London Open",
    "2026-01-10",
    british_fencing::BritishEventKind::Domestic,
  )];
  let mut row = british_row("142013", 12, 50);
  row.results = vec![british_result(0, 3, 50)];
  // Published counted_events says 1 domestic, but the selection carries none --
  // a manually-corrupt payload the ingestion validator should never produce.
  row.counted_selection.domestic_event_indexes = vec![];

  assert!(matches!(
    resolve_british_composition_body(&table, &row, 50.0),
    StandingCompositionBody::Unavailable {
      reason: UnavailableReason::UpstreamUnavailable
    }
  ));
}

#[test]
fn british_composition_refuses_when_a_result_event_index_is_past_the_end_of_the_events_table() {
