#[test]
fn british_standing_item_for_row_reports_scope_key_and_entrant_count() {
  let table = british_table(
    vec![
      british_row("142013", 12, 37210),
      british_row("999999", 1, 50000),
    ],
    Utc::now(),
  );

  let item = british_standing_item_for_row(&table, &table.rows[0]);

  assert_eq!(item.scope, StandingScope::British);
  assert_eq!(item.key.to_string(), "s.d.gb-CDTWS");
  assert_eq!(item.region_id, None);
  assert_eq!(item.rank.position, 12);
  assert_eq!(item.points, Some(37210.0));
  // The parsed row count, not the highest rank on a tied field -- see the
  // design doc's "A chip's field size must be the parsed row count, never
  // the highest rank."
  assert_eq!(item.entrants, Some(2));
  assert!(item.unified.is_none());
}

