fn standings_sort_places_british_last_after_regional() {
  let cadet = RecognizedClassifier::from_code("CDTWS").unwrap();
  let mut items = vec![
    super::tests::sortable_item(StandingScope::British, cadet),
    super::tests::sortable_item(StandingScope::Regional, cadet),
    super::tests::sortable_item(StandingScope::Unified, cadet),
    super::tests::sortable_item(StandingScope::National, cadet),
  ];

  sort_standings(&mut items);

  assert_eq!(
    items.iter().map(|item| item.scope).collect::<Vec<_>>(),
