//! The additive standings movement and trajectory read surface.

use std::collections::HashMap;

use axum::Json;
use axum::extract::{Extension, Path, Query};
use chrono::{DateTime, Duration, Utc};
use ids::{FencerId, StandingId, TypedId};
use model_common::Rank;
use serde::{Deserialize, Serialize};
use standings_history::{
  MovementSummary, ReceiptOutcome, SnapshotRunReceiptFields, StandingSnapshotProjection, repository,
};
use tracing::warn;

use crate::auth::AuthenticatedUser;
use crate::db::DB;
use crate::standings_history::{SCHEDULE, read_movement, slot_run_id_from};
use crate::view::ids::parse_typed_id;

use super::{
  ClassifierInfo, FencerStandingsResponse, Result, StandingScope, StandingsError,
  get_fencer_standings, licence_for_fencer, parse_standing_key,
};

/// Projected history for a single standing. The contributor arrays live in
/// Cosmos for a later explain-why surface, but are intentionally never read
/// by this graph endpoint.
#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct StandingHistoryResponse {
  fencer_id: TypedId<FencerId>,
  standing_key: TypedId<StandingId>,
  scope: StandingScope,
  classifier: ClassifierInfo,
  window_days: u32,
  points: Vec<StandingHistoryPoint>,
  gaps: Vec<StandingHistoryGap>,
  #[serde(skip_serializing_if = "Option::is_none")]
  movement: Option<MovementSummary>,
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct StandingHistoryPoint {
  run_id: String,
  captured_at: DateTime<Utc>,
  rank: Rank,
  #[serde(skip_serializing_if = "Option::is_none")]
  points: Option<f32>,
  #[serde(skip_serializing_if = "Option::is_none")]
  entrants: Option<usize>,
  source_stale: bool,
  #[serde(skip_serializing_if = "Option::is_none")]
  composition_state: Option<String>,
  #[serde(skip_serializing_if = "Option::is_none")]
  composition_reason: Option<String>,
}

impl From<StandingSnapshotProjection> for StandingHistoryPoint {
  fn from(snapshot: StandingSnapshotProjection) -> Self {
    Self {
      run_id: snapshot.run_id,
      captured_at: snapshot.captured_at,
      rank: snapshot.rank,
      points: snapshot.points,
      entrants: snapshot.entrants,
      source_stale: snapshot.source.stale,
      composition_state: snapshot.composition_state,
      composition_reason: snapshot.composition_reason,
    }
  }
}

#[derive(Debug, Serialize, PartialEq, Eq)]
#[serde(rename_all = "camelCase")]
pub struct StandingHistoryGap {
  pub(crate) run_id: String,
  pub(crate) kind: StandingHistoryGapKind,
}

#[derive(Debug, Serialize, PartialEq, Eq)]
#[serde(rename_all = "camelCase")]
pub enum StandingHistoryGapKind {
  CaptureFailed,
  NotAttempted,
  StandingAbsent,
}

#[derive(Debug, Deserialize)]
pub struct StandingHistoryQuery {
  pub(crate) days: Option<u32>,
}

pub(crate) const DEFAULT_HISTORY_WINDOW_DAYS: u32 = 180;

/// Attaches the task-produced summaries with one `HGET` for the whole
/// response. A Redis miss or malformed cache value deliberately degrades to
/// no indicator instead of letting derived state make standings unavailable.
pub(crate) async fn attach_movement(response: FencerStandingsResponse) -> FencerStandingsResponse {
  match read_movement(&response.fencer_id.to_string()).await {
    Ok(movement) => apply_movement(response, movement),
    Err(error) => {
      warn!(
        fencer_id = %response.fencer_id,
        ?error,
        "Failed to read standings movement summaries; serving standings without movement"
      );
      response
    }
  }
}

/// Matches precomputed summaries onto the items they belong to. Keys with no
/// summary keep `movement: None`; extra hash entries that do not match an
/// item are dropped. Pure so owner and share can share one implementation
/// without a Redis fake.
pub(crate) fn apply_movement(
  mut response: FencerStandingsResponse,
  mut movement: HashMap<String, MovementSummary>,
) -> FencerStandingsResponse {
  for standing in &mut response.standings {
    standing.movement = movement.remove(&standing.key.to_string());
  }
  response
}

/// Returns the projected observation series used by the standing trajectory
/// graph. The current-standing lookup intentionally matches the composition
/// route: malformed keys are rejected before reads, while a valid key absent
/// from this fencer's current standings is a 404.
#[axum::debug_handler]
pub async fn get_standing_history_handler(
  Path((raw_fencer_id, raw_standing_key)): Path<(String, String)>,
  Query(query): Query<StandingHistoryQuery>,
  authed: Option<Extension<AuthenticatedUser>>,
) -> Result<Json<StandingHistoryResponse>> {
  let fencer_id = parse_typed_id::<FencerId>(&raw_fencer_id, "fencer")?;
  let standing_key = parse_standing_key(&raw_standing_key)?;
  let british_licence = authed.and_then(|Extension(authed)| {
    licence_for_fencer(&authed.user.fields.tracked_fencers, &fencer_id)
  });
  let standing = get_fencer_standings(fencer_id.clone(), british_licence.as_deref())
    .await?
    .standings
    .into_iter()
    .find(|standing| standing.key == standing_key)
    .ok_or_else(|| StandingsError::StandingNotFound(standing_key.to_string()))?;

  let window_days = history_window_days(
    query.days,
    flunge_config::CONF.standings_history.retention_days,
  );
  let now = Utc::now();
  let since = now - Duration::days(i64::from(window_days));
  let snapshots = repository::list_standing_snapshots_in_window(
    &DB.standings_history_snapshots,
    &fencer_id.to_string(),
    &standing_key.to_string(),
    since,
  )
  .await
  .map_err(|error| StandingsError::Database(error.to_string()))?;
  let receipts = repository::list_receipts_in_window(
    &DB.standings_history_receipts,
    &fencer_id.to_string(),
    since,
  )
  .await
  .map_err(|error| StandingsError::Database(error.to_string()))?
  .into_iter()
  .map(|receipt| receipt.fields)
  .collect::<Vec<_>>();
  let slots = cron_schedule::execution_times_in_window(SCHEDULE, since, now)
    .ok_or_else(|| StandingsError::Database("invalid standings history schedule".to_string()))?;

  let mut points = snapshots
    .into_iter()
    .map(StandingHistoryPoint::from)
    .collect::<Vec<_>>();
  points.sort_by_key(|point| point.captured_at);
  let movement = match read_movement(&fencer_id.to_string()).await {
    Ok(mut movement) => movement.remove(&standing_key.to_string()),
    Err(error) => {
      warn!(
        %fencer_id,
        ?error,
        "Failed to read standings movement summary for history response"
      );
      None
    }
  };

  Ok(Json(StandingHistoryResponse {
    fencer_id,
    standing_key,
    scope: standing.scope,
    classifier: standing.classifier,
    window_days,
    points,
    gaps: history_gaps(slots, &receipts, standing.key.as_str()),
    movement,
  }))
}

pub(crate) fn history_window_days(days: Option<u32>, retention_days: u32) -> u32 {
  days
    .unwrap_or(DEFAULT_HISTORY_WINDOW_DAYS)
    .clamp(1, retention_days)
}

pub(crate) fn history_gaps(
  slots: Vec<DateTime<Utc>>,
  receipts: &[SnapshotRunReceiptFields],
  standing_key: &str,
) -> Vec<StandingHistoryGap> {
  slots
    .into_iter()
    .filter_map(|slot| {
      let run_id = slot_run_id_from(slot);
      let kind = match receipts.iter().find(|receipt| receipt.run_id == run_id) {
        None => StandingHistoryGapKind::NotAttempted,
        Some(SnapshotRunReceiptFields {
          outcome: ReceiptOutcome::Failed { .. },
          ..
        }) => StandingHistoryGapKind::CaptureFailed,
        Some(SnapshotRunReceiptFields {
          outcome: ReceiptOutcome::Succeeded { standing_keys },
          ..
        }) if !standing_keys.iter().any(|key| key == standing_key) => {
          StandingHistoryGapKind::StandingAbsent
        }
        Some(_) => return None,
      };
      Some(StandingHistoryGap { run_id, kind })
    })
    .collect()
}

