//! Pure planner for lifting per-user British Fencing licence assertions
//! onto the shared fencer record.
//!
//! Where exactly one distinct membership id exists across every user
//! tracking a fencer, that value is adopted. Where two or more users
//! asserted *different* ids for the same fencer, the shared record is left
//! unset — the planner never guesses. Callers log the conflict by fencer
//! id and distinct-count only; they must never log the membership ids
//! themselves.

use std::collections::{HashMap, HashSet};

use ids::{FencerId, TypedId, UserId};

/// One user's stored assertion of a British Fencing membership id for a
/// fencer they track. `membership_id` is the already-trimmed stored value.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PerUserAssertion {
  pub user_id: TypedId<UserId>,
  pub fencer_id: TypedId<FencerId>,
  pub membership_id: String,
}

/// What to do for one fencer that had at least one per-user assertion.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum MigrationDecision {
  /// Every asserting user agreed (or only one asserted). Write this value
  /// as the shared licence, attributed to `set_by`.
  Adopt {
    fencer_id: TypedId<FencerId>,
    membership_id: String,
    set_by: TypedId<UserId>,
  },
  /// Two or more distinct membership ids were asserted. Leave the shared
  /// licence unset. `distinct_count` is the number of different ids, never
  /// the ids themselves.
  Conflict {
    fencer_id: TypedId<FencerId>,
    distinct_count: usize,
  },
}

#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct MigrationPlan {
  pub decisions: Vec<MigrationDecision>,
}

impl MigrationPlan {
  pub fn adopted_count(&self) -> usize {
    self
      .decisions
      .iter()
      .filter(|d| matches!(d, MigrationDecision::Adopt { .. }))
      .count()
  }

  pub fn conflicted_count(&self) -> usize {
    self
      .decisions
      .iter()
      .filter(|d| matches!(d, MigrationDecision::Conflict { .. }))
      .count()
  }
}

/// Groups per-user assertions by fencer and decides adopt-vs-conflict for
/// each. Fencers with no assertions are omitted. Adopted `set_by` is the
/// lexicographically-smallest asserting user id so two replicas planning
/// the same input produce the same provenance.
pub fn plan_migration(assertions: &[PerUserAssertion]) -> MigrationPlan {
  let mut by_fencer: HashMap<TypedId<FencerId>, HashMap<String, HashSet<TypedId<UserId>>>> =
    HashMap::new();
  for assertion in assertions {
    by_fencer
      .entry(assertion.fencer_id.clone())
      .or_default()
      .entry(assertion.membership_id.clone())
      .or_default()
      .insert(assertion.user_id.clone());
  }

  let mut decisions = Vec::with_capacity(by_fencer.len());
  for (fencer_id, licences) in by_fencer {
    match licences.len() {
      0 => {}
      1 => {
        let (membership_id, users) = licences.into_iter().next().unwrap();
        let mut users: Vec<_> = users.into_iter().collect();
        users.sort_by_key(|user| user.to_string());
        let set_by = users
          .into_iter()
          .next()
          .expect("at least one asserting user");
        decisions.push(MigrationDecision::Adopt {
          fencer_id,
          membership_id,
          set_by,
        });
      }
      distinct_count => {
        decisions.push(MigrationDecision::Conflict {
          fencer_id,
          distinct_count,
        });
      }
    }
  }
  MigrationPlan { decisions }
}

#[cfg(test)]
mod tests {
  use super::*;

  fn user(id: &str) -> TypedId<UserId> {
    TypedId::<UserId>::database(id)
  }

  fn fencer(id: &str) -> TypedId<FencerId> {
    TypedId::<FencerId>::usaf(id)
  }

  fn assertion(user_id: &str, fencer_id: &str, membership_id: &str) -> PerUserAssertion {
    PerUserAssertion {
      user_id: user(user_id),
      fencer_id: fencer(fencer_id),
      membership_id: membership_id.to_string(),
    }
  }

  #[test]
  fn empty_input_adopts_nothing() {
    let plan = plan_migration(&[]);
    assert_eq!(plan.adopted_count(), 0);
    assert_eq!(plan.conflicted_count(), 0);
    assert!(plan.decisions.is_empty());
  }

  #[test]
  fn single_assertion_is_adopted_with_that_user_as_provenance() {
    let plan = plan_migration(&[assertion("alice", "100", "142013")]);
    assert_eq!(
      plan.decisions,
      vec![MigrationDecision::Adopt {
        fencer_id: fencer("100"),
        membership_id: "142013".to_string(),
        set_by: user("alice"),
      }]
    );
    assert_eq!(plan.adopted_count(), 1);
    assert_eq!(plan.conflicted_count(), 0);
  }

  #[test]
  fn two_users_asserting_the_same_licence_are_adopted() {
    let plan = plan_migration(&[
      assertion("bob", "100", "142013"),
      assertion("alice", "100", "142013"),
    ]);
    assert_eq!(
      plan.decisions,
      vec![MigrationDecision::Adopt {
        fencer_id: fencer("100"),
        membership_id: "142013".to_string(),
        set_by: user("alice"),
      }]
    );
  }

  #[test]
  fn two_users_asserting_different_licences_conflict_without_naming_values() {
    let plan = plan_migration(&[
      assertion("alice", "100", "111"),
      assertion("bob", "100", "222"),
    ]);
    assert_eq!(
      plan.decisions,
      vec![MigrationDecision::Conflict {
        fencer_id: fencer("100"),
        distinct_count: 2,
      }]
    );
    let debug = format!("{:?}", plan);
    assert!(
      !debug.contains("111"),
      "conflict debug must not include licence values"
    );
    assert!(
      !debug.contains("222"),
      "conflict debug must not include licence values"
    );
  }

  #[test]
  fn independent_fencers_are_planned_separately() {
    let plan = plan_migration(&[
      assertion("alice", "100", "AAA"),
      assertion("bob", "200", "BBB"),
      assertion("carol", "200", "CCC"),
    ]);
    assert_eq!(plan.adopted_count(), 1);
    assert_eq!(plan.conflicted_count(), 1);
    assert!(plan.decisions.iter().any(
      |d| matches!(d, MigrationDecision::Adopt { fencer_id, .. } if *fencer_id == fencer("100"))
    ));
    assert!(plan.decisions.iter().any(|d| matches!(
      d,
      MigrationDecision::Conflict {
        fencer_id,
        distinct_count: 2
      } if *fencer_id == fencer("200")
    )));
  }

  #[test]
  fn three_distinct_licences_report_the_count_not_the_values() {
    let plan = plan_migration(&[
      assertion("a", "100", "one"),
      assertion("b", "100", "two"),
      assertion("c", "100", "three"),
    ]);
    assert_eq!(
      plan.decisions,
      vec![MigrationDecision::Conflict {
        fencer_id: fencer("100"),
        distinct_count: 3,
      }]
    );
  }
}

