import { CheckCircle, Error, PlayArrow, Add } from "@mui/icons-material";
import {
  Accordion,
  AccordionDetails,
  AccordionSummary,
  Button,
  Card,
  Chip,
  ChipDelete,
  CircularProgress,
  Divider,
  Dropdown,
  IconButton,
  LinearProgress,
  Menu,
  MenuButton,
  MenuItem,
  Stack,
  Typography,
} from "@mui/joy";
import { useQuery } from "react-query";
import {
  flushAdminCache,
  getAdminTasks,
  getFencingTrackerStatus,
  getUnifiedRankingsRefreshStatus,
  getStandingsHistoryStatus,
  startAdminTask,
  getAdminCacheSummary,
  getAdminCacheKey,
  getAdminCaches,
  getAdminCacheEntry,
  invalidateAdminCache,
  getAdminUsers,
  setUserCapabilities,
  setUserGroups,
  getAdminGroups,
  getCapabilityConfig,
  setCapabilityRollout,
  RedisCacheSummary,
  RedisCacheKeySummary,
  RedisCacheKeyDetail,
  RedisCacheEntry,
  CacheSummaryEntry,
  CacheEntryDetail,
  InvalidateCacheResult,
  CapabilityRollout,
  UserCapability,
  UserCapabilities,
  User,
} from "./api/v2";
import { FlexiTable } from "./components/FlexiTable";
import { ErrorStateCard } from "./components/PageStates";
import { Route, Routes, useNavigate } from "react-router-dom";
import { useEffect, useState } from "react";
import { useAuth } from "@clerk/clerk-react";

const ADMIN_MENU_ITEMS = [
  {
    path: "/admin/tasks",
    title: "Tasks",
    description: "Manage background tasks",
  },
  {
    path: "/admin/cache",
    title: "Cache",
    description: "View and manage Redis cache entries",
  },
  {
    path: "/admin/caches",
    title: "Named Caches",
    description: "Invalidate stale cache entries by cache name and key",
  },
  {
    path: "/admin/users",
    title: "Users",
    description: "Manage user capabilities and groups",
  },
  {
    path: "/admin/groups",
    title: "Groups",
    description: "View user groups and membership",
  },
  {
    path: "/admin/capabilities",
    title: "Capabilities",
    description: "Configure capability rollouts",
  },
  {
    path: "/admin/flags",
    title: "Flags",
    description: "View and update dynamic runtime flags",
  },
] as const;

export default function AdminPage() {
  return (
    <Routes>
      <Route path="/" element={<AdminMenu />} />
      <Route path="/tasks" element={<AdminTasksPage />} />
      <Route path="/cache" element={<AdminCachePage />} />
      <Route path="/caches" element={<AdminCachesPage />} />
      <Route path="/users" element={<AdminUsersPage />} />
      <Route path="/groups" element={<AdminGroupsPage />} />
      <Route path="/capabilities" element={<AdminCapabilitiesPage />} />
    </Routes>
  );
}

function AdminMenu() {
  const navigate = useNavigate();

  return (
    <Stack direction="column" spacing={2} sx={{ p: 2 }}>
      <Typography level="h2">Admin</Typography>
      <Card>
        <Stack direction="column" spacing={1}>
          {ADMIN_MENU_ITEMS.map((item) => (
            <Button
              key={item.path}
              variant="outlined"
              onClick={() => navigate(item.path)}
              sx={{ justifyContent: "flex-start" }}
            >
              <Stack direction="column" alignItems="flex-start" width="100%">
                <Typography level="title-md" textAlign="left">
                  {item.title}
                </Typography>
                <Typography level="body-sm" textAlign="left">
                  {item.description}
                </Typography>
              </Stack>
            </Button>
          ))}
        </Stack>
      </Card>
    </Stack>
  );
}

const FORCE_LIST_REFRESH_TASKS = new Set(["usaf_sync", "rebuild_standings_index"]);
const UNIFIED_CATALOG_REFRESH_TASK = "refresh_unified_catalog";
const UNIFIED_CATALOG_OVERRIDE_TASK = "refresh_unified_catalog_override";

function FencingTrackerStatusCard() {
  const clerkAuth = useAuth();
  const status = useQuery(
    "admin_fencingtracker",
    async () => {
      const token = await clerkAuth.getToken();
      return getFencingTrackerStatus(token);
    },
    {
      refetchInterval: 5000,
    },
  );

  if (status.data === undefined) {
    return null;
  }

  const s = status.data;

  return (
    <Card>
      <Typography level="title-md">FencingTracker egress</Typography>
      <Stack direction="row" spacing={1} alignItems="center">
        {s.cooldown_active ? (
          <Chip color="danger" variant="soft">
            Throttle cooldown active
          </Chip>
        ) : (
          <Chip color="success" variant="soft">
            Healthy
          </Chip>
        )}
        {s.cooldown_active && s.cooldown_until !== null && (
          <Typography level="body-sm">
            Paused until {new Date(s.cooldown_until * 1000).toLocaleString()}
          </Typography>
        )}
        {s.timeout_cooldown_active && (
          <Chip color="warning" variant="soft">
            Timeout cooldown active (background only)
          </Chip>
        )}
        {s.timeout_cooldown_active && s.timeout_cooldown_until !== null && (
          <Typography level="body-sm">
            Paused until {new Date(s.timeout_cooldown_until * 1000).toLocaleString()}
          </Typography>
        )}
      </Stack>
      <FlexiTable columns={[{}, {}]}>
        <Typography level="body-sm">Rate ceiling</Typography>
        <Typography level="body-sm">{s.max_requests_per_second} req/s</Typography>
        <Typography level="body-sm">Consecutive 403/429s</Typography>
        <Typography level="body-sm">{s.error_streak}</Typography>
        <Typography level="body-sm">Consecutive timeouts</Typography>
        <Typography level="body-sm">{s.timeout_error_streak}</Typography>
        <Typography level="body-sm">Background requests (this hour)</Typography>
        <Typography level="body-sm">
          {s.background_requests_this_hour}
          {s.background_max_requests_per_hour > 0
            ? ` / ${s.background_max_requests_per_hour}`
            : " (unlimited)"}
        </Typography>
      </FlexiTable>
    </Card>
  );
}

function UnifiedRankingsStatusCard() {
  const clerkAuth = useAuth();
  const status = useQuery(
    "admin_unified_rankings",
    async () => {
      const token = await clerkAuth.getToken();
      return getUnifiedRankingsRefreshStatus(token);
    },
    {
      refetchInterval: 5000,
    },
  );

  if (status.data === undefined) {
    return null;
  }

  const s = status.data;
  const hasFailedSinceLastSuccess =
    s.lastFailureAt !== null && (s.lastSuccessAt === null || s.lastFailureAt > s.lastSuccessAt);
  const sweep = s.identitySweep;

  return (
    <Card>
      <Typography level="title-md">Unified rankings catalog</Typography>
      <Stack direction="row" spacing={1} alignItems="center">
        {hasFailedSinceLastSuccess ? (
          <Chip color="danger" variant="soft">
            Latest refresh failed
          </Chip>
        ) : s.lastSuccessAt !== null ? (
          <Chip color="success" variant="soft">
            Last refresh succeeded
          </Chip>
        ) : (
          <Chip color="warning" variant="soft">
            No snapshot published
          </Chip>
        )}
      </Stack>
      <FlexiTable columns={[{}, {}]}>
        <Typography level="body-sm">Last attempt</Typography>
        <Typography level="body-sm">
          {s.lastAttemptAt === null ? "Never" : formatDate(s.lastAttemptAt)}
        </Typography>
        <Typography level="body-sm">Cooldown override used</Typography>
        <Typography level="body-sm">
          {s.lastAttemptUsedCooldownOverride === true ? "Yes" : "No"}
        </Typography>
        <Typography level="body-sm">Last successful snapshot</Typography>
        <Typography level="body-sm">
          {s.lastSuccessSnapshotId === null ? "None" : s.lastSuccessSnapshotId}
        </Typography>
        {s.lastFailureReason !== null ? (
          <>
            <Typography level="body-sm">Latest failure</Typography>
            <Typography level="body-sm">{s.lastFailureReason}</Typography>
          </>
        ) : (
          <></>
        )}
        {/* Publishing does not wait for identity resolution, so "last refresh
            succeeded" above does not mean the catalog is fully resolved. This
            row is what keeps that from reading as an all-clear. */}
        <Typography level="body-sm">Identity resolution</Typography>
        <Typography level="body-sm">
          {sweep.catalogRows === 0
            ? "Not yet swept"
            : `${sweep.resolvedRows} of ${sweep.catalogRows} rows` +
              ` (${Math.round((100 * sweep.resolvedRows) / sweep.catalogRows)}%)` +
              `, ${sweep.pendingRows} pending`}
        </Typography>
        <Typography level="body-sm">Last identity sweep</Typography>
        <Typography level="body-sm">
          {sweep.lastRunAt === null
            ? "Never"
            : `${formatDate(sweep.lastRunAt)} — ${sweep.lastRunResolved} resolved` +
              ` of ${sweep.lastRunLookups} lookups (${sweep.lastRunStopReason ?? "unknown"})`}
        </Typography>
      </FlexiTable>
    </Card>
  );
}

function StandingsHistoryStatusCard() {
  const clerkAuth = useAuth();
  const status = useQuery(
    "admin_standings_history",
    async () => {
      const token = await clerkAuth.getToken();
      return getStandingsHistoryStatus(token);
    },
    {
      refetchInterval: 5000,
    },
  );

  if (status.data === undefined) {
    return null;
  }

  const s = status.data;
  const hasFailedSinceLastSuccess =
    s.lastFailureAt !== null && (s.lastSuccessAt === null || s.lastFailureAt > s.lastSuccessAt);
  const counts = s.lastRunCounts;

  return (
    <Card>
      <Typography level="title-md">Standings history capture</Typography>
      <Stack direction="row" spacing={1} alignItems="center">
        {hasFailedSinceLastSuccess ? (
          <Chip color="danger" variant="soft">
            Latest capture incomplete
          </Chip>
        ) : s.lastSuccessAt !== null ? (
          <Chip color="success" variant="soft">
            Last capture succeeded
          </Chip>
        ) : (
          <Chip color="warning" variant="soft">
            No capture yet
          </Chip>
        )}
      </Stack>
      <FlexiTable columns={[{}, {}]}>
        <Typography level="body-sm">Last attempt</Typography>
        <Typography level="body-sm">
          {s.lastAttemptAt === null
            ? "Never"
            : `${formatDate(s.lastAttemptAt)}${s.lastAttemptRunId ? ` (${s.lastAttemptRunId})` : ""}`}
        </Typography>
        <Typography level="body-sm">Last run counts</Typography>
        <Typography level="body-sm">
          {counts === null
            ? "None"
            : `${counts.fencersSucceeded} succeeded, ${counts.fencersFailed} failed, ${counts.fencersUnattempted} unattempted of ${counts.fencersAttempted} attempted`}
        </Typography>
        <Typography level="body-sm">Compositions</Typography>
        <Typography level="body-sm">
          {counts === null
            ? "None"
            : `${counts.compositionsComplete} complete, ${counts.compositionsUnavailable} unavailable, ${counts.compositionsNotCaptured} not captured`}
        </Typography>
        <Typography level="body-sm">British</Typography>
        <Typography level="body-sm">
          {counts === null
            ? "None"
            : `${counts.britishCaptured} captured, ${counts.britishLicenceAmbiguous} licence-ambiguous${counts.britishRankingsFlagDisabled ? ", flag disabled" : ""}`}
        </Typography>
        <Typography level="body-sm">Oldest / newest snapshot</Typography>
        <Typography level="body-sm">
          {s.oldestSnapshotAt === null && s.newestSnapshotAt === null
            ? "None"
            : `${s.oldestSnapshotAt === null ? "—" : formatDate(s.oldestSnapshotAt)} / ${s.newestSnapshotAt === null ? "—" : formatDate(s.newestSnapshotAt)}`}
        </Typography>
        {s.lastFailureReason !== null ? (
          <>
            <Typography level="body-sm">Latest failure</Typography>
            <Typography level="body-sm">{s.lastFailureReason}</Typography>
          </>
        ) : (
          <></>
        )}
      </FlexiTable>
    </Card>
  );
}

function AdminTasksPage() {
  const clerkAuth = useAuth();
  const [taskActions, setTaskActions] = useState<
    Record<
      string,
      | { status: "starting"; forceListRefresh: boolean; overrideCooldown: boolean }
      | { status: "running"; forceListRefresh: boolean; overrideCooldown: boolean }
      | { status: "error"; message: string }
    >
  >({});
  const tasks = useQuery(
    "admin_tasks",
    async () => {
      const token = await clerkAuth.getToken();
      return getAdminTasks(token);
    },
    {
      refetchInterval: 1000,
    },
  );

  useEffect(() => {
    if (tasks.data === undefined) {
      return;
    }

    setTaskActions((actions) => {
      const completedTaskIds = Object.keys(actions).filter((id) => {
        const action = actions[id];
        if (action.status !== "running") {
          return false;
        }

        return !tasks.data.some(
          (task) =>
            (task.short_name === id ||
              (action.overrideCooldown && task.short_name === UNIFIED_CATALOG_OVERRIDE_TASK)) &&
            task.running === true,
        );
      });
      if (completedTaskIds.length === 0) {
        return actions;
      }

      const nextActions = { ...actions };
      completedTaskIds.forEach((id) => delete nextActions[id]);
      return nextActions;
    });
  }, [tasks.data]);

  if (tasks.data === undefined) {
    return <div>Loading...</div>;
  }

  const runNow = async (
    id: string,
    options?: { forceListRefresh?: boolean; overrideCooldown?: boolean },
  ) => {
    const forceListRefresh = options?.forceListRefresh === true;
    const overrideCooldown = options?.overrideCooldown === true;
    setTaskActions((actions) => ({
      ...actions,
      [id]: { status: "starting", forceListRefresh, overrideCooldown },
    }));
    try {
      const token = await clerkAuth.getToken();
      await startAdminTask(id, options, token);
      const refreshedTasks = await tasks.refetch();
      const taskIsRunning = refreshedTasks.data?.some(
        (task) =>
          (task.short_name === id ||
            (overrideCooldown && task.short_name === UNIFIED_CATALOG_OVERRIDE_TASK)) &&
          task.running === true,
      );
      setTaskActions((actions) => {
        const action = actions[id];
        if (action === undefined || action.status !== "starting") {
          return actions;
        }

        if (!taskIsRunning) {
          const nextActions = { ...actions };
          delete nextActions[id];
          return nextActions;
        }

        return {
          ...actions,
          [id]: { status: "running", forceListRefresh, overrideCooldown },
        };
      });
    } catch (error) {
      setTaskActions((actions) => ({
        ...actions,
        [id]: {
          status: "error",
          message: error instanceof globalThis.Error ? error.message : "Unable to start task.",
        },
      }));
    }
  };

  return (
    <>
      <Stack direction="column" spacing={1}>
        <FencingTrackerStatusCard />
        <UnifiedRankingsStatusCard />
        <StandingsHistoryStatusCard />
        <Card>
          <Typography level="title-md">Background tasks</Typography>
          {tasks.data
            .filter((t) => t.short_name !== UNIFIED_CATALOG_OVERRIDE_TASK)
            .map((t) => {
              const taskAction = taskActions[t.short_name];
              const taskActionIsPending =
                taskAction?.status === "starting" || taskAction?.status === "running";
              const runNowIsRunning =
                taskActionIsPending && !taskAction.forceListRefresh && !taskAction.overrideCooldown;
              const refreshListIsRunning = taskActionIsPending && taskAction.forceListRefresh;
              const overrideIsRunning = taskActionIsPending && taskAction.overrideCooldown;

              return (
                <Accordion key={t.short_name} defaultExpanded={true}>
                  <AccordionSummary>
                    <Stack direction="row" spacing={1}>
                      <Typography level="title-sm">{t.description}</Typography>
                    </Stack>
                  </AccordionSummary>
                  <AccordionDetails>
                    <Stack direction="row" spacing={1} alignItems="center">
                      <Button
                        onClick={(e) => {
                          e.stopPropagation();
                          runNow(t.short_name);
                        }}
                        variant="plain"
                        size="sm"
                        disabled={t.running === true || taskActionIsPending}
                        startDecorator={
                          runNowIsRunning ? <CircularProgress size="sm" /> : <PlayArrow />
                        }
                      >
                        Run Now
                      </Button>
                      {FORCE_LIST_REFRESH_TASKS.has(t.short_name) && (
                        <Button
                          onClick={(e) => {
                            e.stopPropagation();
                            runNow(t.short_name, { forceListRefresh: true });
                          }}
                          variant="outlined"
                          size="sm"
                          disabled={t.running === true || taskActionIsPending}
                          startDecorator={
                            refreshListIsRunning ? <CircularProgress size="sm" /> : undefined
                          }
                        >
                          Run + Refresh List
                        </Button>
                      )}
                      {t.short_name === UNIFIED_CATALOG_REFRESH_TASK && (
                        <Button
                          onClick={(e) => {
                            e.stopPropagation();
                            runNow(t.short_name, { overrideCooldown: true });
                          }}
                          variant="outlined"
                          color="warning"
                          size="sm"
                          disabled={t.running === true || taskActionIsPending}
                          startDecorator={
                            overrideIsRunning ? <CircularProgress size="sm" /> : undefined
                          }
                        >
                          Run Now (Override Cooldown)
                        </Button>
                      )}
                    </Stack>
                    {taskAction?.status === "error" && (
                      <Typography level="body-sm" color="danger">
                        Failed to start task: {taskAction.message}
                      </Typography>
                    )}
                    {t.running === true &&
                      t.running_since !== null &&
                      t.running_since !== undefined && (
                        <Typography level="body-sm">
                          Running for: {elapsedTimeFromStart(t.running_since)}
                        </Typography>
                      )}
                    {t.next_time !== null && (
                      <Typography level="body-sm">Next run: {formatDate(t.next_time)}</Typography>
                    )}
                    <Divider />
                    {t.history.length > 0 && (
                      <FlexiTable columns={[{}, {}, {}]}>
                        {t.history.flatMap((h) => [
                          <Typography key={h.started}>{formatDate(h.started)}</Typography>,
                          <Typography key={h.ended}>
                            {elapsedTimeSeconds(h.started, h.ended)}s
                          </Typography>,
                          <Typography key={h.success.toString()}>
                            {h.success === true && (
                              <Stack direction="row" alignItems="center">
                                <CheckCircle color="success" />
                                &nbsp;
                                <Typography color="success">Ran successfully</Typography>
                              </Stack>
                            )}
                            {h.success === false && (
                              <Stack direction="row" alignItems="center">
                                <Error color="error" />
                                &nbsp;
                                <Typography color="danger">Failed: {h.error_message}</Typography>
                              </Stack>
                            )}
                          </Typography>,
                        ])}
                      </FlexiTable>
                    )}
                  </AccordionDetails>
                </Accordion>
              );
            })}
        </Card>
      </Stack>
    </>
  );
}

function AdminCachePage() {
  const clerkAuth = useAuth();
  const summaryQuery = useQuery<RedisCacheSummary, Error>(
    ["admin_cache_summary"],
    async () => {
      const token = await clerkAuth.getToken();
      return getAdminCacheSummary(token);
    },
    { refetchOnWindowFocus: false },
  );

  const keys = summaryQuery.data?.keys ?? [];
  const errorMessage = summaryQuery.error ? summaryQuery.error.message : null;

  const flushCache = async () => {
    const token = await clerkAuth.getToken();
    await flushAdminCache(token);
    summaryQuery.refetch();
  };

  return (
    <Stack spacing={2}>
      <Stack direction="row" alignItems="center" justifyContent="space-between">
        <Typography level="title-md">Redis Cache</Typography>
        <Stack direction="row" spacing={1}>
          <Button
            size="sm"
            variant="outlined"
            onClick={() => summaryQuery.refetch()}
            disabled={summaryQuery.isFetching}
          >
            Refresh
          </Button>
          <Button size="sm" color="danger" onClick={flushCache}>
            Clear Cache
          </Button>
        </Stack>
      </Stack>

      {errorMessage && (
        <ErrorStateCard
          title="Couldn't load cache"
          message={errorMessage}
          onRetry={() => summaryQuery.refetch()}
        />
      )}

      {summaryQuery.isLoading || summaryQuery.isFetching ? <LinearProgress /> : null}

      {!summaryQuery.isLoading && keys.length === 0 && !summaryQuery.error ? (
        <Typography level="body-sm">No keys found in Redis.</Typography>
      ) : null}

      {keys.map((summary) => (
        <CacheKeyAccordion key={summary.name} summary={summary} />
      ))}
    </Stack>
  );
}

function CacheKeyAccordion({ summary }: { summary: RedisCacheKeySummary }) {
  const [expanded, setExpanded] = useState<boolean>(false);
  const clerkAuth = useAuth();
  const keyQuery = useQuery<RedisCacheKeyDetail, Error>(
    ["admin_cache_key", summary.name],
    async () => {
      const token = await clerkAuth.getToken();
      return getAdminCacheKey(summary.name, token);
    },
    { enabled: expanded, refetchOnWindowFocus: false },
  );

  const kind = keyQuery.data?.kind ?? summary.kind;
  const length = keyQuery.data?.length ?? summary.length;
  const lengthLabel = formatLength(kind, length);
  const entries = keyQuery.data?.entries ?? [];

  return (
    <Accordion expanded={expanded} onChange={(_, value) => setExpanded(value)}>
      <AccordionSummary>
        <Stack direction="row" spacing={1} alignItems="center">
          <Typography level="title-sm">{summary.name}</Typography>
          <Chip size="sm" variant="soft" color="neutral">
            {kind}
          </Chip>
          {lengthLabel && (
            <Chip size="sm" variant="soft" color="primary">
              {lengthLabel}
            </Chip>
          )}
        </Stack>
      </AccordionSummary>
      <AccordionDetails>
        <Stack spacing={1.5}>
          {expanded && keyQuery.isFetching ? <LinearProgress /> : null}

          {expanded && keyQuery.error ? (
            <Typography level="body-sm" color="danger">
              Failed to load key: {keyQuery.error.message}
            </Typography>
          ) : null}

          {expanded && !keyQuery.isLoading && !keyQuery.error ? (
            entries.length === 0 ? (
              <Typography level="body-sm">No entries.</Typography>
            ) : (
              <Stack spacing={1}>
                {entries.map((entry, idx) => (
                  <CacheEntryCard key={entry.field ?? `${summary.name}-${idx}`} entry={entry} />
                ))}
              </Stack>
            )
          ) : null}

          {expanded && !keyQuery.isLoading ? (
            <Button
              size="sm"
              variant="outlined"
              onClick={() => keyQuery.refetch()}
              disabled={keyQuery.isFetching}
              sx={{ alignSelf: "flex-start" }}
            >
              Refresh key
            </Button>
          ) : null}
        </Stack>
      </AccordionDetails>
    </Accordion>
  );
}

function CacheEntryCard({ entry }: { entry: RedisCacheEntry }) {
  const body =
    entry.json !== null ? (JSON.stringify(entry.json, null, 2) ?? entry.preview) : entry.preview;

  return (
    <Card variant="outlined" sx={{ p: 1 }}>
      {entry.field && (
        <Typography level="body-sm" sx={{ fontFamily: "var(--joy-fontFamily-code, monospace)" }}>
          {entry.field}
        </Typography>
      )}
      <Typography
        level="body-xs"
        component="pre"
        sx={{
          fontFamily: "var(--joy-fontFamily-code, monospace)",
          whiteSpace: "pre-wrap",
          overflowX: "auto",
          m: 0,
        }}
      >
        {body}
      </Typography>
    </Card>
  );
}

function formatLength(kind: string, length: number | null) {
  if (length === null) {
    return null;
  }

  if (kind === "string") {
    return `${length} ${length === 1 ? "byte" : "bytes"}`;
  }

  return `${length} ${length === 1 ? "entry" : "entries"}`;
}

function AdminCachesPage() {
  const clerkAuth = useAuth();
  const cachesQuery = useQuery<CacheSummaryEntry[], Error>(
    ["admin_caches"],
    async () => {
      const token = await clerkAuth.getToken();
      return getAdminCaches(token);
    },
    { refetchOnWindowFocus: false },
  );

  const caches = cachesQuery.data ?? [];

  return (
    <Stack spacing={2}>
      <Stack direction="row" alignItems="center" justifyContent="space-between">
        <Typography level="title-md">Named Caches</Typography>
        <Button
          size="sm"
          variant="outlined"
          onClick={() => cachesQuery.refetch()}
          disabled={cachesQuery.isFetching}
        >
          Refresh
        </Button>
      </Stack>
      <Typography level="body-sm">
        Invalidate stale entries by cache name and key (e.g. a fencer&apos;s USA Fencing id) once
        you know a fix has landed but existing entries haven&apos;t expired yet. This only clears
        entries — reads still go through the same cache lookup and re-fetch on a miss, they are
        never bypassed.
      </Typography>

      {cachesQuery.error && (
        <ErrorStateCard
          title="Couldn't load caches"
          message={cachesQuery.error.message}
          onRetry={() => cachesQuery.refetch()}
        />
      )}
      {cachesQuery.isLoading ? <LinearProgress /> : null}

      {caches.map((cache) => (
        <CacheRegistryCard
          key={cache.name}
          cache={cache}
          onInvalidated={() => cachesQuery.refetch()}
          onRefreshCounts={async () => {
            await cachesQuery.refetch();
          }}
        />
      ))}
    </Stack>
  );
}

function CacheRegistryCard({
  cache,
  onInvalidated,
  onRefreshCounts,
}: {
  cache: CacheSummaryEntry;
  onInvalidated: () => void;
  onRefreshCounts: () => Promise<void>;
}) {
  const clerkAuth = useAuth();
  const [key, setKey] = useState("");
  const [entry, setEntry] = useState<CacheEntryDetail | null>(null);
  const [checking, setChecking] = useState(false);
  const [checkError, setCheckError] = useState<string | null>(null);
  const [invalidating, setInvalidating] = useState(false);
  const [invalidateError, setInvalidateError] = useState<string | null>(null);
  const [lastResult, setLastResult] = useState<InvalidateCacheResult | null>(null);
  const [confirmingAll, setConfirmingAll] = useState(false);
  const [refreshingCount, setRefreshingCount] = useState(false);

  const startConfirmingAll = async () => {
    setRefreshingCount(true);
    try {
      await onRefreshCounts();
    } finally {
      setRefreshingCount(false);
    }
    setConfirmingAll(true);
  };

  const checkEntry = async () => {
    const trimmed = key.trim();
    if (!trimmed) return;
    setChecking(true);
    setCheckError(null);
    try {
      const token = await clerkAuth.getToken();
      setEntry(await getAdminCacheEntry(cache.name, trimmed, token));
    } catch (e) {
      setCheckError((e as Error).message);
      setEntry(null);
    } finally {
      setChecking(false);
    }
  };

  const invalidateKey = async () => {
    const trimmed = key.trim();
    if (!trimmed) return;
    setInvalidating(true);
    setInvalidateError(null);
    try {
      const token = await clerkAuth.getToken();
      const result = await invalidateAdminCache(cache.name, { key: trimmed }, token);
      setLastResult(result);
      setEntry(null);
      onInvalidated();
    } catch (e) {
      setInvalidateError((e as Error).message);
    } finally {
      setInvalidating(false);
    }
  };

  const invalidateAll = async () => {
    setInvalidating(true);
    setInvalidateError(null);
    try {
      const token = await clerkAuth.getToken();
      const result = await invalidateAdminCache(cache.name, { confirmed: true }, token);
      setLastResult(result);
      setConfirmingAll(false);
      onInvalidated();
    } catch (e) {
      setInvalidateError((e as Error).message);
    } finally {
      setInvalidating(false);
    }
  };

  return (
    <Card variant="outlined">
      <Stack spacing={1.5}>
        <Stack direction="row" spacing={1} alignItems="center" flexWrap="wrap">
          <Typography level="title-sm" sx={{ fontFamily: "var(--joy-fontFamily-code, monospace)" }}>
            {cache.name}
          </Typography>
          <Chip size="sm" variant="soft" color="neutral">
            TTL {formatTtl(cache.ttlSeconds)}
          </Chip>
          <Chip size="sm" variant="soft" color={cache.refresh ? "warning" : "success"}>
            {cache.refresh ? "sliding refresh" : "fixed TTL"}
          </Chip>
          <Chip size="sm" variant="soft" color="primary">
            {cache.entryCount} {cache.entryCount === 1 ? "entry" : "entries"}
          </Chip>
        </Stack>
        <Typography level="body-sm">{cache.description}</Typography>

        <Stack direction="row" spacing={1} alignItems="center" flexWrap="wrap">
          <input
            type="text"
            value={key}
            onChange={(e) => setKey(e.target.value)}
            placeholder="Key (e.g. a USA Fencing id)"
            style={{
              padding: "4px 8px",
              fontSize: "13px",
              flex: "1 1 220px",
              maxWidth: 260,
              border: "1px solid #ccc",
              borderRadius: 4,
            }}
          />
          <Button
            size="sm"
            variant="outlined"
            onClick={checkEntry}
            disabled={!key.trim() || checking}
          >
            {checking ? "Checking..." : "Check entry"}
          </Button>
          <Button
            size="sm"
            color="danger"
            variant="soft"
            onClick={invalidateKey}
            disabled={!key.trim() || invalidating}
          >
            Invalidate key
          </Button>
        </Stack>

        {checkError && (
          <Typography level="body-xs" color="danger">
            {checkError}
          </Typography>
        )}
        {entry && (
          <Card variant="soft" sx={{ p: 1 }}>
            {!entry.found ? (
              <Typography level="body-sm">No cached entry for this key.</Typography>
            ) : (
              <Stack spacing={0.5}>
                <Typography level="body-sm" color={entry.decodeError ? "danger" : undefined}>
                  {entry.decodeError
                    ? "Did not decode (likely a poisoned/stale value from a schema change) — showing the raw stored value:"
                    : `Age: ${entry.ageSeconds !== null ? formatAge(entry.ageSeconds) : "unknown"}`}
                </Typography>
                <Typography
                  level="body-xs"
                  component="pre"
                  sx={{
                    fontFamily: "var(--joy-fontFamily-code, monospace)",
                    whiteSpace: "pre-wrap",
                    overflowX: "auto",
                    m: 0,
                  }}
                >
                  {entry.decodeError ? String(entry.value) : JSON.stringify(entry.value, null, 2)}
                </Typography>
              </Stack>
            )}
          </Card>
        )}

        {invalidateError && (
          <Typography level="body-xs" color="danger">
            {invalidateError}
          </Typography>
        )}
        {lastResult && (
          <Chip size="sm" variant="soft" color="success">
            Invalidated {lastResult.entriesInvalidated}{" "}
            {lastResult.entriesInvalidated === 1 ? "entry" : "entries"} ({lastResult.scope})
          </Chip>
        )}

        <Divider />

        {!confirmingAll ? (
          <Button
            size="sm"
            color="danger"
            variant="outlined"
            onClick={startConfirmingAll}
            disabled={refreshingCount}
            sx={{ alignSelf: "flex-start" }}
          >
            {refreshingCount
              ? "Refreshing count..."
              : `Invalidate entire cache (${cache.entryCount})`}
          </Button>
        ) : (
          <Card color="danger" variant="soft">
            <Stack spacing={1}>
              <Typography level="body-sm">
                This drops all {cache.entryCount} cached{" "}
                {cache.entryCount === 1 ? "entry" : "entries"} for <code>{cache.name}</code> at
                once. Every one of those reads will then miss and re-fetch, bursting load against
                this cache&apos;s source — a rate-limited third party (FencingTracker, USA Fencing)
                or the primary datastore — invalidate a single key instead when you only need to fix
                one entry. Staging and production share this cache, so this also wipes both
                environments&apos; warm entries.
              </Typography>
              <Stack direction="row" spacing={1}>
                <Button size="sm" color="danger" onClick={invalidateAll} disabled={invalidating}>
                  {invalidating ? "Invalidating..." : `Yes, invalidate all ${cache.entryCount}`}
                </Button>
                <Button size="sm" variant="plain" onClick={() => setConfirmingAll(false)}>
                  Cancel
                </Button>
              </Stack>
            </Stack>
          </Card>
        )}
      </Stack>
    </Card>
  );
}

function formatTtl(seconds: number) {
  if (seconds % 86400 === 0) return `${seconds / 86400}d`;
  if (seconds % 3600 === 0) return `${seconds / 3600}h`;
  if (seconds % 60 === 0) return `${seconds / 60}m`;
  return `${seconds}s`;
}

function formatAge(seconds: number) {
  if (seconds < 60) return `${seconds}s`;
  if (seconds < 3600) return `${Math.round(seconds / 60)}m`;
  if (seconds < 86400) return `${Math.round(seconds / 3600)}h`;
  return `${Math.round(seconds / 86400)}d`;
}

function elapsedTimeSeconds(start: string, end: string) {
  return Math.round((new Date(end).getTime() - new Date(start).getTime()) / 1000);
}

function elapsedTimeFromStart(start: string) {
  const diffMs = Date.now() - new Date(start).getTime();
  const totalSeconds = Math.max(Math.floor(diffMs / 1000), 0);
  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;

  if (hours > 0) {
    return `${hours}h ${minutes}m ${seconds}s`;
  }
  if (minutes > 0) {
    return `${minutes}m ${seconds}s`;
  }
  return `${seconds}s`;
}

function formatDate(date: string) {
  const d = new Date(date);
  return d.toLocaleString();
}

