function UserCapabilitiesEditor({ user, onUpdate }: { user: User; onUpdate: () => void }) {
  const clerkAuth = useAuth();
  const availableCapabilities = UserCapabilities.filter((c) => !user.capabilities.includes(c));

  const removeCapability = async (capability: UserCapability) => {
    const newCapabilities = user.capabilities.filter((c) => c !== capability);
    const token = await clerkAuth.getToken();
    await setUserCapabilities(user.id, newCapabilities, token);
    onUpdate();
  };

  const addCapability = async (capability: UserCapability) => {
    const newCapabilities = [...user.capabilities, capability];
    const token = await clerkAuth.getToken();
    await setUserCapabilities(user.id, newCapabilities, token);
    onUpdate();
  };

  return (
    <Stack direction="row" spacing={0.5} flexWrap="wrap" alignItems="center">
      {user.capabilities.map((capability) => (
        <Chip
          key={capability}
          size="sm"
          variant="soft"
          endDecorator={<ChipDelete onDelete={() => removeCapability(capability)} />}
        >
          {capability}
        </Chip>
      ))}
      {availableCapabilities.length > 0 && (
        <Dropdown>
          <MenuButton
            slots={{ root: IconButton }}
            slotProps={{ root: { size: "sm", variant: "outlined" } }}
          >
            <Add fontSize="small" />
          </MenuButton>
          <Menu size="sm">
            {availableCapabilities.map((capability) => (
              <MenuItem key={capability} onClick={() => addCapability(capability)}>
                {capability}
              </MenuItem>
            ))}
          </Menu>
        </Dropdown>
      )}
      {user.capabilities.length === 0 &&
        availableCapabilities.length === UserCapabilities.length && (
          <Typography level="body-xs" sx={{ fontStyle: "italic", mr: 0.5 }}>
            None
          </Typography>
        )}
    </Stack>
  );
}

function UserGroupsEditor({ user, onUpdate }: { user: User; onUpdate: () => void }) {
  const clerkAuth = useAuth();
  const [isAdding, setIsAdding] = useState(false);
  const [newGroup, setNewGroup] = useState("");

  const removeGroup = async (group: string) => {
    const newGroups = user.groups.filter((g) => g !== group);
    const token = await clerkAuth.getToken();
    await setUserGroups(user.id, newGroups, token);
    onUpdate();
  };

  const addGroup = async () => {
    if (!newGroup.trim()) return;
    const newGroups = [...user.groups, newGroup.trim()];
    const token = await clerkAuth.getToken();
    await setUserGroups(user.id, newGroups, token);
    setNewGroup("");
    setIsAdding(false);
    onUpdate();
  };

  return (
    <Stack direction="row" spacing={0.5} flexWrap="wrap" alignItems="center">
      {user.groups.map((group) => (
        <Chip
          key={group}
          size="sm"
          variant="soft"
          color="primary"
          endDecorator={<ChipDelete onDelete={() => removeGroup(group)} />}
        >
          {group}
        </Chip>
      ))}
      {!isAdding ? (
        <IconButton size="sm" variant="outlined" onClick={() => setIsAdding(true)}>
          <Add fontSize="small" />
        </IconButton>
      ) : (
        <Stack direction="row" spacing={0.5} alignItems="center">
          <input
            type="text"
            value={newGroup}
            onChange={(e) => setNewGroup(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter") addGroup();
              if (e.key === "Escape") {
                setIsAdding(false);
                setNewGroup("");
              }
            }}
            placeholder="Group"
            style={{
              padding: "4px 8px",
              fontSize: "12px",
              width: "70px",
              border: "1px solid #ccc",
              borderRadius: "4px",
            }}
            autoFocus
          />
          <IconButton size="sm" variant="soft" color="success" onClick={addGroup}>
            ✓
          </IconButton>
          <IconButton
            size="sm"
            variant="plain"
            onClick={() => {
              setIsAdding(false);
              setNewGroup("");
            }}
          >
            ×
          </IconButton>
        </Stack>
      )}
      {user.groups.length === 0 && !isAdding && (
        <Typography level="body-xs" sx={{ fontStyle: "italic", mr: 0.5 }}>
          None
        </Typography>
      )}
    </Stack>
  );
}

function AdminGroupsPage() {
  const clerkAuth = useAuth();
  const [newGroupName, setNewGroupName] = useState("");
  const [isAddingGroup, setIsAddingGroup] = useState(false);

  const usersQuery = useQuery(
    ["admin_users"],
    async () => {
      const token = await clerkAuth.getToken();
      return getAdminUsers(token);
    },
    { refetchOnWindowFocus: false },
  );

  if (usersQuery.isLoading) {
    return (
      <Stack spacing={2}>
        <Typography level="title-md">Groups</Typography>
        <LinearProgress />
      </Stack>
    );
  }

  if (usersQuery.error) {
    return (
      <Stack spacing={2}>
        <Typography level="title-md">Groups</Typography>
        <ErrorStateCard
          title="Couldn't load groups"
          message={(usersQuery.error as Error).message}
          onRetry={() => usersQuery.refetch()}
        />
      </Stack>
    );
  }

  const users = usersQuery.data || [];

  // Build a map of group name -> users in that group
  const groupsMap = new Map<string, User[]>();
  for (const user of users) {
    for (const group of user.groups) {
      if (!groupsMap.has(group)) {
        groupsMap.set(group, []);
      }
      groupsMap.get(group)!.push(user);
    }
  }

  // Sort groups alphabetically
  const groupNames = Array.from(groupsMap.keys()).sort();

  // Users not in any group (for adding to new groups)
  const getUsersNotInGroup = (groupName: string) =>
    users.filter((u) => !u.groups.includes(groupName));

  const addUserToGroup = async (userId: string, groupName: string) => {
    const user = users.find((u) => u.id === userId);
    if (!user) return;
    const newGroups = [...user.groups, groupName];
    const token = await clerkAuth.getToken();
    await setUserGroups(userId, newGroups, token);
    usersQuery.refetch();
  };

  const removeUserFromGroup = async (userId: string, groupName: string) => {
    const user = users.find((u) => u.id === userId);
    if (!user) return;
    const newGroups = user.groups.filter((g) => g !== groupName);
    const token = await clerkAuth.getToken();
    await setUserGroups(userId, newGroups, token);
    usersQuery.refetch();
  };

  const createGroup = () => {
    if (!newGroupName.trim()) return;
    // Group is created implicitly when we add the first user
    // For now, just add it to the UI - it will show as empty
    setNewGroupName("");
    setIsAddingGroup(false);
  };

  return (
    <Stack spacing={2}>
      <Stack direction="row" alignItems="center" justifyContent="space-between">
        <Typography level="title-md">Groups</Typography>
        <Stack direction="row" spacing={1}>
          <Button
            size="sm"
            variant="outlined"
            onClick={() => usersQuery.refetch()}
            disabled={usersQuery.isFetching}
          >
            Refresh
          </Button>
        </Stack>
      </Stack>

      {groupNames.length === 0 && !isAddingGroup ? (
        <Card>
          <Stack spacing={2}>
            <Typography level="body-sm">No groups found. Create a group to get started.</Typography>
            <Button
              size="sm"
              variant="soft"
              startDecorator={<Add />}
              onClick={() => setIsAddingGroup(true)}
              sx={{ alignSelf: "flex-start" }}
            >
              Create Group
            </Button>
          </Stack>
        </Card>
      ) : (
        <>
          {groupNames.map((groupName) => (
            <GroupAccordion
              key={groupName}
              groupName={groupName}
              usersInGroup={groupsMap.get(groupName) || []}
              usersNotInGroup={getUsersNotInGroup(groupName)}
              onAddUser={(userId) => addUserToGroup(userId, groupName)}
              onRemoveUser={(userId) => removeUserFromGroup(userId, groupName)}
            />
          ))}

          {isAddingGroup ? (
            <Card variant="outlined">
              <Stack direction="row" spacing={1} alignItems="center">
                <Typography level="body-sm">New group name:</Typography>
                <input
                  type="text"
                  value={newGroupName}
                  onChange={(e) => setNewGroupName(e.target.value)}
                  onKeyDown={(e) => {
                    if (e.key === "Enter" && newGroupName.trim()) {
                      // Add group by showing it in accordion (empty)
                      groupsMap.set(newGroupName.trim(), []);
                      setNewGroupName("");
                      setIsAddingGroup(false);
                      // Force re-render
                      usersQuery.refetch();
                    }
                    if (e.key === "Escape") {
                      setIsAddingGroup(false);
                      setNewGroupName("");
                    }
                  }}
                  placeholder="Group name"
                  style={{
                    padding: "4px 8px",
                    fontSize: "14px",
                    width: "150px",
                    border: "1px solid #ccc",
                    borderRadius: "4px",
                  }}
                  autoFocus
                />
                <Button
                  size="sm"
                  variant="soft"
                  color="success"
                  disabled={!newGroupName.trim()}
                  onClick={createGroup}
                >
                  Create
                </Button>
                <Button
                  size="sm"
                  variant="plain"
                  onClick={() => {
                    setIsAddingGroup(false);
                    setNewGroupName("");
                  }}
                >
                  Cancel
                </Button>
              </Stack>
            </Card>
          ) : (
            <Button
              size="sm"
              variant="soft"
              startDecorator={<Add />}
              onClick={() => setIsAddingGroup(true)}
              sx={{ alignSelf: "flex-start" }}
            >
              Create Group
            </Button>
          )}
        </>
      )}
    </Stack>
  );
}

function GroupAccordion({
  groupName,
  usersInGroup,
  usersNotInGroup,
  onAddUser,
  onRemoveUser,
}: {
  groupName: string;
  usersInGroup: User[];
  usersNotInGroup: User[];
  onAddUser: (userId: string) => void;
  onRemoveUser: (userId: string) => void;
}) {
  const [expanded, setExpanded] = useState(false);

  return (
    <Accordion expanded={expanded} onChange={(_, value) => setExpanded(value)}>
      <AccordionSummary>
        <Stack direction="row" spacing={1} alignItems="center">
          <Chip size="sm" variant="soft" color="primary">
            {groupName}
          </Chip>
          <Typography level="body-sm">
            {usersInGroup.length} {usersInGroup.length === 1 ? "user" : "users"}
          </Typography>
        </Stack>
      </AccordionSummary>
      <AccordionDetails>
        <Stack spacing={1}>
          {usersInGroup.length === 0 ? (
            <Typography level="body-sm" sx={{ fontStyle: "italic" }}>
              No users in this group
            </Typography>
          ) : (
            <Stack spacing={0.5}>
              {usersInGroup.map((user) => (
                <Stack key={user.id} direction="row" spacing={1} alignItems="center">
                  <Chip
                    size="sm"
                    variant="outlined"
                    endDecorator={<ChipDelete onDelete={() => onRemoveUser(user.id)} />}
                  >
                    {user.primaryUser.name || user.primaryUser.email}
                  </Chip>
                </Stack>
              ))}
            </Stack>
          )}

          {usersNotInGroup.length > 0 && (
            <Dropdown>
              <MenuButton size="sm" variant="soft" startDecorator={<Add fontSize="small" />}>
                Add User
              </MenuButton>
              <Menu size="sm" sx={{ maxHeight: "300px", overflow: "auto" }}>
                {usersNotInGroup.map((user) => (
                  <MenuItem key={user.id} onClick={() => onAddUser(user.id)}>
                    {user.primaryUser.name || user.primaryUser.email}
                  </MenuItem>
                ))}
              </Menu>
            </Dropdown>
          )}
        </Stack>
      </AccordionDetails>
    </Accordion>
  );
}

