const FORCE_LIST_REFRESH_TASKS = new Set(["usaf_sync", "rebuild_standings_index"]);
const UNIFIED_CATALOG_REFRESH_TASK = "refresh_unified_catalog";
const UNIFIED_CATALOG_OVERRIDE_TASK = "refresh_unified_catalog_override";

function FencingTrackerStatusCard() {
  const clerkAuth = useAuth();
  const status = useQuery(
    "admin_fencingtracker",
    async () => {
      const token = await clerkAuth.getToken();
      return getFencingTrackerStatus(token);
    },
    {
      refetchInterval: 5000,
    },
  );

  if (status.data === undefined) {
    return null;
  }

  const s = status.data;

  return (
    <Card>
      <Typography level="title-md">FencingTracker egress</Typography>
      <Stack direction="row" spacing={1} alignItems="center">
        {s.cooldown_active ? (
          <Chip color="danger" variant="soft">
            Throttle cooldown active
          </Chip>
        ) : (
          <Chip color="success" variant="soft">
            Healthy
          </Chip>
        )}
        {s.cooldown_active && s.cooldown_until !== null && (
          <Typography level="body-sm">
            Paused until {new Date(s.cooldown_until * 1000).toLocaleString()}
          </Typography>
        )}
        {s.timeout_cooldown_active && (
          <Chip color="warning" variant="soft">
            Timeout cooldown active (background only)
          </Chip>
        )}
        {s.timeout_cooldown_active && s.timeout_cooldown_until !== null && (
          <Typography level="body-sm">
            Paused until {new Date(s.timeout_cooldown_until * 1000).toLocaleString()}
          </Typography>
        )}
      </Stack>
      <FlexiTable columns={[{}, {}]}>
        <Typography level="body-sm">Rate ceiling</Typography>
        <Typography level="body-sm">{s.max_requests_per_second} req/s</Typography>
        <Typography level="body-sm">Consecutive 403/429s</Typography>
        <Typography level="body-sm">{s.error_streak}</Typography>
        <Typography level="body-sm">Consecutive timeouts</Typography>
        <Typography level="body-sm">{s.timeout_error_streak}</Typography>
        <Typography level="body-sm">Background requests (this hour)</Typography>
        <Typography level="body-sm">
          {s.background_requests_this_hour}
          {s.background_max_requests_per_hour > 0
            ? ` / ${s.background_max_requests_per_hour}`
            : " (unlimited)"}
        </Typography>
      </FlexiTable>
    </Card>
  );
}

function UnifiedRankingsStatusCard() {
  const clerkAuth = useAuth();
  const status = useQuery(
    "admin_unified_rankings",
    async () => {
      const token = await clerkAuth.getToken();
      return getUnifiedRankingsRefreshStatus(token);
    },
    {
      refetchInterval: 5000,
    },
  );

  if (status.data === undefined) {
    return null;
  }

  const s = status.data;
  const hasFailedSinceLastSuccess =
    s.lastFailureAt !== null && (s.lastSuccessAt === null || s.lastFailureAt > s.lastSuccessAt);
  const sweep = s.identitySweep;

  return (
    <Card>
      <Typography level="title-md">Unified rankings catalog</Typography>
      <Stack direction="row" spacing={1} alignItems="center">
        {hasFailedSinceLastSuccess ? (
          <Chip color="danger" variant="soft">
            Latest refresh failed
          </Chip>
        ) : s.lastSuccessAt !== null ? (
          <Chip color="success" variant="soft">
            Last refresh succeeded
          </Chip>
        ) : (
          <Chip color="warning" variant="soft">
            No snapshot published
          </Chip>
        )}
      </Stack>
      <FlexiTable columns={[{}, {}]}>
        <Typography level="body-sm">Last attempt</Typography>
        <Typography level="body-sm">
          {s.lastAttemptAt === null ? "Never" : formatDate(s.lastAttemptAt)}
        </Typography>
        <Typography level="body-sm">Cooldown override used</Typography>
        <Typography level="body-sm">
          {s.lastAttemptUsedCooldownOverride === true ? "Yes" : "No"}
        </Typography>
        <Typography level="body-sm">Last successful snapshot</Typography>
        <Typography level="body-sm">
          {s.lastSuccessSnapshotId === null ? "None" : s.lastSuccessSnapshotId}
        </Typography>
        {s.lastFailureReason !== null ? (
          <>
            <Typography level="body-sm">Latest failure</Typography>
            <Typography level="body-sm">{s.lastFailureReason}</Typography>
          </>
        ) : (
          <></>
        )}
        {/* Publishing does not wait for identity resolution, so "last refresh
            succeeded" above does not mean the catalog is fully resolved. This
            row is what keeps that from reading as an all-clear. */}
        <Typography level="body-sm">Identity resolution</Typography>
        <Typography level="body-sm">
          {sweep.catalogRows === 0
            ? "Not yet swept"
            : `${sweep.resolvedRows} of ${sweep.catalogRows} rows` +
              ` (${Math.round((100 * sweep.resolvedRows) / sweep.catalogRows)}%)` +
              `, ${sweep.pendingRows} pending`}
        </Typography>
        <Typography level="body-sm">Last identity sweep</Typography>
        <Typography level="body-sm">
          {sweep.lastRunAt === null
            ? "Never"
            : `${formatDate(sweep.lastRunAt)} — ${sweep.lastRunResolved} resolved` +
              ` of ${sweep.lastRunLookups} lookups (${sweep.lastRunStopReason ?? "unknown"})`}
        </Typography>
      </FlexiTable>
    </Card>
  );
}

function StandingsHistoryStatusCard() {
