        <Typography level="body-sm">
          {s.oldestSnapshotAt === null && s.newestSnapshotAt === null
            ? "None"
            : `${s.oldestSnapshotAt === null ? "—" : formatDate(s.oldestSnapshotAt)} / ${s.newestSnapshotAt === null ? "—" : formatDate(s.newestSnapshotAt)}`}
        </Typography>
        {s.lastFailureReason !== null ? (
          <>
            <Typography level="body-sm">Latest failure</Typography>
            <Typography level="body-sm">{s.lastFailureReason}</Typography>
          </>
        ) : (
          <></>
        )}
      </FlexiTable>
    </Card>
  );
}

function AdminTasksPage() {
  const clerkAuth = useAuth();
  const [taskActions, setTaskActions] = useState<
    Record<
      string,
      | { status: "starting"; forceListRefresh: boolean; overrideCooldown: boolean }
      | { status: "running"; forceListRefresh: boolean; overrideCooldown: boolean }
      | { status: "error"; message: string }
    >
  >({});
  const tasks = useQuery(
    "admin_tasks",
    async () => {
      const token = await clerkAuth.getToken();
      return getAdminTasks(token);
    },
    {
      refetchInterval: 1000,
    },
  );

  useEffect(() => {
    if (tasks.data === undefined) {
      return;
    }

    setTaskActions((actions) => {
      const completedTaskIds = Object.keys(actions).filter((id) => {
        const action = actions[id];
        if (action.status !== "running") {
          return false;
        }

        return !tasks.data.some(
          (task) =>
            (task.short_name === id ||
              (action.overrideCooldown && task.short_name === UNIFIED_CATALOG_OVERRIDE_TASK)) &&
            task.running === true,
        );
      });
      if (completedTaskIds.length === 0) {
        return actions;
      }

      const nextActions = { ...actions };
      completedTaskIds.forEach((id) => delete nextActions[id]);
      return nextActions;
    });
  }, [tasks.data]);

  if (tasks.data === undefined) {
    return <div>Loading...</div>;
  }

  const runNow = async (
    id: string,
    options?: { forceListRefresh?: boolean; overrideCooldown?: boolean },
  ) => {
    const forceListRefresh = options?.forceListRefresh === true;
    const overrideCooldown = options?.overrideCooldown === true;
    setTaskActions((actions) => ({
      ...actions,
      [id]: { status: "starting", forceListRefresh, overrideCooldown },
    }));
    try {
      const token = await clerkAuth.getToken();
      await startAdminTask(id, options, token);
      const refreshedTasks = await tasks.refetch();
      const taskIsRunning = refreshedTasks.data?.some(
        (task) =>
          (task.short_name === id ||
            (overrideCooldown && task.short_name === UNIFIED_CATALOG_OVERRIDE_TASK)) &&
          task.running === true,
      );
      setTaskActions((actions) => {
        const action = actions[id];
        if (action === undefined || action.status !== "starting") {
          return actions;
        }

        if (!taskIsRunning) {
          const nextActions = { ...actions };
          delete nextActions[id];
          return nextActions;
        }

        return {
          ...actions,
          [id]: { status: "running", forceListRefresh, overrideCooldown },
        };
      });
    } catch (error) {
      setTaskActions((actions) => ({
        ...actions,
        [id]: {
          status: "error",
          message: error instanceof globalThis.Error ? error.message : "Unable to start task.",
        },
      }));
    }
  };

  return (
    <>
      <Stack direction="column" spacing={1}>
        <FencingTrackerStatusCard />
        <UnifiedRankingsStatusCard />
        <StandingsHistoryStatusCard />
        <Card>
          <Typography level="title-md">Background tasks</Typography>
          {tasks.data
            .filter((t) => t.short_name !== UNIFIED_CATALOG_OVERRIDE_TASK)
            .map((t) => {
              const taskAction = taskActions[t.short_name];
              const taskActionIsPending =
                taskAction?.status === "starting" || taskAction?.status === "running";
              const runNowIsRunning =
                taskActionIsPending && !taskAction.forceListRefresh && !taskAction.overrideCooldown;
              const refreshListIsRunning = taskActionIsPending && taskAction.forceListRefresh;
              const overrideIsRunning = taskActionIsPending && taskAction.overrideCooldown;

              return (
                <Accordion key={t.short_name} defaultExpanded={true}>
                  <AccordionSummary>
                    <Stack direction="row" spacing={1}>
                      <Typography level="title-sm">{t.description}</Typography>
                    </Stack>
                  </AccordionSummary>
                  <AccordionDetails>
                    <Stack direction="row" spacing={1} alignItems="center">
                      <Button
                        onClick={(e) => {
                          e.stopPropagation();
                          runNow(t.short_name);
                        }}
                        variant="plain"
                        size="sm"
                        disabled={t.running === true || taskActionIsPending}
                        startDecorator={
                          runNowIsRunning ? <CircularProgress size="sm" /> : <PlayArrow />
                        }
                      >
                        Run Now
                      </Button>
                      {FORCE_LIST_REFRESH_TASKS.has(t.short_name) && (
                        <Button
                          onClick={(e) => {
                            e.stopPropagation();
                            runNow(t.short_name, { forceListRefresh: true });
                          }}
                          variant="outlined"
                          size="sm"
