                        </Button>
                      )}
                      {t.short_name === UNIFIED_CATALOG_REFRESH_TASK && (
                        <Button
                          onClick={(e) => {
                            e.stopPropagation();
                            runNow(t.short_name, { overrideCooldown: true });
                          }}
                          variant="outlined"
                          color="warning"
                          size="sm"
                          disabled={t.running === true || taskActionIsPending}
                          startDecorator={
                            overrideIsRunning ? <CircularProgress size="sm" /> : undefined
                          }
                        >
                          Run Now (Override Cooldown)
                        </Button>
                      )}
                    </Stack>
                    {taskAction?.status === "error" && (
                      <Typography level="body-sm" color="danger">
                        Failed to start task: {taskAction.message}
                      </Typography>
                    )}
                    {t.running === true &&
                      t.running_since !== null &&
                      t.running_since !== undefined && (
                        <Typography level="body-sm">
                          Running for: {elapsedTimeFromStart(t.running_since)}
                        </Typography>
                      )}
                    {t.next_time !== null && (
                      <Typography level="body-sm">Next run: {formatDate(t.next_time)}</Typography>
                    )}
                    <Divider />
                    {t.history.length > 0 && (
                      <FlexiTable columns={[{}, {}, {}]}>
                        {t.history.flatMap((h) => [
                          <Typography key={h.started}>{formatDate(h.started)}</Typography>,
                          <Typography key={h.ended}>
                            {elapsedTimeSeconds(h.started, h.ended)}s
                          </Typography>,
                          <Typography key={h.success.toString()}>
                            {h.success === true && (
                              <Stack direction="row" alignItems="center">
                                <CheckCircle color="success" />
                                &nbsp;
                                <Typography color="success">Ran successfully</Typography>
                              </Stack>
                            )}
                            {h.success === false && (
                              <Stack direction="row" alignItems="center">
                                <Error color="error" />
                                &nbsp;
                                <Typography color="danger">Failed: {h.error_message}</Typography>
                              </Stack>
                            )}
                          </Typography>,
                        ])}
                      </FlexiTable>
                    )}
                  </AccordionDetails>
                </Accordion>
              );
            })}
        </Card>
      </Stack>
    </>
  );
}

