function formatLength(kind: string, length: number | null) {
  if (length === null) {
    return null;
  }

  if (kind === "string") {
    return `${length} ${length === 1 ? "byte" : "bytes"}`;
  }

  return `${length} ${length === 1 ? "entry" : "entries"}`;
}

