function CacheRegistryCard({
  cache,
  onInvalidated,
  onRefreshCounts,
}: {
  cache: CacheSummaryEntry;
  onInvalidated: () => void;
  onRefreshCounts: () => Promise<void>;
}) {
  const clerkAuth = useAuth();
  const [key, setKey] = useState("");
  const [entry, setEntry] = useState<CacheEntryDetail | null>(null);
  const [checking, setChecking] = useState(false);
  const [checkError, setCheckError] = useState<string | null>(null);
  const [invalidating, setInvalidating] = useState(false);
  const [invalidateError, setInvalidateError] = useState<string | null>(null);
  const [lastResult, setLastResult] = useState<InvalidateCacheResult | null>(null);
  const [confirmingAll, setConfirmingAll] = useState(false);
  const [refreshingCount, setRefreshingCount] = useState(false);

  const startConfirmingAll = async () => {
    setRefreshingCount(true);
    try {
      await onRefreshCounts();
    } finally {
      setRefreshingCount(false);
    }
    setConfirmingAll(true);
  };

  const checkEntry = async () => {
    const trimmed = key.trim();
    if (!trimmed) return;
    setChecking(true);
    setCheckError(null);
    try {
      const token = await clerkAuth.getToken();
      setEntry(await getAdminCacheEntry(cache.name, trimmed, token));
    } catch (e) {
      setCheckError((e as Error).message);
      setEntry(null);
    } finally {
      setChecking(false);
    }
  };

  const invalidateKey = async () => {
    const trimmed = key.trim();
    if (!trimmed) return;
    setInvalidating(true);
    setInvalidateError(null);
    try {
      const token = await clerkAuth.getToken();
      const result = await invalidateAdminCache(cache.name, { key: trimmed }, token);
      setLastResult(result);
      setEntry(null);
      onInvalidated();
    } catch (e) {
      setInvalidateError((e as Error).message);
    } finally {
      setInvalidating(false);
    }
  };

  const invalidateAll = async () => {
    setInvalidating(true);
    setInvalidateError(null);
    try {
      const token = await clerkAuth.getToken();
      const result = await invalidateAdminCache(cache.name, { confirmed: true }, token);
      setLastResult(result);
      setConfirmingAll(false);
      onInvalidated();
    } catch (e) {
      setInvalidateError((e as Error).message);
    } finally {
      setInvalidating(false);
    }
  };

  return (
    <Card variant="outlined">
      <Stack spacing={1.5}>
        <Stack direction="row" spacing={1} alignItems="center" flexWrap="wrap">
          <Typography level="title-sm" sx={{ fontFamily: "var(--joy-fontFamily-code, monospace)" }}>
            {cache.name}
          </Typography>
          <Chip size="sm" variant="soft" color="neutral">
            TTL {formatTtl(cache.ttlSeconds)}
          </Chip>
          <Chip size="sm" variant="soft" color={cache.refresh ? "warning" : "success"}>
            {cache.refresh ? "sliding refresh" : "fixed TTL"}
          </Chip>
          <Chip size="sm" variant="soft" color="primary">
            {cache.entryCount} {cache.entryCount === 1 ? "entry" : "entries"}
          </Chip>
        </Stack>
        <Typography level="body-sm">{cache.description}</Typography>

        <Stack direction="row" spacing={1} alignItems="center" flexWrap="wrap">
          <input
            type="text"
            value={key}
            onChange={(e) => setKey(e.target.value)}
            placeholder="Key (e.g. a USA Fencing id)"
            style={{
              padding: "4px 8px",
              fontSize: "13px",
              flex: "1 1 220px",
              maxWidth: 260,
              border: "1px solid #ccc",
              borderRadius: 4,
            }}
          />
          <Button
            size="sm"
            variant="outlined"
            onClick={checkEntry}
            disabled={!key.trim() || checking}
          >
            {checking ? "Checking..." : "Check entry"}
          </Button>
          <Button
            size="sm"
            color="danger"
            variant="soft"
            onClick={invalidateKey}
            disabled={!key.trim() || invalidating}
          >
            Invalidate key
          </Button>
        </Stack>

        {checkError && (
          <Typography level="body-xs" color="danger">
            {checkError}
          </Typography>
        )}
        {entry && (
          <Card variant="soft" sx={{ p: 1 }}>
            {!entry.found ? (
              <Typography level="body-sm">No cached entry for this key.</Typography>
            ) : (
              <Stack spacing={0.5}>
                <Typography level="body-sm" color={entry.decodeError ? "danger" : undefined}>
                  {entry.decodeError
                    ? "Did not decode (likely a poisoned/stale value from a schema change) — showing the raw stored value:"
                    : `Age: ${entry.ageSeconds !== null ? formatAge(entry.ageSeconds) : "unknown"}`}
                </Typography>
                <Typography
                  level="body-xs"
                  component="pre"
                  sx={{
                    fontFamily: "var(--joy-fontFamily-code, monospace)",
                    whiteSpace: "pre-wrap",
                    overflowX: "auto",
                    m: 0,
                  }}
                >
                  {entry.decodeError ? String(entry.value) : JSON.stringify(entry.value, null, 2)}
                </Typography>
              </Stack>
            )}
          </Card>
        )}

        {invalidateError && (
          <Typography level="body-xs" color="danger">
            {invalidateError}
          </Typography>
        )}
        {lastResult && (
          <Chip size="sm" variant="soft" color="success">
            Invalidated {lastResult.entriesInvalidated}{" "}
            {lastResult.entriesInvalidated === 1 ? "entry" : "entries"} ({lastResult.scope})
          </Chip>
        )}

        <Divider />

        {!confirmingAll ? (
          <Button
            size="sm"
            color="danger"
            variant="outlined"
            onClick={startConfirmingAll}
            disabled={refreshingCount}
            sx={{ alignSelf: "flex-start" }}
          >
            {refreshingCount
              ? "Refreshing count..."
              : `Invalidate entire cache (${cache.entryCount})`}
          </Button>
        ) : (
          <Card color="danger" variant="soft">
            <Stack spacing={1}>
              <Typography level="body-sm">
                This drops all {cache.entryCount} cached{" "}
                {cache.entryCount === 1 ? "entry" : "entries"} for <code>{cache.name}</code> at
                once. Every one of those reads will then miss and re-fetch, bursting load against
                this cache&apos;s source — a rate-limited third party (FencingTracker, USA Fencing)
                or the primary datastore — invalidate a single key instead when you only need to fix
                one entry. Staging and production share this cache, so this also wipes both
                environments&apos; warm entries.
              </Typography>
              <Stack direction="row" spacing={1}>
                <Button size="sm" color="danger" onClick={invalidateAll} disabled={invalidating}>
                  {invalidating ? "Invalidating..." : `Yes, invalidate all ${cache.entryCount}`}
                </Button>
                <Button size="sm" variant="plain" onClick={() => setConfirmingAll(false)}>
                  Cancel
                </Button>
              </Stack>
            </Stack>
          </Card>
        )}
      </Stack>
    </Card>
  );
}

function formatTtl(seconds: number) {
  if (seconds % 86400 === 0) return `${seconds / 86400}d`;
  if (seconds % 3600 === 0) return `${seconds / 3600}h`;
  if (seconds % 60 === 0) return `${seconds / 60}m`;
  return `${seconds}s`;
}

function formatAge(seconds: number) {
  if (seconds < 60) return `${seconds}s`;
  if (seconds < 3600) return `${Math.round(seconds / 60)}m`;
  if (seconds < 86400) return `${Math.round(seconds / 3600)}h`;
  return `${Math.round(seconds / 86400)}d`;
}

function elapsedTimeSeconds(start: string, end: string) {
  return Math.round((new Date(end).getTime() - new Date(start).getTime()) / 1000);
}

function elapsedTimeFromStart(start: string) {
  const diffMs = Date.now() - new Date(start).getTime();
  const totalSeconds = Math.max(Math.floor(diffMs / 1000), 0);
  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;

  if (hours > 0) {
    return `${hours}h ${minutes}m ${seconds}s`;
  }
  if (minutes > 0) {
    return `${minutes}m ${seconds}s`;
  }
  return `${seconds}s`;
}

function formatDate(date: string) {
  const d = new Date(date);
  return d.toLocaleString();
}

