  // Users not in any group (for adding to new groups)
  const getUsersNotInGroup = (groupName: string) =>
    users.filter((u) => !u.groups.includes(groupName));

  const addUserToGroup = async (userId: string, groupName: string) => {
    const user = users.find((u) => u.id === userId);
    if (!user) return;
    const newGroups = [...user.groups, groupName];
    const token = await clerkAuth.getToken();
    await setUserGroups(userId, newGroups, token);
    usersQuery.refetch();
  };

  const removeUserFromGroup = async (userId: string, groupName: string) => {
    const user = users.find((u) => u.id === userId);
    if (!user) return;
    const newGroups = user.groups.filter((g) => g !== groupName);
    const token = await clerkAuth.getToken();
    await setUserGroups(userId, newGroups, token);
    usersQuery.refetch();
  };

  const createGroup = () => {
    if (!newGroupName.trim()) return;
    // Group is created implicitly when we add the first user
    // For now, just add it to the UI - it will show as empty
    setNewGroupName("");
    setIsAddingGroup(false);
  };

  return (
    <Stack spacing={2}>
      <Stack direction="row" alignItems="center" justifyContent="space-between">
        <Typography level="title-md">Groups</Typography>
        <Stack direction="row" spacing={1}>
          <Button
            size="sm"
            variant="outlined"
            onClick={() => usersQuery.refetch()}
            disabled={usersQuery.isFetching}
          >
            Refresh
          </Button>
        </Stack>
      </Stack>

      {groupNames.length === 0 && !isAddingGroup ? (
        <Card>
          <Stack spacing={2}>
            <Typography level="body-sm">No groups found. Create a group to get started.</Typography>
            <Button
              size="sm"
              variant="soft"
              startDecorator={<Add />}
              onClick={() => setIsAddingGroup(true)}
              sx={{ alignSelf: "flex-start" }}
            >
              Create Group
            </Button>
          </Stack>
        </Card>
      ) : (
        <>
          {groupNames.map((groupName) => (
            <GroupAccordion
              key={groupName}
              groupName={groupName}
              usersInGroup={groupsMap.get(groupName) || []}
              usersNotInGroup={getUsersNotInGroup(groupName)}
              onAddUser={(userId) => addUserToGroup(userId, groupName)}
              onRemoveUser={(userId) => removeUserFromGroup(userId, groupName)}
            />
          ))}

          {isAddingGroup ? (
            <Card variant="outlined">
              <Stack direction="row" spacing={1} alignItems="center">
                <Typography level="body-sm">New group name:</Typography>
                <input
                  type="text"
                  value={newGroupName}
                  onChange={(e) => setNewGroupName(e.target.value)}
                  onKeyDown={(e) => {
                    if (e.key === "Enter" && newGroupName.trim()) {
                      // Add group by showing it in accordion (empty)
                      groupsMap.set(newGroupName.trim(), []);
                      setNewGroupName("");
                      setIsAddingGroup(false);
                      // Force re-render
                      usersQuery.refetch();
                    }
                    if (e.key === "Escape") {
                      setIsAddingGroup(false);
                      setNewGroupName("");
                    }
                  }}
                  placeholder="Group name"
                  style={{
                    padding: "4px 8px",
                    fontSize: "14px",
                    width: "150px",
                    border: "1px solid #ccc",
                    borderRadius: "4px",
                  }}
                  autoFocus
                />
                <Button
                  size="sm"
                  variant="soft"
                  color="success"
                  disabled={!newGroupName.trim()}
                  onClick={createGroup}
                >
                  Create
                </Button>
                <Button
                  size="sm"
                  variant="plain"
                  onClick={() => {
                    setIsAddingGroup(false);
                    setNewGroupName("");
                  }}
                >
                  Cancel
                </Button>
              </Stack>
            </Card>
          ) : (
            <Button
              size="sm"
              variant="soft"
              startDecorator={<Add />}
              onClick={() => setIsAddingGroup(true)}
              sx={{ alignSelf: "flex-start" }}
            >
              Create Group
            </Button>
          )}
        </>
      )}
    </Stack>
  );
}

function GroupAccordion({
  groupName,
  usersInGroup,
  usersNotInGroup,
  onAddUser,
  onRemoveUser,
}: {
  groupName: string;
  usersInGroup: User[];
  usersNotInGroup: User[];
  onAddUser: (userId: string) => void;
  onRemoveUser: (userId: string) => void;
}) {
  const [expanded, setExpanded] = useState(false);

  return (
    <Accordion expanded={expanded} onChange={(_, value) => setExpanded(value)}>
      <AccordionSummary>
        <Stack direction="row" spacing={1} alignItems="center">
          <Chip size="sm" variant="soft" color="primary">
            {groupName}
          </Chip>
          <Typography level="body-sm">
            {usersInGroup.length} {usersInGroup.length === 1 ? "user" : "users"}
          </Typography>
        </Stack>
      </AccordionSummary>
      <AccordionDetails>
        <Stack spacing={1}>
          {usersInGroup.length === 0 ? (
            <Typography level="body-sm" sx={{ fontStyle: "italic" }}>
              No users in this group
            </Typography>
          ) : (
            <Stack spacing={0.5}>
              {usersInGroup.map((user) => (
                <Stack key={user.id} direction="row" spacing={1} alignItems="center">
                  <Chip
                    size="sm"
                    variant="outlined"
                    endDecorator={<ChipDelete onDelete={() => onRemoveUser(user.id)} />}
                  >
                    {user.primaryUser.name || user.primaryUser.email}
                  </Chip>
                </Stack>
              ))}
            </Stack>
          )}

          {usersNotInGroup.length > 0 && (
            <Dropdown>
              <MenuButton size="sm" variant="soft" startDecorator={<Add fontSize="small" />}>
                Add User
              </MenuButton>
              <Menu size="sm" sx={{ maxHeight: "300px", overflow: "auto" }}>
                {usersNotInGroup.map((user) => (
                  <MenuItem key={user.id} onClick={() => onAddUser(user.id)}>
                    {user.primaryUser.name || user.primaryUser.email}
                  </MenuItem>
                ))}
              </Menu>
            </Dropdown>
          )}
        </Stack>
      </AccordionDetails>
    </Accordion>
  );
}

function AdminCapabilitiesPage() {
  const clerkAuth = useAuth();
  const configQuery = useQuery(
    ["admin_capability_config"],
    async () => {
      const token = await clerkAuth.getToken();
      return getCapabilityConfig(token);
    },
    { refetchOnWindowFocus: false },
  );

  const groupsQuery = useQuery(
    ["admin_groups"],
    async () => {
      const token = await clerkAuth.getToken();
      return getAdminGroups(token);
    },
    { refetchOnWindowFocus: false },
  );

  if (configQuery.isLoading) {
    return (
      <Stack spacing={2}>
        <Typography level="title-md">Capability Configuration</Typography>
        <LinearProgress />
      </Stack>
    );
  }

  if (configQuery.error) {
    return (
      <Stack spacing={2}>
        <Typography level="title-md">Capability Configuration</Typography>
        <ErrorStateCard
          title="Couldn't load capability configuration"
          message={(configQuery.error as Error).message}
          onRetry={() => configQuery.refetch()}
        />
      </Stack>
    );
  }

  const rollouts = configQuery.data?.capabilities || [];
  const availableGroups = groupsQuery.data?.map((g) => g.name) || [];

  const allCapabilities = [...UserCapabilities];

  return (
    <Stack spacing={2}>
      <Stack direction="row" alignItems="center" justifyContent="space-between">
        <Typography level="title-md">Capability Configuration</Typography>
        <Button
          size="sm"
          variant="outlined"
          onClick={() => configQuery.refetch()}
          disabled={configQuery.isFetching}
        >
          Refresh
        </Button>
      </Stack>
      <Typography level="body-sm">
        Configure how capabilities are rolled out to users. Explicit user capabilities always take
        priority over rollout configuration.
      </Typography>
      {allCapabilities.map((capability) => {
        const rollout = rollouts.find((r) => r.capability === capability);
        return (
          <CapabilityRolloutEditor
            key={capability}
            capability={capability}
            rollout={rollout}
            availableGroups={availableGroups}
            onUpdate={() => configQuery.refetch()}
          />
        );
      })}
    </Stack>
  );
}

function CapabilityRolloutEditor({
  capability,
  rollout,
  availableGroups,
  onUpdate,
}: {
  capability: UserCapability;
  rollout?: CapabilityRollout;
  availableGroups: string[];
  onUpdate: () => void;
}) {
  const clerkAuth = useAuth();
  const [expanded, setExpanded] = useState(false);
  const [percentage, setPercentage] = useState(rollout?.rolloutPercentage ?? 0);
  const [enabledForAll, setEnabledForAll] = useState(rollout?.enabledForAll ?? false);
  const [enabledGroups, setEnabledGroups] = useState<string[]>(rollout?.enabledGroups ?? []);
  const [disabledGroups, setDisabledGroups] = useState<string[]>(rollout?.disabledGroups ?? []);
  const [isSaving, setIsSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);

  // Administrator and Developer cannot have rollout percentage or enabled_for_all
  const isPrivileged = capability === "Administrator" || capability === "Developer";

  const hasChanges =
    percentage !== (rollout?.rolloutPercentage ?? 0) ||
    enabledForAll !== (rollout?.enabledForAll ?? false) ||
    JSON.stringify(enabledGroups) !== JSON.stringify(rollout?.enabledGroups ?? []) ||
    JSON.stringify(disabledGroups) !== JSON.stringify(rollout?.disabledGroups ?? []);

  const save = async () => {
    setIsSaving(true);
    setSaveSuccess(false);
    try {
      const token = await clerkAuth.getToken();
      await setCapabilityRollout(
        capability,
        {
          rolloutPercentage: percentage,
          enabledForAll,
          enabledGroups,
          disabledGroups,
        },
        token,
      );
      onUpdate();
      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 2000);
    } finally {
      setIsSaving(false);
    }
  };

  const resetChanges = () => {
    setPercentage(rollout?.rolloutPercentage ?? 0);
    setEnabledForAll(rollout?.enabledForAll ?? false);
    setEnabledGroups(rollout?.enabledGroups ?? []);
    setDisabledGroups(rollout?.disabledGroups ?? []);
  };

  const getStatusLabel = () => {
    if (enabledForAll) return "Enabled for all";
    if (percentage === 100) return "100% rollout";
    if (percentage > 0) return `${percentage}% rollout`;
    if (enabledGroups.length > 0) return `Groups: ${enabledGroups.join(", ")}`;
    return "Not configured";
  };

  return (
    <Accordion expanded={expanded} onChange={(_, value) => setExpanded(value)}>
      <AccordionSummary>
        <Stack direction="row" spacing={1} alignItems="center" sx={{ width: "100%" }}>
          <Typography level="title-sm" sx={{ flex: 1 }}>
            {capability}
          </Typography>
          <Chip
            size="sm"
            variant="soft"
            color={
              enabledForAll || percentage === 100
                ? "success"
                : percentage > 0 || enabledGroups.length > 0
                  ? "warning"
                  : "neutral"
            }
          >
            {getStatusLabel()}
          </Chip>
        </Stack>
      </AccordionSummary>
      <AccordionDetails>
        <Stack spacing={2}>
          {isPrivileged && (
            <Typography level="body-xs" sx={{ fontStyle: "italic" }}>
              This capability can only be assigned to specific users or groups.
            </Typography>
          )}

          {!isPrivileged && (
            <>
              <Stack direction="row" alignItems="center" spacing={2}>
                <Typography level="body-sm" sx={{ minWidth: "120px" }}>
                  Enabled for all:
                </Typography>
                <input
                  type="checkbox"
                  checked={enabledForAll}
                  onChange={(e) => setEnabledForAll(e.target.checked)}
                />
              </Stack>

              <Stack direction="row" alignItems="center" spacing={2}>
                <Typography level="body-sm" sx={{ minWidth: "120px" }}>
                  Rollout percentage:
                </Typography>
                <input
                  type="range"
                  min="0"
                  max="100"
                  value={percentage}
                  onChange={(e) => setPercentage(parseInt(e.target.value))}
                  style={{ flex: 1 }}
                />
                <Typography level="body-sm" sx={{ minWidth: "40px" }}>
                  {percentage}%
                </Typography>
              </Stack>
            </>
          )}

          <Stack direction="row" alignItems="flex-start" spacing={2}>
            <Typography level="body-sm" sx={{ minWidth: "120px" }}>
              Enabled groups:
            </Typography>
            <Stack direction="row" spacing={0.5} flexWrap="wrap" alignItems="center">
              {enabledGroups.length === 0 && (
                <Typography level="body-xs" sx={{ fontStyle: "italic", mr: 0.5 }}>
                  None
                </Typography>
              )}
              {enabledGroups.map((group) => (
                <Chip
                  key={group}
                  size="sm"
                  variant="soft"
                  color="success"
                  endDecorator={
                    <ChipDelete
                      onDelete={() => setEnabledGroups(enabledGroups.filter((g) => g !== group))}
                    />
                  }
                >
                  {group}
                </Chip>
              ))}
              {availableGroups.filter(
                (g) => !enabledGroups.includes(g) && !disabledGroups.includes(g),
              ).length > 0 && (
                <Dropdown>
                  <MenuButton
                    slots={{ root: IconButton }}
                    slotProps={{ root: { size: "sm", variant: "outlined" } }}
                  >
                    <Add fontSize="small" />
                  </MenuButton>
                  <Menu size="sm">
                    {availableGroups
                      .filter((g) => !enabledGroups.includes(g) && !disabledGroups.includes(g))
                      .map((group) => (
                        <MenuItem
                          key={group}
                          onClick={() => setEnabledGroups([...enabledGroups, group])}
                        >
                          {group}
                        </MenuItem>
                      ))}
                  </Menu>
                </Dropdown>
              )}
            </Stack>
          </Stack>

          <Stack direction="row" alignItems="flex-start" spacing={2}>
            <Typography level="body-sm" sx={{ minWidth: "120px" }}>
              Disabled groups:
            </Typography>
            <Stack direction="row" spacing={0.5} flexWrap="wrap" alignItems="center">
              {disabledGroups.length === 0 && (
                <Typography level="body-xs" sx={{ fontStyle: "italic", mr: 0.5 }}>
                  None
                </Typography>
              )}
              {disabledGroups.map((group) => (
                <Chip
                  key={group}
                  size="sm"
                  variant="soft"
                  color="danger"
                  endDecorator={
                    <ChipDelete
                      onDelete={() => setDisabledGroups(disabledGroups.filter((g) => g !== group))}
                    />
                  }
                >
                  {group}
                </Chip>
              ))}
              {availableGroups.filter(
                (g) => !enabledGroups.includes(g) && !disabledGroups.includes(g),
              ).length > 0 && (
                <Dropdown>
                  <MenuButton
                    slots={{ root: IconButton }}
                    slotProps={{ root: { size: "sm", variant: "outlined" } }}
                  >
                    <Add fontSize="small" />
                  </MenuButton>
                  <Menu size="sm">
                    {availableGroups
                      .filter((g) => !enabledGroups.includes(g) && !disabledGroups.includes(g))
                      .map((group) => (
                        <MenuItem
                          key={group}
                          onClick={() => setDisabledGroups([...disabledGroups, group])}
                        >
                          {group}
                        </MenuItem>
                      ))}
                  </Menu>
                </Dropdown>
              )}
            </Stack>
          </Stack>

          {(hasChanges || saveSuccess) && (
            <Stack direction="row" spacing={1} alignItems="center">
              {saveSuccess ? (
                <Chip size="sm" variant="soft" color="success" startDecorator={<CheckCircle />}>
                  Saved
                </Chip>
              ) : (
                <>
                  <Button size="sm" variant="solid" onClick={save} disabled={isSaving}>
                    {isSaving ? "Saving..." : "Save Changes"}
                  </Button>
                  <Button size="sm" variant="outlined" onClick={resetChanges} disabled={isSaving}>
                    Reset
                  </Button>
                </>
              )}
            </Stack>
          )}
        </Stack>
      </AccordionDetails>
    </Accordion>
  );
}

