import { Operation } from "rfc6902";
import { parseDate, parseEndDate } from "../util";
import { useQuery } from "react-query";
import { useAuth as useClerkAuth } from "@clerk/clerk-react";
import { del, get, patchJson, post, postJson, url } from "./http";

// Re-export HTTP utilities for backward compatibility
export { get, url };

export interface Tournament {
  id: string;
  idDetail: {
    ftlId: string | undefined;
    usafId: string | undefined;
    afId: string | undefined;
  };
  name: string;
  startDate: string | null;
  endDate: string | null;
  city: string | null;
  country: string | null;
  type: "RYC" | "Local" | "SYC" | "National" | "Regional" | null;
  events: Event[];
  timeline: null | TimelineItem[];
}

export function getTournamentDates(t: Tournament) {
  return [parseDate(t.startDate), parseEndDate(t.endDate)];
}

export function getEventDescription(e: Event) {
  let title = "";
  if (typeof e.classifier === "string") {
    title = e.classifier;
  } else {
    switch (e.classifier.category) {
      case "y8":
        title += "Y-8 ";
        break;
      case "y10":
        title += "Y-10 ";
        break;
      case "y12":
        title += "Y-12 ";
        break;
      case "y14":
        title += "Y-14 ";
        break;
      case "junior":
        title += "Junior ";
        break;
      case "cadet":
        title += "Cadet ";
        break;
      case "veteran":
        title += "Veteran ";
        break;
      case "division1":
        title += "Division I ";
        break;
      case "division1A":
        title += "Division IA ";
        break;
      case "division2":
        title += "Division II ";
        break;
      case "division3":
        title += "Division III ";
        break;
      default:
        title += e.classifier.category;
    }
    switch (e.classifier.gender) {
      case "mens":
        title += "Men's ";
        break;
      case "womens":
        title += "Women's ";
        break;
      case "mixed":
        title += "Mixed ";
        break;
    }
    switch (e.classifier.weapon) {
      case "sabre":
        title += "Sabre";
        break;
      case "foil":
        title += "Foil";
        break;
      case "epee":
        title += "Épée";
        break;
    }
  }
  return title;
}

interface TimelineItem {
  kind: TimelineKind;
  date: string;
}

type TimelineKind =
  | "RegistrationOpens"
  | "EntryDeadline"
  | "LateEntryDeadline"
  | "RatingChangeDeadline"
  | "TournamentStart"
  | "TournamentEnd";

export interface Fencer {
  id: string;
  idDetail: null | {
    usafId?: string;
  };
  name: string;
  birthYear?: number;
  firstCompetitionYear?: number;
  country?: string;
  currentClubName?: string;
  gender: "Male" | "Female" | null;
  currentRatings?: Ratings;
  standing?: Standing[];
  registrations?: Registration[];
  matchStats?: FencerMatchStats;
}

export interface FencerSearchResult {
  club: string;
  name: string;
  usafId: number;
  division: string | null;
}

interface Standing {
  category: Classifier;
  usaRegion: null | number;
  rank: number;
  isTied: boolean;
  points: string;
}

export function formatShortDisplay(s: Standing) {
  return `${s.usaRegion !== null ? "R" + s.usaRegion : ""}${getCategoryCode(s.category.category)} #${s.rank}`;
}

interface FencerMatchStats {
  wins: (string | number)[][];
  losses: (string | number)[][];
}

interface FencerWithMatchStats {
  matchStats?: FencerMatchStats | null;
}

export function getWins(trackedId: string, fencer: Fencer | FencerWithMatchStats) {
  if (fencer.matchStats !== undefined && fencer.matchStats !== null) {
    for (const s of fencer.matchStats.wins) {
      if (s[0] === trackedId) {
        return s[1] as number;
      }
    }
  }
  return 0;
}

export function getLosses(trackedId: string, fencer: Fencer | FencerWithMatchStats) {
  if (fencer.matchStats !== undefined && fencer.matchStats !== null) {
    for (const s of fencer.matchStats.losses) {
      if (s[0] === trackedId) {
        return s[1] as number;
      }
    }
  }
  return 0;
}

export function getFencerRating(fencer: Fencer | FencerWithMatchStats, weapon: Weapon) {
  if ("currentRatings" in fencer) {
    if (fencer.currentRatings != null) {
      let rating: Rating | null | undefined;
      switch (weapon) {
        case "epee":
          rating = fencer.currentRatings.epee;
          break;
        case "foil":
          rating = fencer.currentRatings.foil;
          break;
        case "sabre":
          rating = fencer.currentRatings.sabre;
          break;
      }

      const classification = rating?.classification;
      if (classification === undefined) {
        return null;
      }
      return classification;
    }
  }
  // TODO(@backend,2026-03-01): handle non-database fencers with rating metadata
  return null;
}

export interface EventPreferences {
  weapons: Weapon[];
  categories: EventCategory[];
  genders: Gender[];
  usaRegions: number[];
  /** Explicit event type codes (e.g., "Y14MS", "CDTWS"). When non-empty, takes precedence over legacy fields. */
  eventTypes?: string[];
}

interface UserPreferences {
  events: EventPreferences;
}

export function getClassifiersFromPreferences(preferences: EventPreferences | null | undefined) {
  const classifiers = [];
  if (preferences) {
    // If eventTypes is non-empty, use it as the source of truth
    if (preferences.eventTypes && preferences.eventTypes.length > 0) {
      for (const code of preferences.eventTypes) {
        const parsed = parseEventTypeCode(code);
        if (parsed) {
          classifiers.push({
            category: parsed.category,
            weapon: parsed.weapon,
            gender: parsed.gender,
            team: false,
          });
        }
      }
      return classifiers;
    }

    // Fall back to legacy Cartesian product behavior
    for (const category of preferences.categories) {
      for (const weapon of preferences.weapons) {
        for (const gender of preferences.genders) {
          classifiers.push({
            category,
            weapon,
            gender,
            team: false,
          });
        }
      }
    }
  }
  return classifiers;
}

export interface Ratings {
  foil: null | Rating;
  epee: null | Rating;
  sabre: null | Rating;
}

export interface Rating {
  classification: string;
  yearObtained: number;
  dateObtained: string;
}

export interface Registration {
  tournament_id: string;
  event_ids: string[];
}

export interface Event {
  id: null | string;
  idDetail: null | {
    usafId: string;
  };
  classifier: string | Classifier;
  date: null | string;
  matches: null | Match[];
  live: null | LiveEvent;
  startTime: null | string;
  endTime: null | string;
  status: null | string | PoolStatus;
  rating: null | EventRating;
  registeredFencers: null | number;
  totalSpots: null | number;
}

export function getEventWeapon(event: Event) {
  return (event.classifier as Classifier).weapon;
}

const eventRatings = [
  "A1",
  "A2",
  "A3",
  "A4",
  "B1",
  "B2",
  "B3",
  "C1",
  "C2",
  "C3",
  "D1",
  "E1",
  "NotRated",
];
export type EventRating = (typeof eventRatings)[number];

export interface PoolStatus {
  completedPools: number;
  totalPools: number;
}

export interface LiveEvent {
  fencers: LiveFencer[];
  pools: Pool[];
  elimination: null | Elimination;
}

export interface Elimination {
  rounds: EliminationRound[];
}

interface EliminationRound {
  matches: Match[];
}

interface LiveFencer {
