const weapons = ["sabre", "foil", "epee"] as const;
export type Weapon = (typeof weapons)[number];
export const Weapons = weapons;

const eventCategories = [
  "y8",
  "y10",
  "y12",
  "y14",
  "cadet",
  "junior",
  "senior",
  "adult",
  "veteran",
  "division1",
  "division1A",
  "division2",
  "division3",
] as const;
export type EventCategory = (typeof eventCategories)[number];
export const EventCategories = eventCategories;

const genders = ["mens", "womens", "mixed"] as const;
export type Gender = (typeof genders)[number];
export const Genders = genders;

const EventCategoryCodes: { [key: string]: EventCategory } = {
  Y8: "y8",
  Y10: "y10",
  Y12: "y12",
  Y14: "y14",
  CDT: "cadet",
  JNR: "junior",
  SNR: "senior",
  ADT: "adult",
  VET: "veteran",
  D1A: "division1A",
  DV1: "division1",
  DV2: "division2",
  DV3: "division3",
};

const GenderCodes: { [key: string]: Gender } = {
  M: "mens",
  W: "womens",
  X: "mixed",
};

const WeaponCodes: { [key: string]: Weapon } = {
  S: "sabre",
  F: "foil",
  E: "epee",
};
// Reverse mappings
const EventCategoryCodesReverse = Object.fromEntries(
  Object.entries(EventCategoryCodes).map(([code, category]) => [category, code]),
);

const GenderCodesReverse = Object.fromEntries(
  Object.entries(GenderCodes).map(([code, gender]) => [gender, code]),
);

const WeaponCodesReverse = Object.fromEntries(
  Object.entries(WeaponCodes).map(([code, weapon]) => [weapon, code]),
);

function parseEventString(s: string): [EventCategory, Gender, Weapon, number | null] {
  // List of event category codes sorted by length (longest first)
  const EventCategoryCodesList = Object.keys(EventCategoryCodes).sort(
    (a, b) => b.length - a.length,
  );

  let eventCategory: EventCategory | undefined;

  // Find the event category code at the start of the string
  for (const code of EventCategoryCodesList) {
    if (s.startsWith(code)) {
      eventCategory = EventCategoryCodes[code];
      s = s.slice(code.length);
      break;
    }
  }

  if (!eventCategory) {
    throw new Error("Invalid Event Category Code");
  }

  // Parse gender code
  const genderCode = s.charAt(0);
  const gender = GenderCodes[genderCode];
  if (!gender) {
    throw new Error("Invalid Gender Code");
  }
  s = s.slice(1);

  // Parse weapon code
  const weaponCode = s.charAt(0);
  const weapon = WeaponCodes[weaponCode];
  if (!weapon) {
    throw new Error("Invalid Weapon Code");
  }
  s = s.slice(1);

  // Parse region number if present
  let region: number | null = null;
  if (s.startsWith("R")) {
    s = s.slice(1);
    const match = s.match(/^(\d+)/);
    if (match) {
      region = parseInt(match[1], 10);
      s = s.slice(match[1].length);
    } else {
      throw new Error("Invalid Region Number");
    }
  }

  // Check for any extra characters
  if (s.length > 0) {
    throw new Error("Extra characters at the end of the string");
  }

  return [eventCategory, gender, weapon, region];
}

function buildEventString(
  eventCategory: EventCategory,
  gender: Gender,
  weapon: Weapon,
  region: number | null,
): string {
  // Get the codes from the reverse mappings
  const eventCategoryCode = EventCategoryCodesReverse[eventCategory];
  if (!eventCategoryCode) {
    throw new Error("Invalid Event Category");
  }

  const genderCode = GenderCodesReverse[gender];
  if (!genderCode) {
    throw new Error("Invalid Gender");
  }

  const weaponCode = WeaponCodesReverse[weapon];
  if (!weaponCode) {
    throw new Error("Invalid Weapon");
  }

  // Build the event string
  let eventString = eventCategoryCode + genderCode + weaponCode;

  // Append region if present
  if (region !== null) {
    if (!Number.isInteger(region) || region <= 0) {
      throw new Error("Invalid Region Number");
    }
    eventString += "R" + region;
  }

  return eventString;
}

/** Parses an event type code like "Y14MS" into its components. Returns null if invalid. */
export function parseEventTypeCode(
  code: string,
): { category: EventCategory; gender: Gender; weapon: Weapon } | null {
  try {
    const [category, gender, weapon] = parseEventString(code);
    return { category, gender, weapon };
  } catch {
    return null;
  }
}

/** Builds an event type code from components (without region). */
function buildEventTypeCode(category: EventCategory, gender: Gender, weapon: Weapon): string {
  return buildEventString(category, gender, weapon, null);
}

/** Display names for categories */
const CategoryDisplayNames: Record<EventCategory, string> = {
  y8: "Y8",
  y10: "Y10",
  y12: "Y12",
  y14: "Y14",
  cadet: "Cadet",
  junior: "Junior",
  senior: "Senior",
  adult: "Adult",
  veteran: "Veteran",
  division1: "Division I",
  division1A: "Division IA",
  division2: "Division II",
  division3: "Division III",
};

/** Display names for genders */
const GenderDisplayNames: Record<Gender, string> = {
  mens: "Mens",
  womens: "Womens",
  mixed: "Mixed",
};

/** Display names for weapons */
const WeaponDisplayNames: Record<Weapon, string> = {
  sabre: "Sabre",
  foil: "Foil",
  epee: "Epee",
};

/** Gets a human-readable display name for an event type code. */
export function getEventTypeDisplayName(code: string): string {
  const parsed = parseEventTypeCode(code);
  if (!parsed) {
    return code;
  }
  const categoryName = CategoryDisplayNames[parsed.category];
  const genderName = GenderDisplayNames[parsed.gender];
  const weaponName = WeaponDisplayNames[parsed.weapon];
  return `${categoryName} ${genderName} ${weaponName}`;
}

/** All valid event type codes (108 combinations: 12 categories × 3 genders × 3 weapons). */
let _allEventTypeCodes: string[] | null = null;
export function getAllEventTypeCodes(): string[] {
  if (_allEventTypeCodes === null) {
    _allEventTypeCodes = [];
    for (const category of EventCategories) {
      for (const gender of Genders) {
        for (const weapon of Weapons) {
          _allEventTypeCodes.push(buildEventTypeCode(category, gender, weapon));
        }
      }
    }
  }
  return _allEventTypeCodes;
}

export interface EventTypeSearchResult {
  code: string;
  displayName: string;
  category: EventCategory;
  gender: Gender;
  weapon: Weapon;
}

/** Normalizes text for search by lowercasing and removing punctuation */
function normalizeForSearch(text: string): string {
  return text.toLowerCase().replace(/[''`]/g, "").trim();
}

/**
 * Searches event types by query string.
 * Matches against code (e.g., "Y14MS") and display name words (e.g., "mens sabre").
 * @param query Search query
 * @param excludeCodes Codes to exclude from results (already selected)
 * @param limit Maximum number of results
 */
export function searchEventTypes(
  query: string,
  excludeCodes: Set<string> = new Set(),
  limit = 20,
): EventTypeSearchResult[] {
  const normalizedQuery = normalizeForSearch(query);
  if (!normalizedQuery) {
    return [];
  }

  const queryTerms = normalizedQuery.split(/\s+/);
  const results: Array<EventTypeSearchResult & { score: number }> = [];

  for (const code of getAllEventTypeCodes()) {
    if (excludeCodes.has(code)) {
      continue;
    }

    const parsed = parseEventTypeCode(code);
    if (!parsed) {
      continue;
    }

    const displayName = getEventTypeDisplayName(code);
    const lowerCode = code.toLowerCase();
    const normalizedDisplayName = normalizeForSearch(displayName);

    // Calculate match score
    let score = 0;

    // Exact code match (highest priority)
    if (lowerCode === normalizedQuery) {
      score = 1000;
    }
    // Code starts with query
    else if (lowerCode.startsWith(normalizedQuery)) {
      score = 500;
    }
    // Code contains query
    else if (lowerCode.includes(normalizedQuery)) {
      score = 200;
    }
    // All query terms match display name words
    else {
      const displayWords = normalizedDisplayName.split(/\s+/);
      let allTermsMatch = true;
      let termMatchCount = 0;

      for (const term of queryTerms) {
        const termMatches = displayWords.some(
          (word) => word.startsWith(term) || word.includes(term),
        );
        if (termMatches) {
          termMatchCount++;
        } else {
          allTermsMatch = false;
        }
      }

      if (allTermsMatch && termMatchCount > 0) {
        score = 100 + termMatchCount * 10;
      }
    }

    if (score > 0) {
      results.push({
        code,
        displayName,
        category: parsed.category,
        gender: parsed.gender,
        weapon: parsed.weapon,
        score,
      });
    }
  }

  // Sort by score descending, then by code
  results.sort((a, b) => {
    if (b.score !== a.score) {
      return b.score - a.score;
    }
    return a.code.localeCompare(b.code);
  });

  return results.slice(0, limit).map(({ score: _score, ...rest }) => rest);
}

