function getCategoryCode(category: EventCategory) {
  switch (category) {
    case "y8":
    case "y10":
    case "y12":
    case "y14":
      return category.toUpperCase();
    case "cadet":
      return "CDT";
    case "junior":
      return "JNR";
    case "senior":
      return "SNR";
    case "adult":
      return "ADT";
    case "veteran":
      return "VET";
    case "division1":
      return "DV1";
    case "division1A":
      return "D1A";
    case "division2":
      return "DV2";
    case "division3":
      return "DV3";
    default:
      return category;
  }
}

export function getEventCategoryCode(event: Event) {
  if (typeof event.classifier === "string") {
    return event.classifier as string;
  }
  return getCategoryCode((event.classifier as Classifier).category);
}

export function getCode(classifier: string | Classifier) {
  if (typeof classifier === "string") {
    return classifier;
  }
  const recognized = classifier as Classifier;
  let code = "";
  code += getCategoryCode(recognized.category);
  switch (recognized.gender) {
    case "mens":
      code += "M";
      break;
    case "womens":
      code += "W";
      break;
    case "mixed":
      code += "X";
      break;
  }

  switch (recognized.weapon) {
    case "epee":
      code += "E";
      break;
    case "foil":
      code += "F";
      break;
    case "sabre":
      code += "S";
      break;
  }

  return code;
}

