export async function searchFencers(query: string, clerkToken?: string | null) {
  const rawResults = await get<
    (Omit<FencerSearchResult, "usafId"> & {
      usaf_id?: number;
      usafId?: number;
    })[]
  >(`/api/v2/fencingtracker/fencers?query=${encodeURIComponent(query)}`, clerkToken);

  return rawResults
    .map((result) => ({
      ...result,
      usafId: normalizeUsafId(result.usafId ?? result.usaf_id),
    }))
    .filter((result): result is FencerSearchResult => result.usafId !== null);
}

function normalizeUsafId(id: number | string | undefined | null) {
  if (id == null) {
    return null;
  }

  const numeric = typeof id === "string" ? Number.parseInt(id, 10) : id;
  return Number.isFinite(numeric) ? numeric : null;
}

