export function getEventDescription(e: Event) {
  let title = "";
  if (typeof e.classifier === "string") {
    title = e.classifier;
  } else {
    switch (e.classifier.category) {
      case "y8":
        title += "Y-8 ";
        break;
      case "y10":
        title += "Y-10 ";
        break;
      case "y12":
        title += "Y-12 ";
        break;
      case "y14":
        title += "Y-14 ";
        break;
      case "junior":
        title += "Junior ";
        break;
      case "cadet":
        title += "Cadet ";
        break;
      case "veteran":
        title += "Veteran ";
        break;
      case "division1":
        title += "Division I ";
        break;
      case "division1A":
        title += "Division IA ";
        break;
      case "division2":
        title += "Division II ";
        break;
      case "division3":
        title += "Division III ";
        break;
      default:
        title += e.classifier.category;
    }
    switch (e.classifier.gender) {
      case "mens":
        title += "Men's ";
        break;
      case "womens":
        title += "Women's ";
        break;
      case "mixed":
        title += "Mixed ";
        break;
    }
    switch (e.classifier.weapon) {
      case "sabre":
        title += "Sabre";
        break;
      case "foil":
        title += "Foil";
        break;
      case "epee":
        title += "Épée";
        break;
    }
  }
  return title;
}

