}

interface Standing {
  category: Classifier;
  usaRegion: null | number;
  rank: number;
  isTied: boolean;
  points: string;
}

/// Gets the fencer for a participant, or returns null.
export function getFencerParticipant(participant: Participant | null) {
  // Historical name retained for compatibility with existing callers.
  if (participant?.individual != null) {
    if (typeof participant.individual.fencer !== "string") {
      return participant.individual.fencer as Fencer;
    }
  }
  return null;
}

export function isFencer(participant: Participant, fencerId: string) {
  return getFencerParticipant(participant)?.id === fencerId;
}

export interface Individual {
  fencer: string | Fencer;
  score: null | number;
  outcome: null | "win" | "lose" | "withdraw";
}

function getCategoryCode(category: EventCategory) {
  switch (category) {
    case "y8":
    case "y10":
    case "y12":
    case "y14":
      return category.toUpperCase();
    case "cadet":
      return "CDT";
    case "junior":
      return "JNR";
    case "senior":
      return "SNR";
    case "adult":
      return "ADT";
    case "veteran":
      return "VET";
    case "division1":
      return "DV1";
    case "division1A":
      return "D1A";
    case "division2":
      return "DV2";
    case "division3":
      return "DV3";
    default:
      return category;
  }
}

export function getEventCategoryCode(event: Event) {
  if (typeof event.classifier === "string") {
    return event.classifier as string;
  }
  return getCategoryCode((event.classifier as Classifier).category);
}

export function getCode(classifier: string | Classifier) {
  if (typeof classifier === "string") {
    return classifier;
  }
  const recognized = classifier as Classifier;
  let code = "";
  code += getCategoryCode(recognized.category);
  switch (recognized.gender) {
    case "mens":
      code += "M";
      break;
    case "womens":
      code += "W";
      break;
    case "mixed":
      code += "X";
      break;
  }

  switch (recognized.weapon) {
    case "epee":
      code += "E";
      break;
    case "foil":
      code += "F";
      break;
    case "sabre":
      code += "S";
      break;
  }

  return code;
}

