import { putJson } from "../http";

/** Mirrors the server-side bound: docs/design-docs/british-fencing-rankings-as-a-standings-source.md. */
export const MAX_BRITISH_FENCING_MEMBERSHIP_ID_LENGTH = 32;

/**
 * Sets or clears the shared British Fencing membership id for a fencer the
 * caller tracks. Last write wins; every other tracker of that fencer sees
 * the new value. Pass `null` (or an empty string) to clear it.
 */
export async function setBritishFencingMembership(
  fencerId: string,
  membershipId: string | null,
  clerkToken?: string | null,
) {
  await putJson<void>(
    `/api/v3/user/tracked-fencers/${encodeURIComponent(fencerId)}/british-fencing-membership`,
    { membershipId },
    clerkToken,
  );
}
